export type HttpHost = CyrusHost & {
  /** Load the host.info snapshot (statePath, role table). Call once at boot; safe to call again to refresh. */
  warm(): Promise<HostInfo>;
  /** Low-level call (tests, diagnostics). */
  call<T>(name: HostCallName, args?: Record<string, unknown>): Promise<T>;
};

export function createHttpHost(o: HttpHostOptions): HttpHost {
  if (!/^https?:\/\//.test(o.baseUrl)) throw new Error("createHttpHost: baseUrl must be an http(s) URL");
  const base = new URL(o.baseUrl.replace(/\/+$/, "") + "/");
  const doFetch = o.fetch ?? fetch;
  const timeoutMs = o.timeoutMs ?? 8000, retries = o.retries ?? 2, backoff = o.backoffMs ?? 200;
  const now = o.now ?? Date.now;
  const sleep = o.sleep ?? ((ms: number) => new Promise<void>((r) => setTimeout(r, ms)));
  const ttl = o.settingsTtlMs ?? 15_000;
  let info: HostInfo | null = null;
  const cache = new Map<string, { at: number; v: unknown }>();

  async function call<T>(name: HostCallName, args: Record<string, unknown> = {}): Promise<T> {
    const kind = HOST_CALLS[name];
    const url = new URL(encodeURIComponent(name), base);
    const json = toWireJson(args);
    if (kind === "read") url.searchParams.set("a", json);
    const body = kind === "read" ? "" : json;
    const idem = kind === "write" ? randomBytes(16).toString("base64url") : null;
    let last: HostHttpError | null = null;
    let retryAfterMs = 0;
    for (let attempt = 0; attempt <= retries; attempt++) {
      if (attempt) await sleep(retryAfterMs ? Math.min(5000, retryAfterMs) : backoff * 2 ** (attempt - 1) + Math.floor(Math.random() * backoff));
      retryAfterMs = 0;
      // re-signed every attempt: a fresh nonce + timestamp (the server refuses a replayed nonce)
      const headers: Record<string, string> = {
        ...signRequest({ keyId: o.keyId, secret: o.secret, method: kind === "read" ? "GET" : "POST", pathWithQuery: url.pathname + url.search, body, nowMs: now() }),
        accept: "application/json",
        ...(idem ? { "idempotency-key": idem, "content-type": "application/json" } : {}),
      };
      const ac = new AbortController();
      const timer = setTimeout(() => ac.abort(), timeoutMs);
      try {
        const res = await doFetch(url, { method: kind === "read" ? "GET" : "POST", headers, body: kind === "read" ? undefined : body, signal: ac.signal });
        const text = await res.text();
        let parsed: HostReply | null = null;
        try { parsed = JSON.parse(text) as HostReply; } catch { /* not JSON */ }
        if (res.ok && parsed?.ok) return decodeWire(parsed.value) as T;
        const e = new HostHttpError(res.status, parsed && !parsed.ok ? parsed.error.code : "bad_reply", parsed && !parsed.ok ? parsed.error.message : `HTTP ${res.status}`, name);
        const ra = Number(res.headers.get("retry-after"));
        if (Number.isFinite(ra) && ra > 0) retryAfterMs = ra * 1000;
        if (!RETRY_STATUS.has(res.status)) throw e;
        last = e;
      } catch (e) {
        if (e instanceof HostHttpError && !RETRY_STATUS.has(e.status)) throw e;
        if (!(e instanceof HostHttpError)) last = new HostHttpError(0, ac.signal.aborted ? "timeout" : "network", ac.signal.aborted ? `no answer within ${timeoutMs} ms` : (e as Error).message, name);
      } finally { clearTimeout(timer); }
    }
    throw last ?? new HostHttpError(0, "network", "failed", name);
  }

  async function cached<T>(key: string, load: () => Promise<T>): Promise<T> {
    const hit = cache.get(key);
    if (ttl > 0 && hit && now() - hit.at < ttl) return hit.v as T;
    const v = await load();
    if (ttl > 0) cache.set(key, { at: now(), v });
    return v;
  }
  const invalidate = () => cache.clear();

  const sessions = new WeakMap<HostGuestFs, string>();
  const sessionOf = (fs: HostGuestFs) => {
    const s = sessions.get(fs);
    if (!s) throw new HostHttpError(0, "not_remote_fs", "installs over HTTP need a file session opened by servers.openFiles", "installs");
    return s;
  };
  const userFor = async (subject: string | null): Promise<HostUser | null> => (subject ? call<HostUser | null>("auth.user", { subject }) : null);
  // in-process fixed window, same semantics as the platform limiter (synchronous by contract)
  const windows = new Map<string, { start: number; n: number }>();

  const noBuilder = (m: string) => async (): Promise<never> => { throw new HostHttpError(0, "no_builder", "no local build engine was configured (createHttpHost({ builds }))", `builds.${m}`); };
  const remoteWallet: HostWallet = {
    balance: (userId) => call("billing.wallet.balance", { userId }),
    charge: (a) => call("billing.wallet.charge", a),
    refund: (a) => call("billing.wallet.refund", a),
    findByReference: async (a) => ((await call("billing.wallet.findByReference", a)) as { userId: string; reference: string; cents: number; at: string | Date }[]).map((r) => ({ ...r, at: new Date(r.at) })),
  };
  return {
    get db() { return o.db; },
    builds: o.builds ?? { sync: noBuilder("sync"), create: noBuilder("create"), accessUser: noBuilder("accessUser"), accountFor: noBuilder("accountFor"), mergeCyrusKey: noBuilder("mergeCyrusKey") },
    mods: {
      serviceBuildId: (buildId) => call("mods.serviceBuildId", { buildId }),
      onBuildSettled: async (row) => { await call("mods.onBuildSettled", { row: { id: row.id, rootBuildId: row.rootBuildId, status: row.status } }); },
    },
    billing: o.billing ?? { provider: "host", stripe: null, wallet: remoteWallet },
    warm: async () => { info = await call<HostInfo>("host.info"); return info; },
    call,
    auth: {
      currentUser: async () => userFor(await o.session.current()),
      realUser: async () => userFor(await o.session.real()),
      requireArea: (area) => (o.requireArea ? o.requireArea(area) : Promise.reject(new HostHttpError(403, "forbidden", `no admin area ${area} in this app`, "auth.requireArea"))),
    },
    access: {
      canAccess: (role, area) => !!info?.roleAreas[role]?.includes(area),
      isPreviewUser: (user, feature) => call<boolean>("access.isPreviewUser", { user: { email: user?.email ?? null }, feature }),
    },
    settings: {
      get: (key, fallback) => cached(`s:${key}:${fallback ?? ""}`, () => call<string>("settings.get", { key, fallback })),
      getBool: (key, fallback) => cached(`b:${key}:${fallback ?? ""}`, () => call<boolean>("settings.getBool", { key, fallback })),
      getInt: (key, fallback) => cached(`i:${key}:${fallback ?? ""}`, () => call<number>("settings.getInt", { key, fallback })),
      getAll: () => cached("all", () => call<Record<string, string>>("settings.getAll")),
      set: async (key, value) => { invalidate(); await call("settings.set", { key, value }); invalidate(); },
      readStored: (keys) => call("settings.readStored", { keys }),
      readStoredPrefix: (prefix) => call("settings.readStoredPrefix", { prefix }),
      writeStored: async (key, value) => { invalidate(); await call("settings.writeStored", { key, value }); invalidate(); },
      clearStored: async (key) => { invalidate(); await call("settings.clearStored", { key }); invalidate(); },
    },
    rateLimit: {
      check(key, { max, windowMs }) {
        const t = now();
        let w = windows.get(key);
        if (!w || t - w.start >= windowMs) { w = { start: t, n: 0 }; windows.set(key, w); }
        w.n++;
        const ok = w.n <= max;
        return { ok, remaining: Math.max(0, max - w.n), retryAfterSec: ok ? 0 : Math.ceil((w.start + windowMs - t) / 1000) };
      },
    },
    worker: {
      modLifecycleSweep: () => call("worker.modLifecycleSweep"),
      modCompatWatchSweep: () => call("worker.modCompatWatchSweep"),
      syncModBuilds: () => call("worker.syncModBuilds"),
    },
    users: {
      get: (id) => call("users.get", { id }),
      emails: (ids) => call("users.emails", { ids }),
      find: (query) => call("users.find", { query }),
      setBillingCustomerId: async (userId, customerId) => { await call("users.setBillingCustomerId", { userId, customerId }); },
    },
    jobs: { lastDone: (serverId, types) => call("jobs.lastDone", { serverId, types }) },
    servers: {
      get: (serverId) => call("servers.get", { serverId }),
      listForUser: (userId) => call("servers.listForUser", { userId }),
      familyOf: (server) => ((server as WireServerRow).family ?? server.osTemplate?.family ?? null) || null,
      planFamily: (serverId) => call("servers.planFamily", { serverId }),
      paidCount: (userId) => call("servers.paidCount", { userId }),
      lastHealthRun: (serverId) => call("servers.lastHealthRun", { serverId }),
      async openFiles(userId, serverId) {
        const r = await call<{ session: string; base: string; kind: "ssh" | "local" } | null>("servers.openFiles", { userId, serverId });
        if (!r) return null;
        const fs = new RemoteGuestFs(r.kind, r.session, call);
        sessions.set(fs, r.session);
        return { fs, base: r.base, close: () => { void call("fs.close", { session: r.session }).catch(() => undefined); } };
      },
      pinnedVersion: (config) => pinnedVersionOf(config),
    },
    records: {
      onServer: (serverId, source) => call("records.onServer", { serverId, source }),
      serversWithSource: (serverIds, source) => call("records.serversWithSource", { serverIds, source }),
      catalogId: (source, sourceId) => call("records.catalogId", { source, sourceId }),
      ofMod: (modId, serverIds) => call("records.ofMod", { modId, serverIds }),
    },
    installs: {
      get statePath(): string {
        if (!info) throw new HostHttpError(0, "not_warmed", "call warm() before installing (statePath comes from host.info)", "installs.statePath");
        return info.statePath;
      },
      install: ({ fs, ...args }) => call("installs.install", { session: sessionOf(fs), args }),
      uninstall: ({ fs, ...args }) => call("installs.uninstall", { session: sessionOf(fs), args }),
    },
    audit: {
      record: async (userId, action, detail) => { await call("audit.record", { userId, action, detail }); },
      append: async (row) => { await call("audit.append", { row }); },
    },
  };
}

