export type DispatchResult = { sent: number; retried: number; dead: number };
/** One pass (the worker calls it every minute or so): send what is due, schedule retries, bury what ran out of tries. */
export async function dispatchWebhooks(a: { outbox: WebhookOutbox; target: WebhookTarget; now?: () => Date; fetch?: typeof fetch; limit?: number }): Promise<DispatchResult> {
  const now = a.now ?? (() => new Date());
  const doFetch = a.fetch ?? fetch;
  const out: DispatchResult = { sent: 0, retried: 0, dead: 0 };
  for (const row of await a.outbox.due(now(), a.limit ?? 50)) {
    const ts = String(Math.floor(now().getTime() / 1000));
    let error: string | null = null;
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), WEBHOOK_TIMEOUT_MS);
    try {
      const res = await doFetch(a.target.url, {
        method: "POST", signal: ac.signal, redirect: "manual",
        headers: { "content-type": "application/json", "cyrus-webhook-id": row.id, "cyrus-webhook-timestamp": ts, "cyrus-signature": signWebhook(a.target.secret, row.id, ts, row.body), "user-agent": "cyrus-webhooks/1" },
        body: row.body,
      });
      if (res.status < 200 || res.status >= 300) error = `HTTP ${res.status}`;
    } catch (e) {
      error = ac.signal.aborted ? `no answer within ${WEBHOOK_TIMEOUT_MS} ms` : (e as Error).message || "network";
    } finally { clearTimeout(timer); }
    if (!error) { await a.outbox.markSent(row.id, now()); out.sent++; continue; }
    const attempts = row.attempts + 1;
    const delay = WEBHOOK_RETRY_DELAYS_MS[attempts - 1];
    await a.outbox.markFailed(row.id, { attempts, nextAttemptAt: delay === undefined ? null : new Date(now().getTime() + delay), error: error.slice(0, 300) });
    if (delay === undefined) out.dead++; else out.retried++;
  }
  return out;
}

/** In-process outbox (tests, a single dev instance). */
export function createMemoryOutbox(): WebhookOutbox & { rows: Map<string, OutboxRow> } {
  const rows = new Map<string, OutboxRow>();
  return {
    rows,
    async add(e) {
      if (rows.has(e.id)) return;
      rows.set(e.id, { id: e.id, type: e.type, subject: e.subject, body: JSON.stringify(e), attempts: 0, nextAttemptAt: new Date(e.createdAt), status: "pending", lastError: null, createdAt: new Date(e.createdAt) });
    },
    async due(now, limit) {
      return [...rows.values()].filter((r) => r.status === "pending" && r.nextAttemptAt <= now).sort((x, y) => +x.createdAt - +y.createdAt).slice(0, limit);
    },
    async markSent(id) { const r = rows.get(id); if (r) { r.status = "sent"; r.lastError = null; } },
    async markFailed(id, f) {
      const r = rows.get(id);
      if (!r) return;
      r.attempts = f.attempts; r.lastError = f.error;
      if (f.nextAttemptAt) r.nextAttemptAt = f.nextAttemptAt; else r.status = "dead";
    },
  };
}

