// Regenerate after removing coupling: UPDATE_CYRUS_SEAM_BASELINE=1 npx tsx --test test/cyrus-host-seam.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";

const ROOT = path.resolve(__dirname, "..");
const CYRUS = path.join(ROOT, "lib", "cyrus");
const BASELINE = path.join(__dirname, "fixtures", "cyrus-host-seam-baseline.json");
const ALLOWED_BRIDGE = "lib/cyrus/host/nxeon.ts";
const IMPORT_RE = /(?:\bfrom|\bimport|\brequire)\s*\(?\s*["']([^"']+)["']/g;

function walk(dir: string, out: string[] = []): string[] {
  for (const n of readdirSync(dir)) {
    const p = path.join(dir, n);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(n) && !/\.d\.ts$/.test(n)) out.push(p);
  }
  return out;
}

/** file -> sorted Nxeon targets (repo-relative, no extension) it imports from outside lib/cyrus. */
export function scanSeam(): Record<string, string[]> {
  const res: Record<string, string[]> = {};
  for (const file of walk(CYRUS)) {
    const rel = path.relative(ROOT, file).split(path.sep).join("/");
    if (rel === ALLOWED_BRIDGE) continue;
    const targets = new Set<string>();
    for (const m of readFileSync(file, "utf8").matchAll(IMPORT_RE)) {
      const spec = m[1];
      let abs: string | null = null;
      if (spec.startsWith(".")) abs = path.resolve(path.dirname(file), spec);
      else if (spec.startsWith("@/")) abs = path.join(ROOT, spec.slice(2));
      if (!abs) continue; // npm packages and node builtins are not platform coupling
      const t = path.relative(ROOT, abs).split(path.sep).join("/");
      if (t === "lib/cyrus" || t.startsWith("lib/cyrus/")) continue;
      targets.add(t);
    }
    if (targets.size) res[rel] = [...targets].sort();
  }
  return res;
}

