}
export const signPurchaseEvent = (secret: string, id: string, ts: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${ts}.${body}`).digest("hex")}`;

type Row = { e: PurchaseEvent; attempts: number; next: number; status: "pending" | "sent" | "dead"; lastError: string | null };

export function createPurchaseSender(o: { target: PurchaseTarget; fetch?: typeof fetch; now?: () => number }) {
  const rows = new Map<string, Row>();
  const now = o.now ?? Date.now;
  const f = o.fetch ?? fetch;
  async function attempt(r: Row): Promise<void> {
    const body = JSON.stringify(r.e), ts = String(Math.floor(now() / 1000));
    try {
      const res = await f(o.target.url, {
        method: "POST", body, signal: AbortSignal.timeout(10_000),
        headers: { "content-type": "application/json", "nxeon-webhook-id": r.e.id, "nxeon-webhook-timestamp": ts, "nxeon-signature": signPurchaseEvent(o.target.secret, r.e.id, ts, body) },
      });
      if (res.ok) { r.status = "sent"; r.lastError = null; return; }
      r.lastError = `HTTP ${res.status}`;
    } catch (err) {
      r.lastError = (err as Error).message.slice(0, 200);
    }
    r.attempts++;
    if (r.attempts > PURCHASE_RETRY_MS.length) r.status = "dead";
    else r.next = now() + PURCHASE_RETRY_MS[r.attempts - 1];
  }
  return {
    rows,
    /** Queue and try once now. Never throws: a failed send is retried by flush(). */
    async send(e: PurchaseEvent): Promise<void> {
      if (rows.get(e.id)?.status === "sent") return;
      const r: Row = rows.get(e.id) ?? { e, attempts: 0, next: now(), status: "pending", lastError: null };
      rows.set(e.id, r);
      await attempt(r);
    },
    async flush(): Promise<{ sent: number; retried: number; dead: number }> {
      const out = { sent: 0, retried: 0, dead: 0 };
      for (const r of rows.values()) {
        if (r.status !== "pending" || r.next > now()) continue;
        await attempt(r);
        const st = r.status as Row["status"];
        if (st === "sent") out.sent++; else if (st === "dead") out.dead++; else out.retried++;
      }
      return out;
    },
  };
}

