// NXEON SIDE: per-server GRANTS a user gives a connected app (Cyrus), the call audit that doubles as the
// "what did this operation touch" log (the rollback-after-revoke rule), restart budgets, and idempotency.
// Two stores behind one interface: memory (tests, one dev instance) and SQL (the tables in
// prisma/manual-migration-cyrus-bridge-grants.sql, NOT run anywhere yet). Imports nothing from lib/cyrus. SERVER ONLY.
//
// Flag: CYRUS_SERVER_GRANTS=1 shows the consent screen and accepts grants. Off = the screen and its API are 404 and
// nothing reads or writes these tables. CYRUS_SERVER_GRANTS_STORE=sql selects the SQL store (approve the SQL first);
// the default memory store forgets grants on restart, which fails CLOSED (no access), never open.
import { randomBytes } from "node:crypto";
import { CONSENT_VERSION, normaliseScopes, RESTART_BUDGET, type PlatformClient, type Scope } from "./scopes";

export type GrantStatus = "active" | "revoked";
export type Grant = {
  id: string; client: PlatformClient; userId: string; serverId: string; scopes: Scope[]; status: GrantStatus;
  consentVersion: string; restartPerHour: number; restartPerDay: number;
  createdAt: Date; updatedAt: Date; revokedAt: Date | null; revokedBy: string | null;
};
/** One audited Platform API call. `path` is set for file calls; `mutation` marks calls that changed something. */
export type CallRecord = {
  grantId: string | null; client: string; userId: string | null; serverId: string | null; call: string;
  path: string | null; opId: string | null; mutation: boolean; status: number; code: string | null; bytes: number; at: Date;
};
export type IdemHit = { requestHash: string; status: number; body: string };

export interface GrantStore {
  /** The ONE active grant of (client, user, server), created or with its scopes replaced (same id). */
  upsert(a: { client: PlatformClient; userId: string; serverId: string; scopes: Scope[]; consentVersion: string; now: Date }): Promise<Grant>;
  revoke(id: string, by: string, now: Date): Promise<Grant | null>;
  get(id: string): Promise<Grant | null>;
  active(client: PlatformClient, userId: string, serverId: string): Promise<Grant | null>;
  /** The newest grant of (client, user, server) whatever its status (to tell "revoked" from "never granted"). */
  latest(client: PlatformClient, userId: string, serverId: string): Promise<Grant | null>;
  listForUser(client: PlatformClient, userId: string, opts?: { includeRevoked?: boolean }): Promise<Grant[]>;
  /** Active grants on a server (a server deletion revokes them all). */
  activeForServer(serverId: string): Promise<Grant[]>;
  record(c: CallRecord): Promise<void>;
  /** Successful calls of `call` on a grant since a time (restart budget). */
  countCalls(grantId: string, call: string, since: Date): Promise<number>;
  /** Bytes written through a grant since a time. */
  bytesWritten(grantId: string, since: Date): Promise<number>;
  /** Did operation `opId` of this grant successfully mutate `path` (exactly, or as the target of a rename/copy)? */
  touched(grantId: string, opId: string, path: string): Promise<boolean>;
  /** Did operation `opId` restart/reload this server (so its rollback may too)? */
  opDid(grantId: string, opId: string, call: string): Promise<boolean>;
  idemGet(scope: string, key: string): Promise<IdemHit | null>;
  idemPut(scope: string, key: string, hit: IdemHit, now: Date): Promise<void>;
  recentCalls(a: { userId: string; serverId?: string; limit: number }): Promise<CallRecord[]>;
}

export const newGrantId = () => `cg_${randomBytes(12).toString("hex")}`;

/** Grant-state checks shared by both stores' callers. */
export function grantAllows(g: Grant | null, scope: Scope): boolean {
  return !!g && g.status === "active" && g.scopes.includes(scope);
}

// ------------------------------------------------------------------------------------------------ memory store
export function createMemoryGrantStore(): GrantStore & { grants: Map<string, Grant>; calls: CallRecord[] } {
  const grants = new Map<string, Grant>();
  const calls: CallRecord[] = [];
  const idem = new Map<string, { at: number; hit: IdemHit }>();
  const clone = (g: Grant): Grant => ({ ...g, scopes: [...g.scopes] });
  const latest = (client: string, userId: string, serverId: string) =>
    [...grants.values()].filter((g) => g.client === client && g.userId === userId && g.serverId === serverId).sort((a, b) => +b.updatedAt - +a.updatedAt)[0] ?? null;
  return {
    grants, calls,
    async upsert(a) {
      const cur = [...grants.values()].find((g) => g.client === a.client && g.userId === a.userId && g.serverId === a.serverId && g.status === "active");
      if (cur) { cur.scopes = normaliseScopes(a.scopes); cur.consentVersion = a.consentVersion; cur.updatedAt = a.now; return clone(cur); }
      const g: Grant = { id: newGrantId(), client: a.client, userId: a.userId, serverId: a.serverId, scopes: normaliseScopes(a.scopes), status: "active", consentVersion: a.consentVersion, restartPerHour: RESTART_BUDGET.perHour, restartPerDay: RESTART_BUDGET.perDay, createdAt: a.now, updatedAt: a.now, revokedAt: null, revokedBy: null };
      grants.set(g.id, g);
      return clone(g);
    },
    async revoke(id, by, now) {
      const g = grants.get(id);
      if (!g) return null;
      if (g.status === "active") { g.status = "revoked"; g.revokedAt = now; g.revokedBy = by; g.updatedAt = now; }
      return clone(g);
    },
    async get(id) { const g = grants.get(id); return g ? clone(g) : null; },
    async active(client, userId, serverId) { const g = latest(client, userId, serverId); return g && g.status === "active" ? clone(g) : null; },
    async latest(client, userId, serverId) { const g = latest(client, userId, serverId); return g ? clone(g) : null; },
    async listForUser(client, userId, opts) { return [...grants.values()].filter((g) => g.client === client && g.userId === userId && (opts?.includeRevoked || g.status === "active")).sort((a, b) => +a.createdAt - +b.createdAt).map(clone); },
    async activeForServer(serverId) { return [...grants.values()].filter((g) => g.serverId === serverId && g.status === "active").map(clone); },
    async record(c) { calls.push({ ...c }); if (calls.length > 100_000) calls.splice(0, 10_000); },
    async countCalls(grantId, call, since) { return calls.filter((c) => c.grantId === grantId && c.call === call && c.status < 300 && c.at >= since).length; },
    async bytesWritten(grantId, since) { return calls.filter((c) => c.grantId === grantId && c.mutation && c.at >= since).reduce((n, c) => n + c.bytes, 0); },
    async touched(grantId, opId, path) { return calls.some((c) => c.grantId === grantId && c.opId === opId && c.mutation && c.status < 300 && c.path === path); },
    async opDid(grantId, opId, call) { return calls.some((c) => c.grantId === grantId && c.opId === opId && c.call === call && c.status < 300); },
    async idemGet(scope, key) {
      const k = `${scope}\n${key}`, v = idem.get(k);
      if (v && v.at < Date.now() - 24 * 3600_000) { idem.delete(k); return null; }
      return v?.hit ?? null;
    },
    async idemPut(scope, key, hit, now) { idem.set(`${scope}\n${key}`, { at: +now, hit }); },
    async recentCalls(a) { return calls.filter((c) => c.userId === a.userId && (!a.serverId || c.serverId === a.serverId)).slice(-a.limit).reverse(); },
  };
}

// ------------------------------------------------------------------------------------------------ SQL store
/** Raw-SQL access the SQL store needs (Nxeon: db.$queryRawUnsafe / $executeRawUnsafe). */
export type Sql = { query<T = Record<string, unknown>>(sql: string, ...args: unknown[]): Promise<T[]>; exec(sql: string, ...args: unknown[]): Promise<number> };

type GrantRow = { id: string; client: string; user_id: string; server_id: string; scopes: string[]; status: string; consent_version: string; restart_per_hour: number; restart_per_day: number; created_at: Date; updated_at: Date; revoked_at: Date | null; revoked_by: string | null };
const fromRow = (r: GrantRow): Grant => ({ id: r.id, client: r.client as PlatformClient, userId: r.user_id, serverId: r.server_id, scopes: normaliseScopes(r.scopes), status: r.status === "active" ? "active" : "revoked", consentVersion: r.consent_version, restartPerHour: Number(r.restart_per_hour), restartPerDay: Number(r.restart_per_day), createdAt: new Date(r.created_at), updatedAt: new Date(r.updated_at), revokedAt: r.revoked_at ? new Date(r.revoked_at) : null, revokedBy: r.revoked_by });
const G = `"CyrusServerGrant"`, C = `"CyrusPlatformCall"`, I = `"CyrusPlatformIdempotency"`;
const COLS = `id, client, user_id, server_id, scopes, status, consent_version, restart_per_hour, restart_per_day, created_at, updated_at, revoked_at, revoked_by`;

export function createSqlGrantStore(sql: Sql): GrantStore {
  const one = async (q: string, ...a: unknown[]) => { const r = await sql.query<GrantRow>(q, ...a); return r[0] ? fromRow(r[0]) : null; };
  return {
    async upsert(a) {
      const scopes = normaliseScopes(a.scopes);
      // the partial unique index (client, user_id, server_id) WHERE status='active' makes this one row
      const r = await one(
        `INSERT INTO ${G} (id, client, user_id, server_id, scopes, status, consent_version, restart_per_hour, restart_per_day, created_at, updated_at)
         VALUES ($1, $2, $3, $4, $5::text[], 'active', $6, $7, $8, $9, $9)
         ON CONFLICT (client, user_id, server_id) WHERE status = 'active'
         DO UPDATE SET scopes = EXCLUDED.scopes, consent_version = EXCLUDED.consent_version, updated_at = EXCLUDED.updated_at
         RETURNING ${COLS}`,
        newGrantId(), a.client, a.userId, a.serverId, scopes, a.consentVersion, RESTART_BUDGET.perHour, RESTART_BUDGET.perDay, a.now);
      if (!r) throw new Error("grant upsert returned nothing");
      return r;
    },
    revoke: (id, by, now) => one(`UPDATE ${G} SET status = CASE WHEN status = 'active' THEN 'revoked' ELSE status END, revoked_at = COALESCE(revoked_at, $2), revoked_by = COALESCE(revoked_by, $3), updated_at = $2 WHERE id = $1 RETURNING ${COLS}`, id, now, by),
    get: (id) => one(`SELECT ${COLS} FROM ${G} WHERE id = $1`, id),
    active: (client, userId, serverId) => one(`SELECT ${COLS} FROM ${G} WHERE client = $1 AND user_id = $2 AND server_id = $3 AND status = 'active' LIMIT 1`, client, userId, serverId),
