import { currentUser, realUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { recordAudit } from "@/lib/audit";
import { applyConsent, grantStore, grantsEnabled, revokeGrant } from "@/lib/nxeon-platform/grants";
import { serversOf } from "@/lib/nxeon-platform/servers";
import { platformEventSink } from "@/lib/nxeon-platform/events";

export const dynamic = "force-dynamic";

/**
 * The portal side of "Connect Cyrus" (CYRUS_SERVER_GRANTS=1; otherwise 404). Cookie session, same-origin POSTs only,
 * never while an admin is impersonating (handing a customer's server to an app is the customer's own decision).
 *   GET                                   -> { grants, servers }
 *   POST { action: "connect", serverIds, scopes } -> grants (one per ticked server; the required scopes are always added)
 *   POST { action: "revoke", grantId }    -> the revoked grant (takes effect on the next call Cyrus makes)
 */
const notFound = () => new Response("Not found.", { status: 404 });
const appOrigin = () => (process.env.APP_URL || "https://nxeon.cloud").replace(/\/+$/, "");

async function who() {
  const [u, real] = await Promise.all([currentUser(), realUser()]);
  if (!u) return { error: Response.json({ error: "Sign in first." }, { status: 401 }) } as const;
  if (!real || real.id !== u.id) return { error: Response.json({ error: "Connections cannot be changed while viewing as a customer." }, { status: 403 }) } as const;
  return { user: u } as const;
}

export async function GET() {
  if (!grantsEnabled()) return notFound();
  const w = await who();
  if ("error" in w) return w.error;
  const store = await grantStore();
  const [grants, servers] = await Promise.all([store.listForUser("cyrus", w.user.id), serversOf(w.user.id)]);
  return Response.json({ grants, servers }, { headers: { "cache-control": "no-store" } });
}

export async function POST(req: Request) {
  if (!grantsEnabled()) return notFound();
  const origin = req.headers.get("origin");
  if (origin !== appOrigin() && !(process.env.NODE_ENV !== "production" && origin && new URL(origin).hostname === new URL(req.url).hostname)) {
    return Response.json({ error: "Cross-site request refused." }, { status: 403 });
  }
  const w = await who();
  if ("error" in w) return w.error;
  const rl = checkRateLimit(`cyrus-grants:${w.user.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) return Response.json({ error: "Too many changes, try again in a minute." }, { status: 429, headers: { "retry-after": String(rl.retryAfterSec) } });
  let body: { action?: string; serverIds?: unknown; scopes?: unknown; grantId?: unknown };
  try { body = await req.json(); } catch { return Response.json({ error: "Bad request." }, { status: 400 }); }
  const store = await grantStore();
  const onEvent = platformEventSink();
  if (body.action === "connect") {
    const servers = await serversOf(w.user.id);
    const eligible = new Set(servers.filter((s) => s.supported).map((s) => s.id));
    const ids = Array.isArray(body.serverIds) ? body.serverIds.filter((x): x is string => typeof x === "string") : [];
    const r = await applyConsent(store, { client: "cyrus", userId: w.user.id, serverIds: ids, scopes: body.scopes, eligible, onEvent });
    if (!r.ok) return Response.json({ error: r.error }, { status: 400 });
    await recordAudit(w.user.id, "cyrus.grant.connect", `servers=${ids.join(",")} scopes=${r.grants[0]?.scopes.join(",")}`);
    return Response.json({ grants: r.grants });
  }
  if (body.action === "revoke" && typeof body.grantId === "string") {
    const g = await revokeGrant(store, { userId: w.user.id, grantId: body.grantId, onEvent });
    if (!g) return Response.json({ error: "No such connection." }, { status: 404 });
    await recordAudit(w.user.id, "cyrus.grant.revoke", `grant=${g.id} server=${g.serverId}`);
    return Response.json({ grant: g });
  }
  return Response.json({ error: "Unknown action." }, { status: 400 });
}
EOF

