import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { PageHeader } from "@/components/ui/primitives";
import { grantStore, grantsEnabled } from "@/lib/nxeon-platform/grants";
import { serversOf } from "@/lib/nxeon-platform/servers";
import { SCOPES, SCOPE_INFO, CONSENT_VERSION } from "@/lib/nxeon-platform/scopes";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { ConnectCyrusForm } from "@/components/platform/ConnectCyrusForm";

export const dynamic = "force-dynamic";
export const metadata = { title: "Connect Cyrus" };

/** Where to send the user after consenting: a Cyrus page (cyrus.my in domain mode, or the in-portal studio). */
function safeReturn(raw: string | undefined): string | null {
  if (!raw || raw.length > 500) return null;
  if (/^\/dashboard\/cyrus(\/|\?|$)/.test(raw) && !raw.startsWith("//")) return raw;
  const cfg = bridgeConfig();
  try {
    const u = new URL(raw);
    return cfg.enabled && u.origin === cfg.cyrusOrigin ? u.toString() : null;
  } catch { return null; }
}

/**
 * "Connect Cyrus" consent screen (CYRUS_SERVER_GRANTS=1; otherwise 404). Lists exactly what Cyrus may do and lets the
 * user tick which servers; shows current connections with a Revoke button. Cyrus never receives SSH/SFTP access.
 */
export default async function ConnectCyrusPage({ searchParams }: { searchParams: Promise<{ return_to?: string; server?: string }> }) {
  if (!grantsEnabled()) notFound();
  const user = await requireUser();
  const sp = await searchParams;
  const store = await grantStore();
  const [servers, grants] = await Promise.all([serversOf(user.id), store.listForUser("cyrus", user.id)]);
  const scopes = SCOPES.map((s) => ({ id: s, ...SCOPE_INFO[s] }));
  return (
    <div className="mx-auto max-w-3xl">
      <PageHeader title="Connect Cyrus" sub="Let Cyrus, the AI mod studio, install what you build straight onto the servers you pick." />
      <ConnectCyrusForm
        servers={servers}
        grants={grants.map((g) => ({ id: g.id, serverId: g.serverId, scopes: g.scopes, createdAt: g.createdAt.toISOString() }))}
        scopes={scopes}
        consentVersion={CONSENT_VERSION}
        preselect={typeof sp.server === "string" ? sp.server : null}
        returnTo={safeReturn(sp.return_to)}
      />
    </div>
  );
}
