// r38 (1): Connect Cyrus grants: scopes, path policy, the memory store, consent/revoke rules.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { checkPath, normaliseScopes, SCOPES, SCOPE_INFO, type PathLayout } from "../lib/nxeon-platform/scopes";
import { applyConsent, createMemoryGrantStore, grantAllows, revokeGrant, revokeServerGrants } from "../lib/nxeon-platform/grants";

const L: PathLayout = { base: "/opt/mc", levelName: "survival", clientStateDir: "/root/.nxeon-cyrus" };
const ok = (p: string, m: "read" | "write") => checkPath(p, L, m).ok;

describe("path policy", () => {
  it("allows the mod roots for writes", () => {
    for (const p of ["/opt/mc/plugins/Foo.jar", "/opt/mc/plugins/Foo/config.yml", "/opt/mc/mods/x.jar", "/opt/mc/config/paper-global.yml", "/opt/mc/resourcepacks/p.zip", "/opt/mc/survival/datapacks/dp.zip", "/opt/mc/world/datapacks/dp.zip", "/root/.nxeon-cyrus/delivery-journal/x/journal.json", "/opt/mc/plugins/Foo.jar.nxeon-part"]) assert.ok(ok(p, "write"), p);
  });
  it("refuses everything else for writes", () => {
    for (const p of ["/opt/mc/server.jar", "/opt/mc/server.properties", "/opt/mc/plugins", "/opt/mc/survival/level.dat", "/opt/mc/survival/region/r.0.0.mca", "/opt/mc/start.sh", "/opt/mc/plugins/evil.sh", "/opt/mc/plugins/../server.jar", "/opt/mc/plugins/./x", "plugins/x.jar", "/opt/mc//plugins/x", "/root/.ssh/authorized_keys", "/opt/mc/plugins/.ssh/x", "/etc/passwd", "/opt/mc/ops.json", "/opt/mc/other/datapacks/x.zip", "/opt/mc/plugins/a\\b", "/opt/mc/plugins/lib.so", "/root/.nxeon-cyrusX/a"]) assert.ok(!ok(p, "write"), p);
  });
  it("reads: the roots, their folders, version files; never logs/world/credentials", () => {
    for (const p of ["/opt/mc/plugins", "/opt/mc/server.properties", "/opt/mc/version_history.json", "/opt/mc/survival", "/opt/mc/survival/datapacks"]) assert.ok(ok(p, "read"), p);
    for (const p of ["/opt/mc/logs/latest.log", "/opt/mc/survival/level.dat", "/opt/mc/eula.txt", "/opt/mc/whitelist.json", "/root/.ssh/id_ed25519"]) assert.ok(!ok(p, "read"), p);
  });
  it("normalises trailing slashes and reports the area", () => {
    const v = checkPath("/opt/mc/survival/datapacks/x.zip/", L, "write");
    assert.deepEqual(v, { ok: true, path: "/opt/mc/survival/datapacks/x.zip", area: "datapacks" });
  });
});

describe("scopes", () => {
  it("always includes the required ones, drops unknown, keeps display order", () => {
    assert.deepEqual(normaliseScopes(["server.restart", "nope", "pack.set"]), ["servers.read", "inventory.read", "server.restart", "pack.set"]);
    assert.deepEqual(normaliseScopes(null), ["servers.read", "inventory.read"]);
  });
  it("every scope has consent copy", () => { for (const s of SCOPES) assert.ok(SCOPE_INFO[s].title && SCOPE_INFO[s].detail.length > 20, s); });
});

describe("grants", () => {
  const now = new Date("2026-10-11T10:00:00Z");
  it("one active grant per user+server; reconnect replaces scopes, same id", async () => {
    const st = createMemoryGrantStore();
    const ev: string[] = [];
    const a = await applyConsent(st, { client: "cyrus", userId: "u1", serverIds: ["s1"], scopes: ["files.write.mods"], eligible: new Set(["s1", "s2"]), now, onEvent: async (e) => { ev.push(e.type); } });
    assert.ok(a.ok);
    const b = await applyConsent(st, { client: "cyrus", userId: "u1", serverIds: ["s1"], scopes: ["server.restart"], eligible: new Set(["s1"]), now, onEvent: async (e) => { ev.push(e.type); } });
    assert.ok(b.ok && a.ok && b.grants[0].id === a.grants[0].id);
    assert.ok(b.ok && !b.grants[0].scopes.includes("files.write.mods") && b.grants[0].scopes.includes("server.restart"));
    assert.deepEqual(ev, ["grant.created", "grant.updated"]);
    assert.equal((await st.listForUser("cyrus", "u1")).length, 1);
  });
  it("refuses servers that are not eligible (not the user's, unsupported) and empty picks", async () => {
    const st = createMemoryGrantStore();
    assert.equal((await applyConsent(st, { client: "cyrus", userId: "u1", serverIds: ["s9"], scopes: [], eligible: new Set(["s1"]) })).ok, false);
    assert.equal((await applyConsent(st, { client: "cyrus", userId: "u1", serverIds: [], scopes: [], eligible: new Set(["s1"]) })).ok, false);
    assert.equal(st.grants.size, 0);
  });
  it("revoke: own grants only, idempotent, then the scope check fails; history is kept", async () => {
    const st = createMemoryGrantStore();
    const r = await applyConsent(st, { client: "cyrus", userId: "u1", serverIds: ["s1"], scopes: ["files.write.mods"], eligible: new Set(["s1"]), now });
    assert.ok(r.ok);
    const id = r.ok ? r.grants[0].id : "";
    assert.ok(grantAllows(await st.active("cyrus", "u1", "s1"), "files.write.mods"));
    assert.equal(await revokeGrant(st, { userId: "u2", grantId: id }), null);
    const ev: string[] = [];
    const g = await revokeGrant(st, { userId: "u1", grantId: id, onEvent: async (e) => { ev.push(e.type); } });
    assert.equal(g?.status, "revoked");
    await revokeGrant(st, { userId: "u1", grantId: id, onEvent: async (e) => { ev.push(e.type); } });
    assert.deepEqual(ev, ["grant.revoked"]);
    assert.equal(await st.active("cyrus", "u1", "s1"), null);
    assert.equal((await st.latest("cyrus", "u1", "s1"))?.status, "revoked");
    assert.ok(!grantAllows(await st.get(id), "files.write.mods"));
    // a new consent after a revoke is a NEW grant
    const again = await applyConsent(st, { client: "cyrus", userId: "u1", serverIds: ["s1"], scopes: [], eligible: new Set(["s1"]), now });
    assert.ok(again.ok && again.grants[0].id !== id);
  });
  it("a server deletion revokes every grant on it", async () => {
    const st = createMemoryGrantStore();
    await applyConsent(st, { client: "cyrus", userId: "u1", serverIds: ["s1", "s2"], scopes: [], eligible: new Set(["s1", "s2"]), now });
    assert.equal(await revokeServerGrants(st, "s1", "server_deleted"), 1);
    assert.equal((await st.listForUser("cyrus", "u1")).map((g) => g.serverId).join(), "s2");
  });
});
