// Health facts from a Paper latest.log (pure). Shared by Nxeon's delivery worker (worker/cyrus-delivery.ts) and the
// Platform-API session (lib/cyrus/host/platform-session.ts), which reads the log through the logs.read.tail primitive.
// HOST SEAM: no platform imports.
export function parseBootLog(text: string): { cameUp: boolean; enabled: string[]; errors: string[] } {
  const lines = text.split("\n");
  const doneAt = lines.findIndex((l) => /\bDone \(\d/.test(l));
  const upTo = doneAt >= 0 ? lines.slice(0, doneAt + 1) : lines;
  const failed = new Set(upTo.map((l) => /Error occurred while enabling (\S+)/.exec(l)?.[1]).filter(Boolean) as string[]);
  const disabled = new Set(lines.map((l) => /\bDisabling (\S+) v/.exec(l)?.[1]).filter(Boolean) as string[]);
  const enabled = [...new Set(upTo.map((l) => /\bEnabling (\S+) v/.exec(l)?.[1]).filter((n): n is string => !!n))].filter((n) => !failed.has(n) && !disabled.has(n));
  const errors = upTo.filter((l) => /\/(ERROR|FATAL)\]|\[(ERROR|FATAL)\]| ERROR\]:|Exception in |Error occurred while enabling/.test(l)).filter((l) => !/PaperVersionFetcher|Error obtaining version information/.test(l)).slice(0, 40);
  return { cameUp: doneAt >= 0, enabled, errors };
}
