// NXEON PLATFORM API v1 (for Cyrus): the safe primitives a connected app uses on a customer's game server, served by
// Nxeon at /api/platform/cyrus/v1/* and consumed by Cyrus' HTTP host adapter (lib/cyrus/host/platform.ts).
// Contract: docs/api/nxeon-platform-v1.openapi.yaml (generated from PLATFORM_OPERATIONS by tools/nxeon-platform/gen-openapi.ts).
//
// Every request, in order:
//   1. service auth: HMAC request signature of the client's key (cyrus-key-id/-timestamp/-nonce/-signature, replay-once)
//   2. WHO: an Ed25519 user assertion signed by the client (nxeon-user-assertion; sub = Nxeon user id, aud
//      nxeon-platform-v1, <= 120 s, single-use jti). Nxeon holds only the client's PUBLIC key.
//   3. WHICH server: the user's ACTIVE grant for that server (lib/nxeon-platform/grants.ts) carrying the call's scope,
//      and the server still being the user's. After a revoke, an operation already in flight (nxeon-op-id +
//      nxeon-op-mode: rollback) may for 15 minutes only UNDO what that same operation changed, nothing new.
//   4. limits: calls/writes per minute and bytes per hour per grant; restarts against the grant's budget.
//   5. writes: Idempotency-Key (same key + same request = the stored answer; same key + different request = 422).
//   6. files: the path allow-list (lib/nxeon-platform/scopes.ts checkPath), size caps, and a HASH PRECONDITION on every
//      change (ifMatch = the sha256 the caller last saw, or "absent"), under a per-server lock.
//   7. an audit row per call (the same rows are the "what did this operation touch" log of step 3).
// Underneath, the SAME guest file access the Mods engine uses (lib/mods/guest-fs: SSH in production, LocalGuestFs in
// SANDBOX/tests), unchanged. Imports nothing from lib/cyrus except the pure request-signing helpers. SERVER ONLY.
import { createHash, verify as edVerify, type KeyObject } from "node:crypto";
import { ReplayCache, verifyRequest } from "../cyrus/api/v1/signing";
import { grantAllows, type CallRecord, type Grant, type GrantStore } from "./grants";
import { checkPath, LIMITS, type PathLayout, type PlatformClient, type Scope } from "./scopes";
import type { PlatformServer } from "./servers";

export const PLATFORM_API_PREFIX = "/api/platform/cyrus/v1";
export const PLATFORM_API_VERSION = "1";
export const PLATFORM_AUD = "nxeon-platform-v1";
export const H = { assertion: "nxeon-user-assertion", opId: "nxeon-op-id", opMode: "nxeon-op-mode", idem: "idempotency-key" } as const;
export const ASSERTION_MAX_LIFETIME_S = 120;

type OpDef = { method: "GET" | "POST"; path: string; scope: Scope | null; user: boolean; server: boolean; mutation: boolean; summary: string };
/** THE operation table (the OpenAPI file and Cyrus' client table are pinned to it by test/cyrus-platform-contract.test.ts). */
export const PLATFORM_OPERATIONS = {
  health:          { method: "GET",  path: "/health",                         scope: null,               user: false, server: false, mutation: false, summary: "Liveness and API version (service signature only)." },
  listGrants:      { method: "GET",  path: "/grants",                         scope: null,               user: true,  server: false, mutation: false, summary: "The user's active grants for this client." },
  getEntitlements: { method: "GET",  path: "/entitlements",                   scope: null,               user: true,  server: false, mutation: false, summary: "The user's Cyrus plan and token entitlements as Nxeon (the payment provider) records them." },
  listServers:     { method: "GET",  path: "/servers",                        scope: "servers.read",     user: true,  server: false, mutation: false, summary: "The granted servers: id, name, game, version/loader, status, resources." },
  getServer:       { method: "GET",  path: "/servers/{serverId}",             scope: "servers.read",     user: true,  server: true,  mutation: false, summary: "One granted server; with ?live=1 also online/answering, player count and loaded data packs." },
  getInventory:    { method: "GET",  path: "/servers/{serverId}/inventory",   scope: "inventory.read",   user: true,  server: true,  mutation: false, summary: "Installed plugins/mods/data packs/resource packs: Nxeon's install records (incl. the Mods tab) and the files with sizes and sha256." },
  statFile:        { method: "GET",  path: "/servers/{serverId}/files/stat",  scope: "inventory.read",   user: true,  server: true,  mutation: false, summary: "type, size and sha256 of one allowed path (null when absent)." },
  readFile:        { method: "GET",  path: "/servers/{serverId}/files/read",  scope: "inventory.read",   user: true,  server: true,  mutation: false, summary: "Bytes (base64) and sha256 of one allowed file." },
  listDir:         { method: "GET",  path: "/servers/{serverId}/files/list",  scope: "inventory.read",   user: true,  server: true,  mutation: false, summary: "Entry names of one allowed folder." },
  writeFile:       { method: "POST", path: "/servers/{serverId}/files/write", scope: "files.write.mods", user: true,  server: true,  mutation: true,  summary: "Create or replace a file; ifMatch = the sha256 being replaced or \"absent\"." },
  deleteFile:      { method: "POST", path: "/servers/{serverId}/files/delete",scope: "files.write.mods", user: true,  server: true,  mutation: true,  summary: "Delete a file (ifMatch = its sha256) or a folder (ifMatch = \"dir\")." },
  makeDir:         { method: "POST", path: "/servers/{serverId}/files/mkdir", scope: "files.write.mods", user: true,  server: true,  mutation: true,  summary: "Create a folder (and parents)." },
  renameFile:      { method: "POST", path: "/servers/{serverId}/files/rename",scope: "files.write.mods", user: true,  server: true,  mutation: true,  summary: "Move a file; ifMatch for the source, toIfMatch for what it replaces (sha256 or \"absent\")." },
  copyFile:        { method: "POST", path: "/servers/{serverId}/files/copy",  scope: "files.write.mods", user: true,  server: true,  mutation: true,  summary: "Copy a file on the server (no download); toIfMatch for what it replaces." },
  reload:          { method: "POST", path: "/servers/{serverId}/reload",      scope: "server.reload",    user: true,  server: true,  mutation: true,  summary: "minecraft:reload (data packs) or one plugin's own \"<plugin> reload\"." },
  restart:         { method: "POST", path: "/servers/{serverId}/restart",     scope: "server.restart",   user: true,  server: true,  mutation: true,  summary: "Restart the game service and wait for it to come up (budgeted per grant)." },
  logTail:         { method: "GET",  path: "/servers/{serverId}/logs/tail",   scope: "logs.read.tail",   user: true,  server: true,  mutation: false, summary: "The last lines of logs/latest.log." },
  setPack:         { method: "POST", path: "/servers/{serverId}/pack",        scope: "pack.set",         user: true,  server: true,  mutation: true,  summary: "Set resource-pack, resource-pack-sha1, require-resource-pack (and prompt) in server.properties." },
} as const satisfies Record<string, OpDef>;
export type PlatformOperation = keyof typeof PLATFORM_OPERATIONS;

// ------------------------------------------------------------------------------------------------ deps
/** Guest file access (structurally lib/mods/guest-fs GuestFs). */
export interface PlatformFs {
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  rename(from: string, to: string): Promise<void>;
  remove(p: string): Promise<void>;
  list(dir: string): Promise<string[]>;
  copy(from: string, to: string): Promise<void>;
}
export type InventoryRecord = { name: string; version: string | null; source: string; sourceId: string | null; status: string; fileName: string | null; via: "mods-tab" | "cyrus" | "managed" | "other" };
export type LiveStatus = { online: boolean; answered: boolean; players: number | null; maxPlayers: number | null; datapacksLoaded: string[] };
export type PlatformEvent = { type: "server.restarted"; userId: string; serverId: string; at: Date; by: string };

export type PlatformDeps = {
  store: GrantStore;
  /** HMAC secret of a client key, and which client it belongs to (null = unknown key). */
  keys: { secretFor(keyId: string): string | null; clientOf(keyId: string): PlatformClient | null };
  /** The client's Ed25519 PUBLIC keys for user assertions (rotation: several). */
  assertionKeys(client: PlatformClient): KeyObject[];
  servers: {
    /** The user's server (null when it is not theirs, gone or being deleted). */
    get(userId: string, serverId: string): Promise<PlatformServer | null>;
    many(userId: string, ids: string[]): Promise<PlatformServer[]>;
    live?(serverId: string): Promise<LiveStatus | null>;
  };
  /** Full guest access, Nxeon only (never handed out). `layout.levelName` comes from server.properties. */
  open(serverId: string): Promise<{ fs: PlatformFs; layout: PathLayout; close?: () => void } | null>;
  /** Nxeon's own install records for the server (ServerMod: the Mods tab, Cyrus, managed plugins). */
  records(serverId: string): Promise<InventoryRecord[]>;
  power: {
    restart(serverId: string): Promise<{ ok: true; cameUp: boolean } | { ok: false; error: string }>;
    console(serverId: string, command: string): Promise<{ ok: true; reply: string } | { ok: false; error: string }>;
  };
  entitlements?(userId: string): Promise<unknown>;
  onEvent?(e: PlatformEvent): Promise<void>;
  rateLimit(key: string, o: { max: number; windowMs: number }): { ok: boolean; retryAfterSec: number };
  now?: () => number;
  replay?: ReplayCache;
  /** idle time an opened guest connection is kept for the next call (default 60 s) */
  fsIdleMs?: number;
};

// ------------------------------------------------------------------------------------------------ helpers
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const SHA_RE = /^[a-f0-9]{64}$/;
const IDEM_RE = /^[A-Za-z0-9_-]{8,128}$/;
const OPID_RE = /^[A-Za-z0-9_-]{8,64}$/;
const SUB_RE = /^[A-Za-z0-9_:.-]{4,128}$/;
const PLUGIN_RELOAD_DENY = new Set(["minecraft", "bukkit", "spigot", "paper", "purpur", "plugman", "plugmanx", "op", "deop", "stop", "restart", "reload", "whitelist", "ban", "kick", "execute", "sudo", "lp", "luckperms"]);
class ApiError extends Error { constructor(public status: number, public code: string, message: string, public extra?: Record<string, unknown>) { super(message); } }
const json = (status: number, body: unknown, headers: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "nxeon-platform-api": PLATFORM_API_VERSION, ...headers } });
const fail = (e: ApiError) => json(e.status, { ok: false, error: { code: e.code, message: e.message, ...(e.extra ?? {}) } }, e.code === "rate_limited" || e.code === "budget_exhausted" ? { "retry-after": String(e.extra?.retryAfterSec ?? 60) } : {});

type Claims = { v: 1; iss: string; sub: string; aud: string; iat: number; exp: number; jti: string };
/** Verify the client-signed user assertion. Exported for the contract tests. */
export function verifyUserAssertion(raw: string | null, o: { client: string; keys: KeyObject[]; nowMs: number; replay: ReplayCache }): { ok: true; sub: string } | { ok: false; message: string } {
  const s = String(raw ?? "").trim();
  const m = /^([A-Za-z0-9_-]{10,2048})\.([A-Za-z0-9_-]{40,200})$/.exec(s);
  if (!m) return { ok: false, message: "user assertion missing or malformed" };
  if (!o.keys.some((k) => { try { return edVerify(null, Buffer.from(m[1]), k, Buffer.from(m[2], "base64url")); } catch { return false; } })) return { ok: false, message: "user assertion signature does not verify" };
  let c: Claims;
  try { c = JSON.parse(Buffer.from(m[1], "base64url").toString("utf8")); } catch { return { ok: false, message: "user assertion is not JSON" }; }
  if (!c || c.v !== 1 || c.iss !== o.client || c.aud !== PLATFORM_AUD) return { ok: false, message: "user assertion is for another party" };
  if ("email" in (c as object)) return { ok: false, message: "user assertions carry the stable user id, never an email" };
  if (typeof c.sub !== "string" || !SUB_RE.test(c.sub) || typeof c.jti !== "string" || !/^[A-Za-z0-9_-]{8,64}$/.test(c.jti)) return { ok: false, message: "user assertion claims are invalid" };
  const now = Math.floor(o.nowMs / 1000);
  if (!Number.isInteger(c.iat) || !Number.isInteger(c.exp) || c.exp <= c.iat || c.exp - c.iat > ASSERTION_MAX_LIFETIME_S || c.iat > now + 30 || c.exp + 30 < now) return { ok: false, message: "user assertion expired or too long-lived" };
  if (o.replay.seen(`pua:${o.client}:${c.jti}`, (c.exp + 30) * 1000, o.nowMs)) return { ok: false, message: "user assertion already used" };
  return { ok: true, sub: c.sub };
}

function match(method: string, rel: string): { op: PlatformOperation; serverId: string | null } | null {
  const segs = rel.split("/").filter(Boolean);
  for (const [name, d] of Object.entries(PLATFORM_OPERATIONS) as [PlatformOperation, OpDef][]) {
    if (d.method !== method) continue;
    const t = d.path.split("/").filter(Boolean);
    if (t.length !== segs.length) continue;
    let serverId: string | null = null, ok = true;
    for (let i = 0; i < t.length && ok; i++) {
      if (t[i] === "{serverId}") { if (/^[A-Za-z0-9_-]{4,64}$/.test(segs[i])) serverId = segs[i]; else ok = false; }
      else if (t[i] !== segs[i]) ok = false;
    }
    if (ok) return { op: name, serverId };
  }
  return null;
}

/** Edit only the resource-pack keys of a server.properties text (pure; exported for tests). */
export function setPackProperties(text: string, p: { url: string; sha1: string; required: boolean; prompt: string | null }): string {
  const want: Record<string, string> = { "resource-pack": p.url, "resource-pack-sha1": p.sha1, "require-resource-pack": String(p.required), ...(p.prompt !== null ? { "resource-pack-prompt": p.prompt } : {}) };
  const seen = new Set<string>();
  const lines = text.split("\n").map((l) => {
    const k = /^([A-Za-z0-9.-]+)\s*=/.exec(l)?.[1];
    if (k && k in want) { seen.add(k); return `${k}=${want[k]}`; }
    return l;
  });
  for (const k of Object.keys(want)) if (!seen.has(k)) lines.splice(lines.length && lines[lines.length - 1] === "" ? lines.length - 1 : lines.length, 0, `${k}=${want[k]}`);
  return lines.join("\n");
}

// ------------------------------------------------------------------------------------------------ the API
export type PlatformApi = { handle(req: Request): Promise<Response>; close(): void };

export function createPlatformApi(d: PlatformDeps): PlatformApi {
  const now = d.now ?? Date.now;
  const replay = d.replay ?? new ReplayCache();
  const idleMs = d.fsIdleMs ?? 60_000;
  // opened guest connections, reused across calls of one delivery (an SSH handshake per file call would be slow)
  const pool = new Map<string, { fs: PlatformFs; layout: PathLayout; close?: () => void; last: number; users: number }>();
  const locks = new Map<string, Promise<unknown>>();
  const sweep = () => { for (const [k, v] of pool) if (!v.users && now() - v.last > idleMs) { pool.delete(k); try { v.close?.(); } catch { /* best effort */ } } };
  const timer = setInterval(sweep, Math.max(5_000, Math.min(idleMs, 30_000)));
  (timer as { unref?: () => void }).unref?.();

  async function withFs<T>(serverId: string, fn: (fs: PlatformFs, layout: PathLayout) => Promise<T>): Promise<T> {
    let e = pool.get(serverId);
    if (!e) {
      const o = await d.open(serverId).catch((err: Error) => { throw new ApiError(503, "server_unreachable", `the server could not be reached (${err.message.slice(0, 120)})`); });
      if (!o) throw new ApiError(404, "server_gone", "the server is gone or being deleted");
      e = { ...o, last: now(), users: 0 };
      pool.set(serverId, e);
    }
    e.users++;
    try { return await fn(e.fs, e.layout); } finally { e.users--; e.last = now(); }
  }
  /** one mutation at a time per server (preconditions are checked and applied atomically w.r.t. other API calls) */
  async function locked<T>(serverId: string, fn: () => Promise<T>): Promise<T> {
    const prev = locks.get(serverId) ?? Promise.resolve();
    let release!: () => void;
    const mine = new Promise<void>((r) => (release = r));
    const chain = prev.then(() => mine);
    locks.set(serverId, chain);
    await prev.catch(() => undefined);
    try { return await fn(); } finally { release(); if (locks.get(serverId) === chain) locks.delete(serverId); }
  }
  const hashOf = async (fs: PlatformFs, p: string): Promise<{ type: "file" | "dir"; size: number; sha256: string | null } | null> => {
    const st = await fs.stat(p);
    if (!st) return null;
    if (st.type === "dir") return { type: "dir", size: 0, sha256: null };
    const b = st.size <= LIMITS.maxReadBytes ? await fs.readFile(p, LIMITS.maxReadBytes) : null;
    return { type: "file", size: st.size, sha256: b ? sha(b) : null };
  };
  const precondition = async (fs: PlatformFs, p: string, ifMatch: unknown, label = "ifMatch") => {
    if (ifMatch !== "absent" && ifMatch !== "dir" && !(typeof ifMatch === "string" && SHA_RE.test(ifMatch))) throw new ApiError(400, "precondition_required", `${label} must be the sha256 you are replacing, "absent", or "dir"`);
    const cur = await hashOf(fs, p);
    const ok = ifMatch === "absent" ? !cur : ifMatch === "dir" ? cur?.type === "dir" : cur?.type === "file" && cur.sha256 === ifMatch;
    if (!ok) throw new ApiError(412, "precondition_failed", `${p} is not what ${label} says (someone else changed it, or the caller's view is stale)`, { path: p, current: cur ? (cur.type === "dir" ? "dir" : cur.sha256 ?? "too_large") : "absent" });
  };

  type Ctx = { client: PlatformClient; userId: string; grant: Grant | null; rollback: boolean; opId: string | null; serverId: string | null; layout?: PathLayout; touched: string[]; bytes: number };
  const pathArg = (ctx: Ctx, layout: PathLayout, raw: unknown, mode: "read" | "write") => {
    const v = checkPath(raw, layout, mode);
    if (!v.ok) throw new ApiError(403, "path_refused", v.reason, { path: typeof raw === "string" ? raw.slice(0, 200) : null });
    return v.path;
  };
  /** Rollback-only mode: may this (revoked) operation touch `p`? Its own earlier changes, their temp names, its journal. */
  const mayUndo = async (ctx: Ctx, layout: PathLayout, p: string) => {
    if (!ctx.rollback) return;
    const state = layout.clientStateDir?.replace(/\/+$/, "");
    if (state && (p === state || p.startsWith(state + "/"))) return;
    const plain = p.replace(/\.(nxeon-part|nxeon-restore)$/, "");
    if (await d.store.touched(ctx.grant!.id, ctx.opId!, p) || await d.store.touched(ctx.grant!.id, ctx.opId!, plain)) return;
    throw new ApiError(403, "rollback_only", "the connection was revoked: this operation may only undo its own changes");
  };
  const b64 = (raw: unknown, max: number) => {
    if (typeof raw !== "string" || !/^[A-Za-z0-9+/=_-]*$/.test(raw)) throw new ApiError(400, "bad_request", "dataB64 must be base64");
    if (raw.length > Math.ceil(max / 3) * 4 + 4) throw new ApiError(413, "too_large", `files are capped at ${max} bytes`);
    const buf = Buffer.from(raw, "base64");
    if (buf.length > max) throw new ApiError(413, "too_large", `files are capped at ${max} bytes`);
    return buf;
  };

  const ops: Record<PlatformOperation, (ctx: Ctx, q: URLSearchParams, body: Record<string, unknown>) => Promise<unknown>> = {
    health: async () => ({ version: PLATFORM_API_VERSION }),
    listGrants: async (ctx) => (await d.store.listForUser(ctx.client, ctx.userId)).map((g) => ({ grantId: g.id, serverId: g.serverId, scopes: g.scopes, consentVersion: g.consentVersion, createdAt: g.createdAt.toISOString(), restartBudget: { perHour: g.restartPerHour, perDay: g.restartPerDay } })),
    getEntitlements: async (ctx) => {
      if (!d.entitlements) throw new ApiError(501, "not_available", "entitlements are not served here");
      return d.entitlements(ctx.userId);
    },
    listServers: async (ctx) => {
      const grants = (await d.store.listForUser(ctx.client, ctx.userId)).filter((g) => grantAllows(g, "servers.read"));
      const servers = await d.servers.many(ctx.userId, grants.map((g) => g.serverId));
      const byId = new Map(grants.map((g) => [g.serverId, g]));
      return servers.map((s) => ({ ...s, grant: { grantId: byId.get(s.id)!.id, scopes: byId.get(s.id)!.scopes } }));
    },
    getServer: async (ctx, q) => {
      const s = await d.servers.get(ctx.userId, ctx.serverId!);
      if (!s) throw new ApiError(404, "server_gone", "the server is gone");
      const live = q.get("live") === "1" && d.servers.live ? await d.servers.live(s.id).catch(() => null) : undefined;
      return { ...s, grant: { grantId: ctx.grant!.id, scopes: ctx.grant!.scopes }, ...(live !== undefined ? { live } : {}) };
    },
    getInventory: async (ctx) => withFs(ctx.serverId!, async (fs, layout) => {
      const dirs = [`${layout.base}/plugins`, `${layout.base}/mods`, `${layout.base}/${layout.levelName}/datapacks`, `${layout.base}/resourcepacks`];
      const files: { path: string; area: string; size: number; sha256: string | null }[] = [];
      let hashed = 0;
      for (const dir of dirs) {
        if ((await fs.stat(dir))?.type !== "dir") continue;
        for (const n of (await fs.list(dir)).sort().slice(0, 500)) {
          const p = `${dir}/${n}`;
          if (!checkPath(p, layout, "read").ok) continue;
          const st = await fs.stat(p);
          if (st?.type !== "file") continue;
          const canHash = st.size <= LIMITS.maxReadBytes && hashed + st.size <= 512 * 1024 * 1024;
          const b = canHash ? await fs.readFile(p, LIMITS.maxReadBytes) : null;
          if (b) hashed += b.length;
          files.push({ path: p, area: dir.split("/").pop()!, size: st.size, sha256: b ? sha(b) : null });
        }
      }
      return { layout: { base: layout.base, levelName: layout.levelName, clientStateDir: layout.clientStateDir }, records: await d.records(ctx.serverId!), files };
    }),
    statFile: async (ctx, q) => withFs(ctx.serverId!, async (fs, layout) => hashOf(fs, pathArg(ctx, layout, q.get("path"), "read"))),
    readFile: async (ctx, q) => withFs(ctx.serverId!, async (fs, layout) => {
      const p = pathArg(ctx, layout, q.get("path"), "read");
      const max = Math.min(LIMITS.maxReadBytes, Number(q.get("maxBytes")) > 0 ? Number(q.get("maxBytes")) : LIMITS.maxReadBytes);
      const st = await fs.stat(p);
      if (!st) return null;
      if (st.type !== "file") throw new ApiError(409, "is_directory", `${p} is a folder`);
      if (st.size > max) throw new ApiError(413, "too_large", `${p} is ${st.size} bytes (cap ${max})`);
      const b = await fs.readFile(p, max);
      if (!b) return null;
      ctx.bytes = b.length;
      return { size: b.length, sha256: sha(b), dataB64: b.toString("base64") };
    }),
    listDir: async (ctx, q) => withFs(ctx.serverId!, async (fs, layout) => {
      const p = pathArg(ctx, layout, q.get("path"), "read");
      const st = await fs.stat(p);
      if (!st) return [];
      if (st.type !== "dir") throw new ApiError(409, "not_directory", `${p} is a file`);
      return (await fs.list(p)).slice(0, LIMITS.maxListEntries);
    }),
    writeFile: async (ctx, _q, b) => withFs(ctx.serverId!, async (fs, layout) => {
      const p = pathArg(ctx, layout, b.path, "write");
      await mayUndo(ctx, layout, p);
      const data = b64(b.dataB64, LIMITS.maxFileBytes);
      return locked(ctx.serverId!, async () => {
        await precondition(fs, p, b.ifMatch);
        await fs.writeFile(p, data);
        ctx.touched.push(p); ctx.bytes = data.length;
        return { path: p, size: data.length, sha256: sha(data) };
      });
    }),
    deleteFile: async (ctx, _q, b) => withFs(ctx.serverId!, async (fs, layout) => {
      const p = pathArg(ctx, layout, b.path, "write");
      await mayUndo(ctx, layout, p);
      return locked(ctx.serverId!, async () => {
        if (b.ifMatch !== "absent") await precondition(fs, p, b.ifMatch);
        await fs.remove(p);
        ctx.touched.push(p);
        return { path: p, removed: b.ifMatch !== "absent" };
      });
    }),
    makeDir: async (ctx, _q, b) => withFs(ctx.serverId!, async (fs, layout) => {
      const p = pathArg(ctx, layout, b.path, "write");
      await mayUndo(ctx, layout, p);
      return locked(ctx.serverId!, async () => {
        const st = await fs.stat(p);
        if (st?.type === "file") throw new ApiError(409, "is_file", `${p} is a file`);
        await fs.mkdirp(p);
        ctx.touched.push(p);
        return { path: p, created: !st };
      });
    }),
    renameFile: async (ctx, _q, b) => withFs(ctx.serverId!, async (fs, layout) => {
      const from = pathArg(ctx, layout, b.from, "write"), to = pathArg(ctx, layout, b.to, "write");
      await mayUndo(ctx, layout, from); await mayUndo(ctx, layout, to);
      return locked(ctx.serverId!, async () => {
        await precondition(fs, from, b.ifMatch);
        await precondition(fs, to, b.toIfMatch, "toIfMatch");
        await fs.rename(from, to);
        ctx.touched.push(from, to);
        return { from, to };
      });
    }),
    copyFile: async (ctx, _q, b) => withFs(ctx.serverId!, async (fs, layout) => {
      const from = pathArg(ctx, layout, b.from, "read"), to = pathArg(ctx, layout, b.to, "write");
      await mayUndo(ctx, layout, to);
      return locked(ctx.serverId!, async () => {
        const src = await fs.stat(from);
        if (src?.type !== "file") throw new ApiError(404, "not_found", `${from} is not a file`);
        if (src.size > LIMITS.maxFileBytes * 4) throw new ApiError(413, "too_large", `${from} is too large to copy`);
        await precondition(fs, to, b.toIfMatch, "toIfMatch");
        await fs.copy(from, to);
        ctx.touched.push(to); ctx.bytes = src.size;
        return { from, to };
      });
    }),
    reload: async (ctx, _q, b) => {
      let command: string;
      if (b.kind === "datapacks") command = "minecraft:reload";
