      return res;
    }
  }

  return { handle, close: () => { clearInterval(timer); for (const v of pool.values()) try { v.close?.(); } catch { /* best effort */ } pool.clear(); } };
}

export const platformApiEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_PLATFORM_API === "1";

