// NXEON SIDE: the real PlatformDeps (database, guest file access, game control) for lib/nxeon-platform/api.ts.
// Reuses, unchanged: lib/mods/guest-fs (LocalGuestFs in SANDBOX) and worker/mods-guest-ssh (SshGuestFs), the
// game-control power script and RCON (the same calls worker/cyrus-delivery.ts makes). SERVER ONLY.
//
// Config (all required for the API to answer anything; missing = every call 401, fail closed):
//   CYRUS_PLATFORM_KEYS                    "keyId:secret[,keyId:secret]" HMAC keys of the Cyrus client (secret >= 32
//                                          chars, never AUTH_SECRET); two entries during a rotation
//   CYRUS_PLATFORM_ASSERTION_PUBLIC_KEY    Cyrus' Ed25519 PUBLIC key (PEM, "\n" escapes allowed) for user assertions;
//   CYRUS_PLATFORM_ASSERTION_PUBLIC_KEY_NEXT  optional second key during a rotation
//   CYRUS_GUEST_MC_BASE / CYRUS_GUEST_STATE_DIR  guest layout (defaults /opt/mc and /root/.nxeon-cyrus, as lib/cyrus/config)
import { createPublicKey, type KeyObject } from "node:crypto";
import { db } from "../db";
import { SANDBOX } from "../sandbox";
import { checkRateLimit } from "../rate-limit";
import type { InventoryRecord, LiveStatus, PlatformDeps, PlatformEvent, PlatformFs } from "./api";
import type { GrantStore } from "./grants";
import type { PlatformClient } from "./scopes";
import { serversByIds } from "./servers";

type Env = Record<string, string | undefined>;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const trim = (p: string) => (p.length > 1 ? p.replace(/\/+$/, "") : p);

export function platformKeys(env: Env = process.env): Map<string, string> {
  const out = new Map<string, string>();
  for (const part of (env.CYRUS_PLATFORM_KEYS ?? "").split(",").map((s) => s.trim()).filter(Boolean)) {
    const i = part.indexOf(":");
    const id = part.slice(0, i), secret = part.slice(i + 1);
    if (i > 0 && /^[a-z0-9]{4,32}$/.test(id) && secret.length >= 32 && secret !== env.AUTH_SECRET) out.set(id, secret);
  }
  return out;
}
export function assertionPublicKeys(env: Env = process.env): KeyObject[] {
  const out: KeyObject[] = [];
  for (const name of ["CYRUS_PLATFORM_ASSERTION_PUBLIC_KEY", "CYRUS_PLATFORM_ASSERTION_PUBLIC_KEY_NEXT"]) {
    const pem = env[name];
    if (!pem) continue;
    try { const k = createPublicKey(pem.replace(/\\n/g, "\n")); if (k.asymmetricKeyType === "ed25519") out.push(k); } catch { console.error(`[platform-api] ${name} is not a valid Ed25519 public key`); }
  }
  return out;
}
export const guestLayoutDefaults = (env: Env = process.env) => ({
  base: trim(env.CYRUS_GUEST_MC_BASE?.trim() || "/opt/mc"),
  stateDir: trim(env.CYRUS_GUEST_STATE_DIR?.trim() || "/root/.nxeon-cyrus"),
});

const loadServer = (id: string) => db.server.findFirst({ where: { id, status: { notIn: ["DELETING"] } }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });

/** The Minecraft log's Done line after a restart (same rule as the delivery worker). */
const cameUp = (log: string) => /\bDone \(\d/.test(log);

export function nxeonPlatformDeps(a: { store: GrantStore; env?: Env; onEvent?: (e: PlatformEvent) => Promise<void>; entitlements?: PlatformDeps["entitlements"] }): PlatformDeps {
  const env = a.env ?? process.env;
  const keys = platformKeys(env);
  const pub = assertionPublicKeys(env);
  const layoutDefaults = guestLayoutDefaults(env);

  async function rcon(serverId: string, command: string): Promise<{ ok: true; reply: string } | { ok: false; error: string }> {
    if (SANDBOX) return { ok: false, error: "no console in the sandbox" };
    const server = await loadServer(serverId);
    if (!server) return { ok: false, error: "server gone" };
    const { controlSpec, runRcon } = await import("../game-control");
    const { withServerSsh } = await import("../ssh-exec");
    const spec = controlSpec("minecraft");
    if (!spec) return { ok: false, error: "no control spec for minecraft" };
    try { const r = await withServerSsh(server as never, (conn) => runRcon(conn, spec, command)); return r.ok ? { ok: true, reply: r.response } : { ok: false, error: r.error }; }
    catch (e) { return { ok: false, error: (e as Error).message }; }
  }

  async function open(serverId: string): Promise<{ fs: PlatformFs; layout: { base: string; levelName: string; clientStateDir: string }; close?: () => void } | null> {
    const server = await loadServer(serverId);
    if (!server) return null;
    let fs: PlatformFs & { close?: () => void };
    if (SANDBOX) {
      const { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest } = await import("../mods/guest-fs");
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
      fs = local;
    } else {
      const { SshGuestFs } = await import("../../worker/mods-guest-ssh");
      fs = await SshGuestFs.open(server as never);
    }
    const props = (await fs.readFile(`${layoutDefaults.base}/server.properties`, 256 * 1024).catch(() => null))?.toString("utf8") ?? "";
    const levelName = /^level-name=([A-Za-z0-9_-]{1,64})\s*$/m.exec(props)?.[1] ?? "world";
    return { fs, layout: { base: layoutDefaults.base, levelName, clientStateDir: layoutDefaults.stateDir }, close: () => fs.close?.() };
  }

  return {
    store: a.store,
    keys: { secretFor: (id) => keys.get(id) ?? null, clientOf: (id): PlatformClient | null => (keys.has(id) ? "cyrus" : null) },
    assertionKeys: () => pub,
    servers: {
      get: async (userId, serverId) => (await serversByIds(userId, [serverId]))[0] ?? null,
      many: (userId, ids) => serversByIds(userId, ids),
      async live(serverId): Promise<LiveStatus | null> {
        const list = await rcon(serverId, "list");
        if (!list.ok) return { online: false, answered: false, players: null, maxPlayers: null, datapacksLoaded: [] };
        const m = /There are (\d+) of a max(?: of)? (\d+) players/i.exec(list.reply);
        const dps = await rcon(serverId, "datapack list enabled");
        return { online: true, answered: true, players: m ? Number(m[1]) : null, maxPlayers: m ? Number(m[2]) : null, datapacksLoaded: dps.ok ? [...dps.reply.matchAll(/file\/([A-Za-z0-9_.-]+?\.zip)/g)].map((x) => `file/${x[1]}`) : [] };
      },
    },
    open,
    async records(serverId): Promise<InventoryRecord[]> {
      const rows = await db.serverMod.findMany({ where: { serverId, status: { notIn: ["REMOVED"] } }, include: { mod: { select: { name: true, source: true, sourceId: true } } }, orderBy: { installedAt: "asc" }, take: 500 });
      return rows.map((r) => ({
        name: r.mod.name, version: r.version ?? null, source: r.mod.source, sourceId: r.mod.sourceId ?? null, status: r.status, fileName: r.fileName ?? null,
        via: r.mod.source === "cyrus" ? "cyrus" : r.mod.source === "nxeon-managed" ? "managed" : r.mod.source ? "mods-tab" : "other",
      }));
    },
    power: {
      async restart(serverId) {
        if (SANDBOX) return { ok: true, cameUp: false };
        const server = await loadServer(serverId);
        if (!server) return { ok: false, error: "server gone" };
        const { controlSpec } = await import("../game-control");
        const { withServerSsh, exec } = await import("../ssh-exec");
        const { powerScript } = await import("../../worker/game-control");
        const spec = controlSpec("minecraft");
        if (!spec) return { ok: false, error: "no control spec for minecraft" };
        const o = await open(serverId);
        const logPath = `${layoutDefaults.base}/logs/latest.log`;
        const readLog = async () => (o ? (await o.fs.readFile(logPath, 8 * 1024 * 1024).catch(() => null))?.toString("utf8") ?? "" : "");
        try {
          const before = await readLog();
          const r = await withServerSsh(server as never, (conn) => exec(conn, powerScript(spec, "restart"), 90_000));
          const rc = /NXGP:RC:(\d+)/.exec(r.stdout)?.[1];
          if (/NXGP:UNIT:NONE/.test(r.stdout)) return { ok: false, error: "the game service was not found" };
          if (rc !== "0") return { ok: false, error: `systemctl restart exited ${rc ?? "?"}` };
          const until = Date.now() + 300_000;
          while (Date.now() < until) {
            await sleep(5000);
            const now = await readLog();
            if (now && now !== before && (cameUp(now) || /Stopping server|FATAL|Registry loading errors/.test(now))) return { ok: true, cameUp: cameUp(now) };
          }
          return { ok: true, cameUp: false };
        } catch (e) { return { ok: false, error: (e as Error).message }; }
        finally { o?.close?.(); }
      },
      console: rcon,
    },
    entitlements: a.entitlements,
    onEvent: a.onEvent,
    rateLimit: (key, o) => checkRateLimit(key, o),
  };
}

