// CYRUS SIDE of the Nxeon Platform API v1: a typed client for the per-server primitives Nxeon serves at
// /api/platform/cyrus/v1 (lib/nxeon-platform/api.ts; contract docs/api/nxeon-platform-v1.openapi.yaml). Used by the
// HTTP host adapter (createHttpHost({ platform })) and by lib/cyrus/host/platform-session.ts, which turns a granted
// server into a delivery ServerSession so the orchestrator (journal, rollback) runs unchanged over HTTP.
//   auth   HMAC request signature with Cyrus' service key (../api/v1/signing signRequest) + an Ed25519 USER ASSERTION
//          Cyrus signs per attempt (sub = the Nxeon user id, aud nxeon-platform-v1, 60 s, single-use jti).
//   writes always carry an Idempotency-Key that stays the same across retries (Nxeon applies them once).
//   ops    every call of one delivery can carry the same operation id (nxeon-op-id); after the user revokes the grant,
//          that operation may still undo its own changes (nxeon-op-mode: rollback) for 15 minutes, nothing else.
// SERVER ONLY. HOST SEAM: no platform imports.
import { randomBytes, sign as edSign, type KeyObject } from "node:crypto";
import { signRequest } from "../api/v1/signing";

export const PLATFORM_API_PREFIX = "/api/platform/cyrus/v1";
export const PLATFORM_AUD = "nxeon-platform-v1";
/** The client's view of the operation table (pinned to the OpenAPI file by test/cyrus-platform-contract.test.ts). */
export const PLATFORM_CLIENT_OPERATIONS = {
  health: ["GET", "/health"], listGrants: ["GET", "/grants"], getEntitlements: ["GET", "/entitlements"],
  listServers: ["GET", "/servers"], getServer: ["GET", "/servers/{serverId}"], getInventory: ["GET", "/servers/{serverId}/inventory"],
  statFile: ["GET", "/servers/{serverId}/files/stat"], readFile: ["GET", "/servers/{serverId}/files/read"], listDir: ["GET", "/servers/{serverId}/files/list"],
  writeFile: ["POST", "/servers/{serverId}/files/write"], deleteFile: ["POST", "/servers/{serverId}/files/delete"], makeDir: ["POST", "/servers/{serverId}/files/mkdir"],
  renameFile: ["POST", "/servers/{serverId}/files/rename"], copyFile: ["POST", "/servers/{serverId}/files/copy"],
  reload: ["POST", "/servers/{serverId}/reload"], restart: ["POST", "/servers/{serverId}/restart"], logTail: ["GET", "/servers/{serverId}/logs/tail"], setPack: ["POST", "/servers/{serverId}/pack"],
} as const;
export type PlatformOp = keyof typeof PLATFORM_CLIENT_OPERATIONS;

export type PlatformScope = "servers.read" | "inventory.read" | "files.write.mods" | "server.reload" | "server.restart" | "logs.read.tail" | "pack.set";
export type PlatformGrant = { grantId: string; serverId: string; scopes: PlatformScope[]; consentVersion: string; createdAt: string; restartBudget: { perHour: number; perDay: number } };
export type PlatformServer = {
  id: string; name: string; game: string | null; loader: string | null; version: string | null; status: string;
  ramMB: number | null; cpuCores: number | null; slots: number | null; supported: boolean; reason: string | null;
  grant: { grantId: string; scopes: PlatformScope[] };
  live?: { online: boolean; answered: boolean; players: number | null; maxPlayers: number | null; datapacksLoaded: string[] } | null;
};
export type PlatformInventory = {
  layout: { base: string; levelName: string; clientStateDir: string | null };
  records: { name: string; version: string | null; source: string; sourceId: string | null; status: string; fileName: string | null; via: "mods-tab" | "cyrus" | "managed" | "other" }[];
  files: { path: string; area: string; size: number; sha256: string | null }[];
};
export type PlatformStat = { type: "file" | "dir"; size: number; sha256: string | null } | null;
/** sha256 of the bytes being replaced, "absent" (must not exist), or "dir" (deleting a folder). */
export type IfMatch = string;

export class PlatformError extends Error {
  constructor(public status: number, public code: string, message: string, public op: string, public detail: Record<string, unknown> = {}) {
    super(`${op}: ${message}`);
    this.name = "PlatformError";
  }
}

export type PlatformClientOptions = {
  /** e.g. https://nxeon.cloud/api/platform/cyrus/v1 (required, no default) */
  baseUrl: string;
  keyId: string;
  secret: string;
  /** Cyrus' Ed25519 PRIVATE key for user assertions (Nxeon holds the public key) */
  signingKey: KeyObject;
  client?: "cyrus";
  fetch?: typeof fetch;
  now?: () => number;
  sleep?: (ms: number) => Promise<void>;
  timeoutMs?: number;
  /** extra attempts after the first for 429/502/503/504/network (default 2) */
  retries?: number;
};
export type CallOpts = { opId?: string | null; rollback?: boolean; idemKey?: string };

const RETRY = new Set([429, 502, 503, 504]);
const b64u = (b: Buffer | string) => Buffer.from(b).toString("base64url");

/** Mint one user assertion (exported for tests and the fake platform). */
export function mintPlatformAssertion(a: { sub: string; client?: string; key: KeyObject; nowMs: number; ttlS?: number }): string {
  const iat = Math.floor(a.nowMs / 1000);
  const claims = { v: 1, iss: a.client ?? "cyrus", sub: a.sub, aud: PLATFORM_AUD, iat, exp: iat + Math.min(a.ttlS ?? 60, 120), jti: randomBytes(12).toString("base64url") };
  const p = b64u(JSON.stringify(claims));
  return `${p}.${b64u(edSign(null, Buffer.from(p), a.key))}`;
}

export function createPlatformClient(o: PlatformClientOptions) {
  if (!/^https?:\/\//.test(o.baseUrl)) throw new Error("createPlatformClient: baseUrl must be an http(s) URL");
  const base = o.baseUrl.replace(/\/+$/, "");
  const doFetch = o.fetch ?? fetch;
  const now = o.now ?? Date.now;
  const sleep = o.sleep ?? ((ms: number) => new Promise<void>((r) => setTimeout(r, ms)));
  const timeoutMs = o.timeoutMs ?? 120_000, retries = o.retries ?? 2;

  async function call<T>(op: PlatformOp, a: { userId?: string; serverId?: string; query?: Record<string, string | number | undefined>; body?: Record<string, unknown>; opts?: CallOpts } = {}): Promise<T> {
    const [method, tpl] = PLATFORM_CLIENT_OPERATIONS[op];
    const url = new URL(base + tpl.replace("{serverId}", encodeURIComponent(a.serverId ?? "")));
    for (const [k, v] of Object.entries(a.query ?? {})) if (v !== undefined) url.searchParams.set(k, String(v));
    const body = method === "POST" ? JSON.stringify(a.body ?? {}) : "";
    const idem = method === "POST" ? a.opts?.idemKey ?? randomBytes(16).toString("base64url") : null;
    let last: PlatformError | null = null;
    for (let attempt = 0; attempt <= retries; attempt++) {
      if (attempt) await sleep(Math.min(5000, 250 * 2 ** (attempt - 1)));
      const headers: Record<string, string> = {
        ...signRequest({ keyId: o.keyId, secret: o.secret, method, pathWithQuery: url.pathname + url.search, body, nowMs: now() }),
        accept: "application/json",
        ...(a.userId ? { "nxeon-user-assertion": mintPlatformAssertion({ sub: a.userId, client: o.client, key: o.signingKey, nowMs: now() }) } : {}),
        ...(a.opts?.opId ? { "nxeon-op-id": a.opts.opId } : {}),
        ...(a.opts?.rollback ? { "nxeon-op-mode": "rollback" } : {}),
        ...(idem ? { "idempotency-key": idem, "content-type": "application/json" } : {}),
      };
      const ac = new AbortController();
      const timer = setTimeout(() => ac.abort(), timeoutMs);
      try {
        const res = await doFetch(url, { method, headers, body: method === "POST" ? body : undefined, signal: ac.signal });
        const text = await res.text();
        let parsed: { ok: boolean; data?: unknown; error?: { code: string; message: string } & Record<string, unknown> } | null = null;
        try { parsed = JSON.parse(text); } catch { /* not JSON */ }
        if (res.ok && parsed?.ok) return parsed.data as T;
        const { code = "bad_reply", message = `HTTP ${res.status}`, ...detail } = parsed?.error ?? {};
        const e = new PlatformError(res.status, code, message, op, detail);
        if (!RETRY.has(res.status)) throw e;
        last = e;
      } catch (e) {
        if (e instanceof PlatformError && !RETRY.has(e.status)) throw e;
        if (!(e instanceof PlatformError)) last = new PlatformError(0, ac.signal.aborted ? "timeout" : "network", ac.signal.aborted ? `no answer within ${timeoutMs} ms` : (e as Error).message, op);
      } finally { clearTimeout(timer); }
    }
    throw last ?? new PlatformError(0, "network", "failed", op);
  }

  /** Everything Cyrus does for one signed-in user. */
  function as(userId: string) {
    const s = (serverId: string) => ({ userId, serverId });
    return {
      userId,
      grants: () => call<PlatformGrant[]>("listGrants", { userId }),
      entitlements: () => call<unknown>("getEntitlements", { userId }),
      servers: () => call<PlatformServer[]>("listServers", { userId }),
      server: (serverId: string, o: { live?: boolean } = {}) => call<PlatformServer>("getServer", { ...s(serverId), query: { live: o.live ? 1 : undefined } }),
      inventory: (serverId: string, opts?: CallOpts) => call<PlatformInventory>("getInventory", { ...s(serverId), opts }),
      stat: (serverId: string, path: string, opts?: CallOpts) => call<PlatformStat>("statFile", { ...s(serverId), query: { path }, opts }),
      async read(serverId: string, path: string, maxBytes?: number, opts?: CallOpts): Promise<{ data: Buffer; sha256: string } | null> {
        const r = await call<{ dataB64: string; sha256: string } | null>("readFile", { ...s(serverId), query: { path, maxBytes }, opts });
        return r ? { data: Buffer.from(r.dataB64, "base64"), sha256: r.sha256 } : null;
      },
      list: (serverId: string, path: string, opts?: CallOpts) => call<string[]>("listDir", { ...s(serverId), query: { path }, opts }),
      write: (serverId: string, a: { path: string; data: Buffer; ifMatch: IfMatch }, opts?: CallOpts) => call<{ path: string; size: number; sha256: string }>("writeFile", { ...s(serverId), body: { path: a.path, dataB64: a.data.toString("base64"), ifMatch: a.ifMatch }, opts }),
      remove: (serverId: string, a: { path: string; ifMatch: IfMatch }, opts?: CallOpts) => call<{ path: string; removed: boolean }>("deleteFile", { ...s(serverId), body: a, opts }),
      mkdir: (serverId: string, path: string, opts?: CallOpts) => call<{ path: string; created: boolean }>("makeDir", { ...s(serverId), body: { path }, opts }),
      rename: (serverId: string, a: { from: string; to: string; ifMatch: IfMatch; toIfMatch: IfMatch }, opts?: CallOpts) => call<{ from: string; to: string }>("renameFile", { ...s(serverId), body: a, opts }),
      copy: (serverId: string, a: { from: string; to: string; toIfMatch: IfMatch }, opts?: CallOpts) => call<{ from: string; to: string }>("copyFile", { ...s(serverId), body: a, opts }),
      reload: (serverId: string, a: { kind: "datapacks" } | { kind: "plugin"; plugin: string }, opts?: CallOpts) => call<{ command: string; reply: string }>("reload", { ...s(serverId), body: a, opts }),
      restart: (serverId: string, opts?: CallOpts) => call<{ restarted: true; cameUp: boolean }>("restart", { ...s(serverId), opts }),
      logTail: (serverId: string, lines = 200, opts?: CallOpts) => call<{ lines: string[]; truncated: boolean }>("logTail", { ...s(serverId), query: { lines }, opts }),
      setPack: (serverId: string, a: { url: string; sha1: string; required: boolean; prompt?: string | null }, opts?: CallOpts) => call<{ changed: boolean; restartRequired: boolean }>("setPack", { ...s(serverId), body: a, opts }),
    };
  }
  return { health: () => call<{ version: string }>("health"), as, call };
}
export type PlatformClient = ReturnType<typeof createPlatformClient>;
export type PlatformUser = ReturnType<PlatformClient["as"]>;

