// CYRUS SIDE: a granted Nxeon server as the delivery orchestrator sees it, built ONLY from Platform API primitives
// (./platform.ts). The orchestrator (lib/cyrus/delivery: journal, health check, rollback) runs unchanged on top:
//   fs        PlatformTxnFs: every mutation names the bytes it replaces (ifMatch from what this session last saw, or a
//             fresh stat), so a file the user changed meanwhile is never overwritten blind (412 -> the delivery fails
//             and rolls back). When Nxeon answers grant_revoked mid-delivery, the fs switches to ROLLBACK mode: the
//             orchestrator's rollback then runs with nxeon-op-mode: rollback, which Nxeon allows only for paths this
//             same operation changed (15 minutes).
//   restart   the budgeted restart primitive (absent scope -> an honest failure, the delivery says so)
//   console   only what server.reload allows: minecraft:reload and "<plugin> reload"; absent without the scope
//   health    the boot log through logs.read.tail + the live probe of servers.read
// SERVER ONLY. HOST SEAM: no platform imports.
import { createHash, randomBytes } from "node:crypto";
import type { DeliveryHost, HealthReport, JarPort, ManagedPort, ServerSession, TxnFs } from "../delivery/types";
import { parseBootLog } from "../delivery/bootlog";
import { PlatformError, type CallOpts, type PlatformScope, type PlatformUser } from "./platform";

const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
type Known = string | "absent" | "dir";

export class PlatformTxnFs implements TxnFs {
  readonly kind = "ssh" as const;
  private known = new Map<string, Known>();
  /** true once Nxeon said the grant was revoked: from then on only this operation's undo is attempted */
  rollback = false;
  readonly opId: string;
  constructor(readonly api: PlatformUser, readonly serverId: string, o: { opId?: string; onRevoked?: () => void } = {}) {
    this.opId = o.opId ?? `op_${randomBytes(12).toString("hex")}`;
    this.onRevoked = o.onRevoked;
  }
  private onRevoked?: () => void;
  private opts(): CallOpts { return { opId: this.opId, rollback: this.rollback }; }
  private async guard<T>(fn: () => Promise<T>): Promise<T> {
    try { return await fn(); } catch (e) {
      if (e instanceof PlatformError && e.code === "grant_revoked" && !this.rollback) { this.rollback = true; this.onRevoked?.(); }
      throw e;
    }
  }
  private forget(prefix: string) { for (const k of [...this.known.keys()]) if (k === prefix || k.startsWith(prefix + "/")) this.known.delete(k); }
  private async current(p: string): Promise<Known> {
    const k = this.known.get(p);
    if (k !== undefined) return k;
    const st = await this.guard(() => this.api.stat(this.serverId, p, this.opts()));
    const v: Known = !st ? "absent" : st.type === "dir" ? "dir" : st.sha256 ?? "absent";
    if (st && st.type === "file" && !st.sha256) throw new PlatformError(413, "too_large", `${p} is too large to replace safely`, "statFile");
    this.known.set(p, v);
    return v;
  }

  async stat(p: string) {
    const st = await this.guard(() => this.api.stat(this.serverId, p, this.opts()));
    this.known.set(p, !st ? "absent" : st.type === "dir" ? "dir" : st.sha256 ?? "absent");
    return st ? { type: st.type, size: st.size } : null;
  }
  async readFile(p: string, maxBytes?: number) {
    const r = await this.guard(() => this.api.read(this.serverId, p, maxBytes, this.opts()));
    this.known.set(p, r ? r.sha256 : "absent");
    return r?.data ?? null;
  }
  list(dir: string) { return this.guard(() => this.api.list(this.serverId, dir, this.opts())); }
  async writeFile(p: string, data: Buffer) {
    const ifMatch = await this.current(p);
    if (ifMatch === "dir") throw new PlatformError(409, "is_directory", `${p} is a folder`, "writeFile");
    await this.guard(() => this.api.write(this.serverId, { path: p, data, ifMatch }, this.opts()));
    this.known.set(p, sha(data));
  }
  async mkdirp(p: string) {
    await this.guard(() => this.api.mkdir(this.serverId, p, this.opts()));
    this.known.set(p, "dir");
  }
  async rename(from: string, to: string) {
    const ifMatch = await this.current(from), toIfMatch = await this.current(to);
    await this.guard(() => this.api.rename(this.serverId, { from, to, ifMatch, toIfMatch }, this.opts()));
    this.known.set(to, ifMatch); this.known.set(from, "absent");
  }
  async remove(p: string) {
    const ifMatch = await this.current(p);
    await this.guard(() => this.api.remove(this.serverId, { path: p, ifMatch }, this.opts()));
    this.forget(p); this.known.set(p, "absent");
  }
  async copy(from: string, to: string) {
    const toIfMatch = await this.current(to);
    await this.guard(() => this.api.copy(this.serverId, { from, to, toIfMatch }, this.opts()));
