export type PlatformSessionOptions = { opId?: string; onRevoked?: () => void; logLines?: number };

/** Open a granted server for one delivery. Throws PlatformError when the grant is missing/revoked or the scopes are short. */
export async function openPlatformSession(api: PlatformUser, serverId: string, o: PlatformSessionOptions = {}): Promise<ServerSession & { fs: PlatformTxnFs; scopes: PlatformScope[] }> {
  const server = await api.server(serverId);
  const scopes = server.grant.scopes;
  if (!scopes.includes("files.write.mods")) throw new PlatformError(403, "scope_missing", "this connection does not allow installing files (files.write.mods)", "open");
  const fs = new PlatformTxnFs(api, serverId, { opId: o.opId, onRevoked: o.onRevoked });
  const inv = await api.inventory(serverId, { opId: fs.opId });
  const can = (s: PlatformScope) => scopes.includes(s);
  const logText = async () => (can("logs.read.tail") ? (await api.logTail(serverId, o.logLines ?? 2000, { opId: fs.opId, rollback: fs.rollback })).lines.join("\n") : "");
  const session: ServerSession & { fs: PlatformTxnFs; scopes: PlatformScope[] } = {
    fs, scopes, base: inv.layout.base, levelName: inv.layout.levelName, mcVersion: server.version,
    async restart() {
      if (!can("server.restart")) return { ok: false, error: "this connection does not allow restarts (server.restart): restart the server yourself to finish" };
      try { await api.restart(serverId, { opId: fs.opId, rollback: fs.rollback }); return { ok: true }; }
      catch (e) { if (e instanceof PlatformError && e.code === "grant_revoked") fs.rollback = true; return { ok: false, error: (e as Error).message }; }
    },
    async health(): Promise<HealthReport> {
      const log = parseBootLog(await logText().catch(() => ""));
      const live = await api.server(serverId, { live: true }).then((s) => s.live ?? null).catch(() => null);
      return {
        real: true, cameUp: log.cameUp, answered: !!live?.answered, pluginsEnabled: log.enabled, errorLines: log.errors, datapacksLoaded: live?.datapacksLoaded ?? [],
        evidence: [can("logs.read.tail") ? (log.cameUp ? "Done line found" : "no Done line") : "no log access (logs.read.tail)", live ? (live.answered ? "answers list" : "does not answer") : "no live probe"],
      };
    },
    async baselineErrors() { return parseBootLog(await logText().catch(() => "")).errors; },
  };
  if (can("server.reload")) {
    session.console = async (command: string) => {
      const m = /^([a-z0-9_-]{2,32}) reload$/.exec(command);
      const arg = command === "minecraft:reload" ? { kind: "datapacks" as const } : m ? { kind: "plugin" as const, plugin: m[1] } : null;
      if (!arg) return { ok: false, error: "only reload commands are available through the Nxeon Platform API" };
      try { const r = await api.reload(serverId, arg, { opId: fs.opId, rollback: fs.rollback }); return { ok: true, reply: r.reply }; }
      catch (e) { return { ok: false, error: (e as Error).message }; }
    };
  }
  return session;
}

/** A plugin jar placed like every installer does (new name + rename), through the journaled fs only. */
export const platformJarPort: JarPort = {
  async install({ fs, base, release, previous }) {
    if (!release.plugin) return { ok: false, error: "this release has no plugin jar" };
    const target = `${base}/plugins/${release.plugin.jarName}`;
    if (previous?.jar && previous.jar.target !== target && (await fs.stat(previous.jar.target))) await fs.remove(previous.jar.target);
    await fs.writeFile(`${target}.nxeon-part`, release.plugin.bytes);
    await fs.rename(`${target}.nxeon-part`, target);
    return { ok: true, target };
  },
  async remove({ fs, record }) {
    if (record.jar && (await fs.stat(record.jar.target))) await fs.remove(record.jar.target);
    return { ok: true };
  },
};
const noManaged: ManagedPort = {
  async ensure() { return { ok: false, error: "managed plugins over the Platform API need Cyrus' managed installer (platformDeliveryHost({ managed }))" }; },
  async release() { return { ok: true, action: "not_held" }; },
  async snapshot() { return null; },
  async restore() { return { ok: true }; },
};

/** The orchestrator's DeliveryHost for ONE granted server through the Platform API (standalone Cyrus). */
export function platformDeliveryHost(a: { api: PlatformUser; serverId: string; opId?: string; managed?: ManagedPort; packs?: DeliveryHost["packs"]; env?: DeliveryHost["env"]; onRevoked?: () => void }): DeliveryHost & { opened(): (ServerSession & { fs: PlatformTxnFs }) | null } {
  let last: (ServerSession & { fs: PlatformTxnFs }) | null = null;
  return {
    env: a.env,
    async open() { last = await openPlatformSession(a.api, a.serverId, { opId: a.opId, onRevoked: a.onRevoked }); return last; },
    opened: () => last,
    managed: a.managed ?? noManaged,
    jar: platformJarPort,
    ...(a.packs ? { packs: a.packs } : {}),
  };
}

