// NXEON SIDE: the OpenAPI 3.1 document of the Platform API v1, built from PLATFORM_OPERATIONS (never hand-copied).
// tools/nxeon-platform/gen-openapi.ts writes docs/api/nxeon-platform-v1.openapi.yaml; the contract test pins it.
import { PLATFORM_API_PREFIX, PLATFORM_API_VERSION, PLATFORM_OPERATIONS, H, type PlatformOperation } from "./api";
import { LIMITS, RESTART_BUDGET, SCOPES, SCOPE_INFO } from "./scopes";
import { ENTITLEMENT_SCHEMA } from "./entitlement-schema";

type J = Record<string, unknown>;
const str = (description?: string, extra: J = {}): J => ({ type: "string", ...(description ? { description } : {}), ...extra });
const obj = (properties: J, required: string[] = Object.keys(properties)): J => ({ type: "object", additionalProperties: false, required, properties });
const nullable = (s: J): J => ({ oneOf: [s, { type: "null" }] });
const sha = str("sha256, lower-case hex", { pattern: "^[a-f0-9]{64}$" });
const ifMatch = str("the sha256 of the bytes being replaced, \"absent\" (must not exist) or \"dir\" (a folder, deletes only)", { pattern: "^([a-f0-9]{64}|absent|dir)$" });
const path = str(`absolute guest path inside the allow-list (max ${LIMITS.maxPathLength} chars)`, { maxLength: LIMITS.maxPathLength });

const SERVER: J = obj({
  id: str(), name: str(), game: nullable(str()), loader: nullable(str()), version: nullable(str()), status: str("PENDING | PROVISIONING | RUNNING | STOPPED | SUSPENDED | REINSTALLING | ERROR"),
  ramMB: nullable({ type: "integer" }), cpuCores: nullable({ type: "integer" }), slots: nullable({ type: "integer" }), supported: { type: "boolean" }, reason: nullable(str()),
  grant: obj({ grantId: str(), scopes: { type: "array", items: { $ref: "#/components/schemas/Scope" } } }),
  live: nullable(obj({ online: { type: "boolean" }, answered: { type: "boolean" }, players: nullable({ type: "integer" }), maxPlayers: nullable({ type: "integer" }), datapacksLoaded: { type: "array", items: str() } })),
}, ["id", "name", "game", "loader", "version", "status", "ramMB", "cpuCores", "slots", "supported", "reason", "grant"]);

const RESPONSES: Record<PlatformOperation, J> = {
  health: obj({ version: str() }),
  listGrants: { type: "array", items: obj({ grantId: str(), serverId: str(), scopes: { type: "array", items: { $ref: "#/components/schemas/Scope" } }, consentVersion: str(), createdAt: str(undefined, { format: "date-time" }), restartBudget: obj({ perHour: { type: "integer" }, perDay: { type: "integer" } }) }) },
  getEntitlements: { $ref: "#/components/schemas/Entitlement" },
  listServers: { type: "array", items: { $ref: "#/components/schemas/Server" } },
  getServer: { $ref: "#/components/schemas/Server" },
  getInventory: obj({
    layout: obj({ base: str(), levelName: str(), clientStateDir: nullable(str()) }),
    records: { type: "array", items: obj({ name: str(), version: nullable(str()), source: str(), sourceId: nullable(str()), status: str(), fileName: nullable(str()), via: str("mods-tab | cyrus | managed | other", { enum: ["mods-tab", "cyrus", "managed", "other"] }) }) },
    files: { type: "array", items: obj({ path: str(), area: str(), size: { type: "integer" }, sha256: nullable(sha) }) },
  }),
  statFile: nullable(obj({ type: str(undefined, { enum: ["file", "dir"] }), size: { type: "integer" }, sha256: nullable(sha) })),
  readFile: nullable(obj({ size: { type: "integer" }, sha256: sha, dataB64: str("base64") })),
  listDir: { type: "array", items: str(), maxItems: LIMITS.maxListEntries },
  writeFile: obj({ path: str(), size: { type: "integer" }, sha256: sha }),
  deleteFile: obj({ path: str(), removed: { type: "boolean" } }),
  makeDir: obj({ path: str(), created: { type: "boolean" } }),
  renameFile: obj({ from: str(), to: str() }),
  copyFile: obj({ from: str(), to: str() }),
  reload: obj({ command: str(), reply: str() }),
  restart: obj({ restarted: { type: "boolean", const: true }, cameUp: { type: "boolean" } }),
  logTail: obj({ lines: { type: "array", items: str(), maxItems: LIMITS.maxLogLines }, truncated: { type: "boolean" } }),
  setPack: obj({ changed: { type: "boolean" }, restartRequired: { type: "boolean" }, previous: { type: "object", additionalProperties: str() } }, ["changed", "restartRequired"]),
};
const BODIES: Partial<Record<PlatformOperation, J>> = {
  writeFile: obj({ path, dataB64: str(`base64, at most ${LIMITS.maxFileBytes} bytes decoded`), ifMatch }),
  deleteFile: obj({ path, ifMatch }),
  makeDir: obj({ path }),
  renameFile: obj({ from: path, to: path, ifMatch, toIfMatch: ifMatch }),
  copyFile: obj({ from: path, to: path, toIfMatch: ifMatch }),
  reload: { oneOf: [obj({ kind: str(undefined, { const: "datapacks" }) }), obj({ kind: str(undefined, { const: "plugin" }), plugin: str("the plugin's own lower-case command, e.g. bettermodel", { pattern: "^[a-z0-9_-]{2,32}$" }) })] },
  restart: obj({}, []),
  setPack: obj({ url: str("https URL of the pack zip"), sha1: str("sha1 of the zip", { pattern: "^[a-f0-9]{40}$" }), required: { type: "boolean" }, prompt: nullable(str(undefined, { maxLength: 200 })) }, ["url", "sha1", "required"]),
};
const QUERY: Partial<Record<PlatformOperation, J[]>> = {
  getServer: [{ name: "live", in: "query", required: false, schema: str(undefined, { enum: ["1"] }), description: "also probe the running server (RCON list, loaded data packs)" }],
  statFile: [{ name: "path", in: "query", required: true, schema: path }],
  readFile: [{ name: "path", in: "query", required: true, schema: path }, { name: "maxBytes", in: "query", required: false, schema: { type: "integer", maximum: LIMITS.maxReadBytes } }],
  listDir: [{ name: "path", in: "query", required: true, schema: path }],
  logTail: [{ name: "lines", in: "query", required: false, schema: { type: "integer", minimum: 1, maximum: LIMITS.maxLogLines, default: 200 } }],
};
const ERROR_CODES = ["unauthorized", "bad_assertion", "unknown_operation", "no_grant", "grant_revoked", "scope_missing", "rollback_only", "server_gone", "server_unreachable", "path_refused", "precondition_required", "precondition_failed", "is_directory", "not_directory", "is_file", "not_found", "too_large", "rate_limited", "budget_exhausted", "idempotency_key_required", "idempotency_mismatch", "bad_request", "console_failed", "restart_failed", "not_available", "host_error"];

export function buildPlatformOpenApi(): J {
  const paths: J = {};
  for (const [name, d] of Object.entries(PLATFORM_OPERATIONS) as [PlatformOperation, (typeof PLATFORM_OPERATIONS)[PlatformOperation]][]) {
    const params: J[] = [];
    if (d.server) params.push({ name: "serverId", in: "path", required: true, schema: str(undefined, { pattern: "^[A-Za-z0-9_-]{4,64}$" }) });
    if (d.user) params.push({ $ref: "#/components/parameters/UserAssertion" }, { $ref: "#/components/parameters/OpId" }, { $ref: "#/components/parameters/OpMode" });
    if (d.method === "POST") params.push({ $ref: "#/components/parameters/IdempotencyKey" });
    params.push(...(QUERY[name] ?? []));
    const op: J = {
      operationId: name, summary: d.summary,
      "x-nxeon-scope": d.scope ?? "none", "x-nxeon-mutation": d.mutation,
      security: [{ ServiceSignature: [] }],
      parameters: params,
      responses: {
        "200": { description: "ok", content: { "application/json": { schema: obj({ ok: { type: "boolean", const: true }, data: RESPONSES[name] }) } } },
        default: { description: "error (see components.schemas.Error.code)", content: { "application/json": { schema: { $ref: "#/components/schemas/Error" } } } },
      },
    };
    if (BODIES[name]) op.requestBody = { required: true, content: { "application/json": { schema: BODIES[name] } } };
    const p = PLATFORM_API_PREFIX + d.path;
    paths[p] = { ...((paths[p] as J) ?? {}), [d.method.toLowerCase()]: op };
  }
  return {
    openapi: "3.1.0",
    info: {
      title: "Nxeon Platform API (for Cyrus)", version: PLATFORM_API_VERSION,
      description: `Per-server primitives a connected app uses on a customer's game server. Every call: HMAC service signature (headers cyrus-key-id, cyrus-timestamp, cyrus-nonce, cyrus-signature = v1=hex HMAC-SHA256(secret, METHOD\\npath?query\\nts\\nnonce\\nsha256(body)), 300 s window, nonce once), then for user calls an Ed25519 user assertion (${H.assertion}: b64url(claims).b64url(sig), claims {v:1, iss:"cyrus", sub:<Nxeon user id>, aud:"nxeon-platform-v1", iat, exp <= iat+120, jti once}), then the user's ACTIVE per-server grant with the operation's scope. Writes need ${H.idem}. File changes name what they replace (ifMatch). Restarts: ${RESTART_BUDGET.perHour}/hour, ${RESTART_BUDGET.perDay}/day per grant. After a revoke an in-flight operation (${H.opId}, ${H.opMode}: rollback) may only undo its own changes for ${LIMITS.rollbackGraceMs / 60000} minutes. Limits per grant: ${LIMITS.callsPerMinute} calls/min, ${LIMITS.writesPerMinute} changes/min, files <= ${LIMITS.maxFileBytes} bytes.`,
    },
    servers: [{ url: "https://nxeon.cloud" }],
    paths,
    components: {
      securitySchemes: { ServiceSignature: { type: "apiKey", in: "header", name: "cyrus-signature", description: "HMAC request signature (see info.description)" } },
      parameters: {
        UserAssertion: { name: H.assertion, in: "header", required: true, schema: str() },
        OpId: { name: H.opId, in: "header", required: false, schema: str(undefined, { pattern: "^[A-Za-z0-9_-]{8,64}$" }), description: "groups the calls of one delivery (the rollback-after-revoke rule)" },
        OpMode: { name: H.opMode, in: "header", required: false, schema: str(undefined, { enum: ["rollback"] }) },
        IdempotencyKey: { name: H.idem, in: "header", required: true, schema: str(undefined, { pattern: "^[A-Za-z0-9_-]{8,128}$" }) },
      },
      schemas: {
        Scope: { type: "string", enum: [...SCOPES], description: SCOPES.map((s) => `${s}: ${SCOPE_INFO[s].title}`).join("; ") },
        Server: SERVER,
        Entitlement: ENTITLEMENT_SCHEMA,
        Error: obj({ ok: { type: "boolean", const: false }, error: { type: "object", required: ["code", "message"], properties: { code: str(undefined, { enum: ERROR_CODES }), message: str() }, additionalProperties: true } }),
      },
    },
  };
}
export const PLATFORM_OPENAPI_HEADER = "GENERATED by tools/nxeon-platform/gen-openapi.ts from lib/nxeon-platform (PLATFORM_OPERATIONS). Do not edit.\nNxeon Platform API v1 for Cyrus (OpenAPI 3.1). Served behind CYRUS_PLATFORM_API=1.";

