// ------------------------------------------------------------------------------------------------ harness
const SECRETS: Record<string, string> = { cyrus01: "s3cret-one-0123456789abcdef", cyrus02: "s3cret-two-0123456789abcdef" };

function serve(hs: HostServer): Promise<{ server: Server; url: string }> {
  return new Promise((res) => {
    const server = createServer(async (req, out) => {
      const chunks: Buffer[] = [];
      for await (const c of req) chunks.push(c as Buffer);
      const r = await hs.handle(new Request(`http://127.0.0.1${req.url}`, { method: req.method, headers: req.headers as Record<string, string>, body: req.method === "POST" ? Buffer.concat(chunks) : undefined }));
      out.writeHead(r.status, Object.fromEntries(r.headers));
      out.end(Buffer.from(await r.arrayBuffer()));
    });
    server.listen(0, "127.0.0.1", () => res({ server, url: `http://127.0.0.1:${(server.address() as AddressInfo).port}${HOST_API_PREFIX}` }));
  });
}

