// Test helper: a FAKE NXEON serving the REAL Platform API (lib/nxeon-platform/api.ts) over a real local HTTP server,
// backed by a FakeServer guest dir (test/_cyrus-delivery-fakehost.ts: LocalGuestFs + a fake boot), memory grants,
// and a Cyrus-side PlatformClient pointed at it. Restarts rewrite logs/latest.log from the fake boot, so the
// Platform-API session reads real-looking boot logs through logs.read.tail.
import { generateKeyPairSync, randomBytes, type KeyObject } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { createServer, type Server } from "node:http";
import type { AddressInfo } from "node:net";
import path from "node:path";
import { createPlatformApi, PLATFORM_API_PREFIX, type InventoryRecord, type PlatformApi, type PlatformDeps } from "../lib/nxeon-platform/api";
import { applyConsent, createMemoryGrantStore } from "../lib/nxeon-platform/grants";
import type { PlatformServer } from "../lib/nxeon-platform/servers";
import { createPlatformClient, type PlatformClient } from "../lib/cyrus/host/platform";
import { FakeServer } from "./_cyrus-delivery-fakehost";

export const USER = "user_alice_01";
export const OTHER = "user_bob_0002";
export const SERVER = "srv_alpha_01";

export function bootLog(s: FakeServer): string {
  const b = s.booted;
  const lines = ["[12:00:00 INFO]: Starting minecraft server version 1.21.11", "[12:00:00 INFO]: This server is running Paper version 1.21.11-132 (MC: 1.21.11)"];
  for (const p of b.pluginsEnabled) lines.push(`[12:00:00 INFO]: [${p}] Enabling ${p} v1.0.0`);
  lines.push(...b.errorLines);
  if (b.cameUp) lines.push(`[12:00:01 INFO]: Done (1.0s)! For help, type "help"`);
  return lines.join("\n") + "\n";
}

export type FakePlatform = {
  srv: FakeServer; api: PlatformApi; store: ReturnType<typeof createMemoryGrantStore>; http: Server; baseUrl: string;
  client: PlatformClient; keys: { keyId: string; secret: string; priv: KeyObject; pub: KeyObject };
  owner: Map<string, string>; records: InventoryRecord[]; consoleLog: string[]; clock: { offsetMs: number };
  grant(scopes: string[], userId?: string, serverId?: string): Promise<string>;
  close(): void;
};

export async function fakePlatform(o: { srv?: FakeServer; restartFails?: number; deps?: Partial<PlatformDeps> } = {}): Promise<FakePlatform> {
  const srv = o.srv ?? new FakeServer();
  const store = createMemoryGrantStore();
  const { privateKey: priv, publicKey: pub } = generateKeyPairSync("ed25519");
  const keyId = "cyrus01", secret = randomBytes(32).toString("base64url");
  const owner = new Map<string, string>([[SERVER, USER]]);
  const records: InventoryRecord[] = [];
  const consoleLog: string[] = [];
  const clock = { offsetMs: 0 };
  let restartFails = o.restartFails ?? 0;
  const writeLog = () => { const p = path.join(srv.dir, "opt/mc/logs/latest.log"); mkdirSync(path.dirname(p), { recursive: true }); writeFileSync(p, bootLog(srv)); };
  const describe = (id: string): PlatformServer => ({ id, name: "Alpha SMP", game: "minecraft", loader: "paper", version: "1.21.11", status: "RUNNING", ramMB: 4096, cpuCores: 2, slots: 20, supported: true, reason: null });
  const deps: PlatformDeps = {
    store,
    keys: { secretFor: (id) => (id === keyId ? secret : null), clientOf: (id) => (id === keyId ? "cyrus" : null) },
    assertionKeys: () => [pub],
    servers: {
      get: async (userId, id) => (owner.get(id) === userId ? describe(id) : null),
      many: async (userId, ids) => ids.filter((id) => owner.get(id) === userId).map(describe),
      live: async () => ({ online: srv.booted.cameUp, answered: srv.booted.answered, players: 0, maxPlayers: 20, datapacksLoaded: srv.booted.datapacksLoaded }),
    },
    open: async (id) => (owner.has(id) ? { fs: srv.raw, layout: { base: "/opt/mc", levelName: "world", clientStateDir: "/root/.nxeon-cyrus" } } : null),
    records: async () => records,
    power: {
      async restart() {
        srv.restarts++;
        if (restartFails > 0) { restartFails--; return { ok: false, error: "systemctl restart timed out" }; }
        srv.booted = srv.boot(); writeLog();
        return { ok: true, cameUp: srv.booted.cameUp };
      },
      async console(_id, command) {
        consoleLog.push(command);
        if (command === "minecraft:reload") { const b = srv.boot(); srv.booted = { ...srv.booted, datapacksLoaded: b.cameUp ? b.datapacksLoaded : srv.booted.datapacksLoaded }; }
        return { ok: true, reply: "ok" };
      },
    },
    rateLimit: (() => { const w = new Map<string, { s: number; n: number }>(); return (k: string, { max, windowMs }: { max: number; windowMs: number }) => { const t = Date.now(); let x = w.get(k); if (!x || t - x.s >= windowMs) { x = { s: t, n: 0 }; w.set(k, x); } x.n++; return { ok: x.n <= max, retryAfterSec: 1 }; }; })(),
    now: () => Date.now() + clock.offsetMs,
    ...o.deps,
  };
  const api = createPlatformApi(deps);
  const http = createServer(async (req, out) => {
    const chunks: Buffer[] = [];
    for await (const c of req) chunks.push(c as Buffer);
    const r = await api.handle(new Request(`http://127.0.0.1${req.url}`, { method: req.method, headers: req.headers as Record<string, string>, body: req.method === "POST" ? Buffer.concat(chunks) : undefined }));
    out.writeHead(r.status, Object.fromEntries(r.headers));
    out.end(Buffer.from(await r.arrayBuffer()));
  });
  await new Promise<void>((r) => http.listen(0, "127.0.0.1", () => r()));
  const baseUrl = `http://127.0.0.1:${(http.address() as AddressInfo).port}${PLATFORM_API_PREFIX}`;
  const client = createPlatformClient({ baseUrl, keyId, secret, signingKey: priv, sleep: async () => {}, now: () => Date.now() + clock.offsetMs });
  writeLog();
  return {
    srv, api, store, http, baseUrl, client, keys: { keyId, secret, priv, pub }, owner, records, consoleLog, clock,
    async grant(scopes, userId = USER, serverId = SERVER) {
      const r = await applyConsent(store, { client: "cyrus", userId, serverIds: [serverId], scopes, eligible: new Set([serverId]) });
      if (!r.ok) throw new Error(r.error);
      return r.grants[0].id;
    },
    close() { api.close(); http.close(); srv.cleanup(); },
  };
}

