import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { createHash, generateKeyPairSync } from "node:crypto";
import { signRequest } from "../lib/cyrus/api/v1/signing";
import { mintPlatformAssertion, PlatformError, createPlatformClient } from "../lib/cyrus/host/platform";
import { PlatformTxnFs } from "../lib/cyrus/host/platform-session";
import { setPackProperties } from "../lib/nxeon-platform/api";
import { revokeGrant } from "../lib/nxeon-platform/grants";
import { fakePlatform, OTHER, SERVER, USER, type FakePlatform } from "./_cyrus-platform-fake";
import { seedServer } from "./_cyrus-delivery-fakehost";

const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const code = async (p: Promise<unknown>) => { try { await p; return "ok"; } catch (e) { return e instanceof PlatformError ? e.code : `throw:${(e as Error).message}`; } };
const ALL = ["files.write.mods", "server.reload", "server.restart", "logs.read.tail", "pack.set"];

describe("Platform API: auth", () => {
  let fx: FakePlatform;
  before(async () => { fx = await fakePlatform(); seedServer(fx.srv); await fx.grant(ALL); });
  after(() => fx.close());
  const raw = async (pathQ: string, headers: Record<string, string>) => fetch(fx.baseUrl.replace("/api/platform/cyrus/v1", "") + pathQ, { headers });
  const P = "/api/platform/cyrus/v1/servers";
  it("health needs only the service signature", async () => { assert.deepEqual(await fx.client.health(), { version: "1" }); });
  it("unsigned and unknown-key requests are refused", async () => {
    assert.equal((await raw(P, {})).status, 401);
    const h = signRequest({ keyId: "nobody1", secret: "x".repeat(40), method: "GET", pathWithQuery: P, body: "", nowMs: Date.now() });
    assert.equal((await raw(P, h)).status, 401);
  });
  it("a user call without, with a foreign-signed, a replayed, or an email assertion is refused", async () => {
    const sign = () => signRequest({ keyId: fx.keys.keyId, secret: fx.keys.secret, method: "GET", pathWithQuery: P, body: "", nowMs: Date.now() });
    assert.equal((await (await raw(P, sign())).json()).error.code, "bad_assertion");
    const foreign = generateKeyPairSync("ed25519").privateKey;
    assert.equal((await raw(P, { ...sign(), "nxeon-user-assertion": mintPlatformAssertion({ sub: USER, key: foreign, nowMs: Date.now() }) })).status, 401);
    const a = mintPlatformAssertion({ sub: USER, key: fx.keys.priv, nowMs: Date.now() });
    assert.equal((await raw(P, { ...sign(), "nxeon-user-assertion": a })).status, 200);
    assert.equal((await raw(P, { ...sign(), "nxeon-user-assertion": a })).status, 401, "jti is single-use");
    const old = mintPlatformAssertion({ sub: USER, key: fx.keys.priv, nowMs: Date.now() - 10 * 60_000 });
    assert.equal((await raw(P, { ...sign(), "nxeon-user-assertion": old })).status, 401, "expired");
    const b64u = (s: string) => Buffer.from(s).toString("base64url");
    const { sign: edSign } = await import("node:crypto");
    const p = b64u(JSON.stringify({ v: 1, iss: "cyrus", sub: USER, aud: "nxeon-platform-v1", iat: Math.floor(Date.now() / 1000), exp: Math.floor(Date.now() / 1000) + 60, jti: "abcdefgh123", email: "a@b.c" }));
    assert.equal((await raw(P, { ...sign(), "nxeon-user-assertion": `${p}.${b64u(edSign(null, Buffer.from(p), fx.keys.priv).toString("latin1"))}` })).status, 401);
  });
  it("a tampered signature (path changed) is refused", async () => {
    const h = signRequest({ keyId: fx.keys.keyId, secret: fx.keys.secret, method: "GET", pathWithQuery: "/api/platform/cyrus/v1/grants", body: "", nowMs: Date.now() });
    assert.equal((await raw(P, { ...h, "nxeon-user-assertion": mintPlatformAssertion({ sub: USER, key: fx.keys.priv, nowMs: Date.now() }) })).status, 401);
  });
});

describe("Platform API: grants, scopes, paths, preconditions", () => {
  let fx: FakePlatform;
  before(async () => { fx = await fakePlatform(); seedServer(fx.srv); });
  after(() => fx.close());
  it("no grant -> no_grant; another user's server is invisible", async () => {
    const me = fx.client.as(USER);
    assert.equal(await code(me.server(SERVER)), "no_grant");
    assert.deepEqual(await me.servers(), []);
    await fx.grant([]);
    assert.equal((await me.servers()).length, 1);
    assert.equal(await code(fx.client.as(OTHER).server(SERVER)), "no_grant");
  });
  it("read-only grant: inventory and reads work, writes/restarts are scope_missing", async () => {
    const me = fx.client.as(USER);
    const inv = await me.inventory(SERVER);
    assert.equal(inv.layout.base, "/opt/mc");
    assert.ok(inv.files.some((f) => f.path === "/opt/mc/plugins/Unrelated.jar" && f.sha256 && f.sha256.length === 64));
    assert.equal(await code(me.write(SERVER, { path: "/opt/mc/plugins/X.jar", data: Buffer.from("x"), ifMatch: "absent" })), "scope_missing");
    assert.equal(await code(me.restart(SERVER)), "scope_missing");
    assert.equal(await code(me.logTail(SERVER)), "scope_missing");
  });
  it("path allow-list on reads and writes", async () => {
    await fx.grant(ALL);
    const me = fx.client.as(USER);
    assert.equal(await code(me.read(SERVER, "/opt/mc/logs/latest.log")), "path_refused");
    assert.equal(await code(me.write(SERVER, { path: "/opt/mc/server.jar", data: Buffer.from("x"), ifMatch: "absent" })), "path_refused");
    assert.equal(await code(me.write(SERVER, { path: "/opt/mc/plugins/../server.properties", data: Buffer.from("x"), ifMatch: "absent" })), "path_refused");
    assert.equal(await code(me.write(SERVER, { path: "/opt/mc/plugins/run.sh", data: Buffer.from("x"), ifMatch: "absent" })), "path_refused");
    assert.ok((await me.read(SERVER, "/opt/mc/server.properties"))?.data.toString().includes("level-name"));
  });
  it("hash preconditions: create-only, replace-by-sha, stale view refused with the current sha", async () => {
    const me = fx.client.as(USER);
    const p = "/opt/mc/plugins/Hello.jar";
    await me.write(SERVER, { path: p, data: Buffer.from("v1"), ifMatch: "absent" });
    assert.equal(await code(me.write(SERVER, { path: p, data: Buffer.from("v2"), ifMatch: "absent" })), "precondition_failed");
    try { await me.write(SERVER, { path: p, data: Buffer.from("v2"), ifMatch: sha("nope") }); assert.fail(); } catch (e) { assert.equal((e as PlatformError).detail.current, sha("v1")); }
    await me.write(SERVER, { path: p, data: Buffer.from("v2"), ifMatch: sha("v1") });
    assert.equal(fx.srv.read("opt/mc/plugins/Hello.jar")?.toString(), "v2");
    assert.equal(await code(me.write(SERVER, { path: p, data: Buffer.from("v3"), ifMatch: "whatever" })), "precondition_required");
    assert.equal(await code(me.remove(SERVER, { path: p, ifMatch: sha("v1") })), "precondition_failed");
    await me.remove(SERVER, { path: p, ifMatch: sha("v2") });
    assert.equal(fx.srv.read("opt/mc/plugins/Hello.jar"), null);
  });
  it("idempotency: same key replays, a different request with the key is 422, writes need a key", async () => {
    const me = fx.client.as(USER);
    const r1 = await me.write(SERVER, { path: "/opt/mc/plugins/Idem.jar", data: Buffer.from("a"), ifMatch: "absent" }, { idemKey: "key-000001" });
    const r2 = await me.write(SERVER, { path: "/opt/mc/plugins/Idem.jar", data: Buffer.from("a"), ifMatch: "absent" }, { idemKey: "key-000001" });
    assert.deepEqual(r1, r2, "the stored answer, not a 412");
    assert.equal(await code(me.write(SERVER, { path: "/opt/mc/plugins/Idem.jar", data: Buffer.from("b"), ifMatch: "absent" }, { idemKey: "key-000001" })), "idempotency_mismatch");
    const P = "/api/platform/cyrus/v1/servers/" + SERVER + "/files/mkdir";
    const body = JSON.stringify({ path: "/opt/mc/plugins/NoKey" });
    const h = signRequest({ keyId: fx.keys.keyId, secret: fx.keys.secret, method: "POST", pathWithQuery: P, body, nowMs: Date.now() });
    const res = await fetch(fx.baseUrl.replace("/api/platform/cyrus/v1", "") + P, { method: "POST", body, headers: { ...h, "content-type": "application/json", "nxeon-user-assertion": mintPlatformAssertion({ sub: USER, key: fx.keys.priv, nowMs: Date.now() }) } });
    assert.equal((await res.json()).error.code, "idempotency_key_required");
  });
  it("restart budget: 4 an hour, then budget_exhausted", async () => {
    const me = fx.client.as(USER);
    for (let i = 0; i < 4; i++) assert.equal((await me.restart(SERVER)).restarted, true);
    assert.equal(await code(me.restart(SERVER)), "budget_exhausted");
  });
  it("reload: data packs or a plugin's own reload; never the server-wide /reload", async () => {
    const me = fx.client.as(USER);
    assert.equal((await me.reload(SERVER, { kind: "datapacks" })).command, "minecraft:reload");
    assert.equal((await me.reload(SERVER, { kind: "plugin", plugin: "bettermodel" })).command, "bettermodel reload");
    assert.equal(await code(me.reload(SERVER, { kind: "plugin", plugin: "minecraft" })), "bad_request");
    assert.equal(await code(me.reload(SERVER, { kind: "plugin", plugin: "op; stop" })), "bad_request");
    assert.deepEqual(fx.consoleLog, ["minecraft:reload", "bettermodel reload"]);
  });
  it("logs tail and pack.set (only the pack keys change)", async () => {
    const me = fx.client.as(USER);
    assert.ok((await me.logTail(SERVER, 50)).lines.some((l) => /Done \(/.test(l)));
    const r = await me.setPack(SERVER, { url: "https://packs.example.invalid/p/abc.zip", sha1: "a".repeat(40), required: true });
    assert.equal(r.changed, true);
    const props = fx.srv.read("opt/mc/server.properties")!.toString();
    assert.match(props, /^motd=test$/m);
    assert.match(props, /^resource-pack=https:\/\/packs\.example\.invalid\/p\/abc\.zip$/m);
    assert.match(props, /^require-resource-pack=true$/m);
    assert.equal(await code(me.setPack(SERVER, { url: "https://x.invalid/a\nop=me", sha1: "a".repeat(40), required: false })), "bad_request");
    assert.equal(await code(me.setPack(SERVER, { url: "http://x.invalid/a.zip", sha1: "a".repeat(40), required: false })), "bad_request");
  });
  it("a server that is no longer the user's is gone even with a grant", async () => {
    fx.owner.set(SERVER, OTHER);
    assert.equal(await code(fx.client.as(USER).server(SERVER)), "server_gone");
    fx.owner.set(SERVER, USER);
  });
  it("every user call is audited with its op id and path", async () => {
    const me = fx.client.as(USER);
    await me.mkdir(SERVER, "/opt/mc/plugins/Audited", { opId: "op_audit_0001" });
    const rows = fx.store.calls.filter((c) => c.opId === "op_audit_0001");
    assert.equal(rows.length, 1);
    assert.equal(rows[0].path, "/opt/mc/plugins/Audited");
    assert.ok(rows[0].mutation && rows[0].grantId && rows[0].userId === USER && rows[0].serverId === SERVER);
    assert.ok(fx.store.calls.some((c) => c.code === "path_refused"), "refusals are audited too");
  });
});

describe("Platform API: revoke mid-operation", () => {
  let fx: FakePlatform;
  before(async () => { fx = await fakePlatform(); seedServer(fx.srv); });
  after(() => fx.close());
  it("forward calls stop; the same operation may undo only its own changes, within the grace window", async () => {
    const gid = await fx.grant(ALL);
    const me = fx.client.as(USER);
    const op = { opId: "op_revoke_0001" };
    await me.write(SERVER, { path: "/opt/mc/plugins/New.jar", data: Buffer.from("new"), ifMatch: "absent" }, op);
    await me.restart(SERVER, op);
    await revokeGrant(fx.store, { userId: USER, grantId: gid });
    assert.equal(await code(me.write(SERVER, { path: "/opt/mc/plugins/Other.jar", data: Buffer.from("x"), ifMatch: "absent" }, op)), "grant_revoked");
    const rb = { ...op, rollback: true };
    assert.equal(await code(me.write(SERVER, { path: "/opt/mc/plugins/Other.jar", data: Buffer.from("x"), ifMatch: "absent" }, rb)), "rollback_only");
    assert.equal(await code(me.remove(SERVER, { path: "/opt/mc/plugins/Unrelated.jar", ifMatch: sha(fx.srv.read("opt/mc/plugins/Unrelated.jar")!) }, rb)), "rollback_only");
    assert.equal(await code(me.remove(SERVER, { path: "/opt/mc/plugins/New.jar", ifMatch: sha("new") }, rb)), "ok");
    assert.equal(await code(me.restart(SERVER, rb)), "ok", "it restarted before, so its rollback may");
    assert.equal(await code(me.reload(SERVER, { kind: "datapacks" }, rb)), "rollback_only", "it never reloaded");
    assert.equal(await code(me.stat(SERVER, "/opt/mc/plugins/New.jar", { opId: "op_fresh_00001", rollback: true })), "grant_revoked", "a new op gets nothing");
    fx.clock.offsetMs = 16 * 60_000;
    assert.equal(await code(me.stat(SERVER, "/opt/mc/plugins/New.jar", rb)), "grant_revoked", "grace over");
    fx.clock.offsetMs = 0;
    assert.equal(fx.srv.read("opt/mc/plugins/New.jar"), null);
  });
});

describe("Cyrus side: PlatformTxnFs (automatic preconditions)", () => {
  let fx: FakePlatform;
  before(async () => { fx = await fakePlatform(); seedServer(fx.srv); await fx.grant(ALL); });
  after(() => fx.close());
  it("write/rename/copy/remove name what they replace; a concurrent change is refused", async () => {
    const fs = new PlatformTxnFs(fx.client.as(USER), SERVER);
    await fs.writeFile("/opt/mc/plugins/A.jar.nxeon-part", Buffer.from("A1"));
    await fs.rename("/opt/mc/plugins/A.jar.nxeon-part", "/opt/mc/plugins/A.jar");
    await fs.copy("/opt/mc/plugins/A.jar", "/root/.nxeon-cyrus/backup/A.jar");
    assert.equal(fx.srv.read("root/.nxeon-cyrus/backup/A.jar")?.toString(), "A1");
    await fs.writeFile("/opt/mc/plugins/A.jar", Buffer.from("A2"));
    // the user edits the file behind Cyrus' back
    require("node:fs").writeFileSync(require("node:path").join(fx.srv.dir, "opt/mc/plugins/A.jar"), "USER");
    await assert.rejects(fs.writeFile("/opt/mc/plugins/A.jar", Buffer.from("A3")), (e: PlatformError) => e.code === "precondition_failed");
    assert.equal(fx.srv.read("opt/mc/plugins/A.jar")?.toString(), "USER");
    assert.equal(await fs.readFile("/opt/mc/plugins/A.jar").then((b) => b?.toString()), "USER");
    await fs.remove("/opt/mc/plugins/A.jar");
    assert.equal(await fs.stat("/opt/mc/plugins/A.jar"), null);
  });
  it("grant_revoked flips the fs into rollback mode", async () => {
    const api = fx.client.as(USER);
    let flagged = 0;
    const fs = new PlatformTxnFs(api, SERVER, { onRevoked: () => flagged++ });
    await fs.writeFile("/opt/mc/plugins/B.jar", Buffer.from("B"));
    const g = (await fx.store.active("cyrus", USER, SERVER))!;
    await revokeGrant(fx.store, { userId: USER, grantId: g.id });
    await assert.rejects(fs.writeFile("/opt/mc/plugins/C.jar", Buffer.from("C")));
    assert.equal(fs.rollback, true); assert.equal(flagged, 1);
    await fs.remove("/opt/mc/plugins/B.jar");
    assert.equal(fx.srv.read("opt/mc/plugins/B.jar"), null);
  });
});

describe("pure helpers", () => {
  it("setPackProperties keeps every other line and adds missing keys before the trailing newline", () => {
    assert.equal(setPackProperties("motd=hi\nresource-pack=old\n", { url: "https://a.b/c.zip", sha1: "b".repeat(40), required: false, prompt: null }),
      `motd=hi\nresource-pack=https://a.b/c.zip\nresource-pack-sha1=${"b".repeat(40)}\nrequire-resource-pack=false\n`);
  });
  it("a client refuses a non-http base URL", () => {
    assert.throws(() => createPlatformClient({ baseUrl: "ftp://x", keyId: "a", secret: "b", signingKey: generateKeyPairSync("ed25519").privateKey }));
  });
});

