// r38 (2): the Platform API contract is generated and pinned; Nxeon's table, Cyrus' client table and the OpenAPI file agree.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { generateKeyPairSync } from "node:crypto";
import { fromYaml } from "../lib/cyrus/api/v1/yaml";
import { ReplayCache } from "../lib/cyrus/api/v1/signing";
import { PLATFORM_OPERATIONS, PLATFORM_API_PREFIX, verifyUserAssertion } from "../lib/nxeon-platform/api";
import { SCOPES } from "../lib/nxeon-platform/scopes";
import { PLATFORM_CLIENT_OPERATIONS, PLATFORM_SCOPES, PLATFORM_API_PREFIX as CLIENT_PREFIX, mintPlatformAssertion } from "../lib/cyrus/host/platform";
import { platformOpenApiYaml } from "../tools/nxeon-platform/gen-openapi";

const FILE = path.resolve(__dirname, "..", "docs", "api", "nxeon-platform-v1.openapi.yaml");

describe("Platform API contract", () => {
  it("the OpenAPI file is exactly the generated one (regenerate: npx tsx tools/nxeon-platform/gen-openapi.ts)", () => {
    assert.equal(readFileSync(FILE, "utf8"), platformOpenApiYaml());
  });
  it("Nxeon's operation table and Cyrus' client table are the same, both ways", () => {
    assert.equal(CLIENT_PREFIX, PLATFORM_API_PREFIX);
    assert.deepEqual(Object.keys(PLATFORM_CLIENT_OPERATIONS).sort(), Object.keys(PLATFORM_OPERATIONS).sort());
    for (const [k, d] of Object.entries(PLATFORM_OPERATIONS)) assert.deepEqual([...PLATFORM_CLIENT_OPERATIONS[k as keyof typeof PLATFORM_CLIENT_OPERATIONS]], [d.method, d.path], k);
    assert.deepEqual([...PLATFORM_SCOPES], [...SCOPES]);
  });
  it("the file parses and documents every operation with its scope, and every write with an Idempotency-Key", () => {
    const doc = fromYaml(readFileSync(FILE, "utf8")) as { paths: Record<string, Record<string, { operationId: string; "x-nxeon-scope": string; parameters: { $ref?: string }[] }>> };
    const ops = new Map<string, { method: string; p: string; scope: string; params: string[] }>();
    for (const [p, m] of Object.entries(doc.paths)) for (const [method, op] of Object.entries(m)) ops.set(op.operationId, { method: method.toUpperCase(), p, scope: op["x-nxeon-scope"], params: op.parameters.map((x) => x.$ref ?? "") });
    assert.equal(ops.size, Object.keys(PLATFORM_OPERATIONS).length);
    for (const [k, d] of Object.entries(PLATFORM_OPERATIONS)) {
      const o = ops.get(k);
      assert.ok(o, k);
      assert.equal(o!.p, PLATFORM_API_PREFIX + d.path);
      assert.equal(o!.scope, d.scope ?? "none");
      if (d.method === "POST") assert.ok(o!.params.includes("#/components/parameters/IdempotencyKey"), k);
      if (d.user) assert.ok(o!.params.includes("#/components/parameters/UserAssertion"), k);
    }
  });
  it("every mutation needs a scope other than the read ones; reads never mutate", () => {
    for (const [k, d] of Object.entries(PLATFORM_OPERATIONS)) {
      if (d.mutation) assert.ok(d.method === "POST" && d.scope && !["servers.read", "inventory.read", "logs.read.tail"].includes(d.scope), k);
      else assert.equal(d.method, "GET", k);
    }
  });
  it("Cyrus' assertion verifies on the Nxeon side, once, and only for Cyrus' key", () => {
    const { privateKey, publicKey } = generateKeyPairSync("ed25519");
    const replay = new ReplayCache();
    const a = mintPlatformAssertion({ sub: "user_1234", key: privateKey, nowMs: Date.now() });
    assert.deepEqual(verifyUserAssertion(a, { client: "cyrus", keys: [publicKey], nowMs: Date.now(), replay }), { ok: true, sub: "user_1234" });
    assert.equal(verifyUserAssertion(a, { client: "cyrus", keys: [publicKey], nowMs: Date.now(), replay }).ok, false);
    const b = mintPlatformAssertion({ sub: "user_1234", key: privateKey, nowMs: Date.now() });
    assert.equal(verifyUserAssertion(b, { client: "cyrus", keys: [generateKeyPairSync("ed25519").publicKey], nowMs: Date.now(), replay }).ok, false);
    assert.equal(verifyUserAssertion(mintPlatformAssertion({ sub: "user_1234", client: "kodely", key: privateKey, nowMs: Date.now() }), { client: "cyrus", keys: [publicKey], nowMs: Date.now(), replay }).ok, false);
  });
});
EOF
