/** Status of a wallet top-up by its key: honest, from the ledger and the wallet itself. */
export async function walletTopupStatus(userId: string, key: string): Promise<WalletPayState> {
  const ref = walletRef(userId, key);
  if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return "credited";
  const w = getHost().billing.wallet;
  const moves = (await w?.findByReference?.({ userId, prefix: ref, sinceMs: Date.now() - 30 * DAY })) ?? [];
  const charged = moves.some((m) => m.reference === ref && m.cents < 0);
  const refunded = moves.some((m) => m.reference === `${ref}:refund` && m.cents > 0);
  return refunded ? "failed" : charged ? "pending" : "invalid";
}

export async function payTopupWithWallet(user: { id: string }, cents: number, key: string): Promise<{ state: WalletPayState; tokens: number; error?: string }> {
  const wallet = getHost().billing.wallet;
  if (!walletPayEnabled() || !wallet) return { state: "unavailable", tokens: 0, error: "Paying with your wallet isn't available right now." };
  if (!/^[A-Za-z0-9_-]{16,64}$/.test(key)) return { state: "invalid", tokens: 0, error: "Missing purchase key." };
  const cfg = await loadTokenConfig();
  if (!cfg.topup.enabled) return { state: "unavailable", tokens: 0, error: "Top-ups aren't available right now." };
  if (!validTopupCents(cents, cfg)) return { state: "invalid", tokens: 0, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
  if (cfg.topup.requiresPaid) {
    const paid = (await getHost().servers.paidCount(user.id)) + (await db.cyrusPlan.count({ where: { userId: user.id } }));
    if (!paid) return { state: "invalid", tokens: 0, error: "Top-ups are for customers with a game server or a Cyrus plan." };
  }
  const ref = walletRef(user.id, key);
  if (locks.has(ref)) return { state: "in_progress", tokens: 0 };
  locks.add(ref);
  try {
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return { state: "credited", tokens: 0 };
    const tokens = topupTokens(cents, cfg);
    const charge = await wallet.charge({ userId: user.id, cents, description: `Cyrus tokens: ${fmt(tokens)}`, reference: ref });
    if (!charge.ok) return { state: charge.error === "insufficient_funds" ? "insufficient_funds" : "invalid", tokens: 0, error: charge.error === "insufficient_funds" ? "Not enough in your wallet. Add funds or pay by card." : "Couldn't charge your wallet." };
    const e = purchaseEnvelope("purchase.completed", user.id, {
      idemKey: ref, kind: "topup", method: "wallet", tokens, cents,
      expiresAt: new Date(Date.now() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet)`,
    });
    try {
      const r = await deliverPurchase(e);
      return { state: r.state, tokens: r.tokens };
    } catch (err) {
      console.error("[cyrus-purchase] credit failed after wallet charge", ref, (err as Error).message);
      // Compensate: the money goes back, the purchase is honestly failed. If the refund fails too, the charge stays
      // "pending" and reconcileWalletTopups credits it later.
      try {
        await wallet.refund({ userId: user.id, cents, description: "Refund: Cyrus tokens not credited", reference: `${ref}:refund` });
        return { state: "failed", tokens: 0, error: "We couldn't add your tokens, so your wallet was refunded." };
      } catch {
        return { state: "pending", tokens: 0, error: "Your tokens are on the way. If they don't appear in a few minutes, contact support." };
      }
    }
  } finally {
    locks.delete(ref);
  }
}

/** Reconciliation: any referenced wallet charge without a ledger row (and without a refund) is credited. */
export async function reconcileWalletTopups(o: { userId?: string; sinceMs?: number } = {}): Promise<{ checked: number; credited: number }> {
  const w = getHost().billing.wallet;
  if (!walletPayEnabled() || !w?.findByReference) return { checked: 0, credited: 0 };
  const cfg = await loadTokenConfig();
  const moves = await w.findByReference({ userId: o.userId, prefix: "cwt:", sinceMs: o.sinceMs ?? Date.now() - 7 * DAY });
  const refunded = new Set(moves.filter((m) => m.cents > 0 && m.reference.endsWith(":refund")).map((m) => m.reference.slice(0, -":refund".length)));
  let credited = 0, checked = 0;
  for (const m of moves) {
    if (m.cents >= 0 || refunded.has(m.reference) || locks.has(m.reference)) continue;
    checked++;
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: m.reference }, select: { id: true } })) continue;
    const cents = -m.cents;
    const r = await applyPurchaseEvent(purchaseEnvelope("purchase.completed", m.userId, {
      idemKey: m.reference, kind: "topup", method: "wallet", tokens: topupTokens(cents, cfg), cents,
      expiresAt: new Date(m.at.getTime() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet, reconciled)`,
    }));
    if (r.applied) credited++;
  }
  return { checked, credited };
}

