  if (cur && !sameSub && ACTIVE.includes(cur.status) && !cur.endedAt && !ACTIVE.includes(sub.status)) return { userId };
  const endedAt = ts(sub.ended_at);
  const data = {
    stripeCustomerId: idOf(sub.customer as string | { id: string })!,
    stripeSubscriptionId: sub.id,
    priceTier,
    status: sub.status,
    currentPeriodStart: start,
    currentPeriodEnd: end,
    cancelAtPeriodEnd: !!sub.cancel_at_period_end,
    endedAt,
    livemode: sub.livemode,
    lastSyncAt: new Date(),
  };
  // `tier` (the paid entitlement) only ever comes from a paid invoice; a brand-new row
  // starts at the price's tier but has no period until the first invoice is paid.
  await db.cyrusPlan.upsert({
    where: { userId },
    create: { userId, tier: priceTier, ...data },
    update: sameSub ? data : { tier: priceTier, ...data },
  });
