// CYRUS SIDE: the plan + token ENTITLEMENT mirrored from Nxeon, the payment provider (Katara / Saka / Yakko plans and
// token packs are Nxeon products). Flag CYRUS_ENTITLEMENT_MIRROR=1 (off = nothing here runs; tierOf reads the plan row
// exactly as before).
//   apply      entitlement.changed (signed webhook, lib/cyrus/bridge/platform-events.ts) or a pulled snapshot: the plan
//              becomes the mirrored CyrusPlan row (stripeSubscriptionId "nxeon:<user>"), older versions are ignored;
//              wallet purchases are credited once by idemKey (the SAME key the direct path uses), refunds/chargebacks
//              take back that lot's unspent tokens (applyPurchaseEvent).
//   read       tierOf -> gateMirroredPlan: a 60 s in-process cache; past it, the mirror must have been CONFIRMED by
//              Nxeon within CYRUS_ENTITLEMENT_MAX_AGE_H (default 36 h), else Cyrus pulls a fresh snapshot through the
//              Platform API; if that fails too the plan counts as unknown = no paid plan (FAIL CLOSED).
//   reconcile  reconcileEntitlements(): re-pull every mirrored user not confirmed in 12 h (worker sweep, daily cadence).
// HOST SEAM: Nxeon is reached only through host.platform.
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import { loadTokenConfig } from "./config";
import { topupTokens } from "./economy";
import { applyPurchaseEvent, purchaseEnvelope } from "./purchase";

type Env = Record<string, string | undefined>;
export const entitlementMirrorEnabled = (env: Env = process.env) => env.CYRUS_ENTITLEMENT_MIRROR === "1";
const maxAgeMs = (env: Env = process.env) => Math.max(1, Math.min(24 * 14, Number(env.CYRUS_ENTITLEMENT_MAX_AGE_H) || 36)) * 3600_000;
export const CACHE_TTL_MS = 60_000;
export const MIRROR_PREFIX = "nxeon:";

/** The wire shape (docs/api/nxeon-platform-v1.openapi.yaml components.schemas.Entitlement). */
export type MirrorEntitlement = {
  subject: string; version: number; issuedAt: string;
  plan: { tier: "katara" | "saka" | "all" | null; status: "active" | "trialing" | "past_due" | "canceled" | "unpaid" | "none"; periodEnd: string | null; cancelAtPeriodEnd: boolean; product: string | null };
  purchases: { idemKey: string; tokens: number | null; cents: number; method: "wallet" | "card"; at: string; refundedCents: number; chargeback: boolean }[];
  partner: { code: string; firstPaymentPct: number; recurringPct: number } | null;
};

const IDEM_RE = /^[A-Za-z0-9:_-]{6,160}$/;
export function parseEntitlement(x: unknown): MirrorEntitlement | null {
  const e = x as MirrorEntitlement;
  if (!e || typeof e !== "object" || typeof e.subject !== "string" || !/^[A-Za-z0-9_:.-]{4,128}$/.test(e.subject) || !Number.isInteger(e.version) || e.version < 0) return null;
  if (!e.plan || !["katara", "saka", "all", null].includes(e.plan.tier) || !["active", "trialing", "past_due", "canceled", "unpaid", "none"].includes(e.plan.status)) return null;
  if (e.plan.periodEnd !== null && Number.isNaN(Date.parse(e.plan.periodEnd))) return null;
  if (!Array.isArray(e.purchases) || e.purchases.length > 1000) return null;
  for (const p of e.purchases) {
    if (!p || !IDEM_RE.test(p.idemKey) || !Number.isInteger(p.cents) || p.cents <= 0 || p.cents > 10_000_000 || !Number.isInteger(p.refundedCents) || p.refundedCents < 0) return null;
    if (p.tokens !== null && (!Number.isInteger(p.tokens) || p.tokens < 0 || p.tokens > 100_000_000)) return null;
    // a purchase must belong to the subject (wallet references embed the user id)
    if (p.idemKey.startsWith("cwt:") && !p.idemKey.startsWith(`cwt:${e.subject}:`)) return null;
  }
  return e;
}

const cache = new Map<string, number>();
export function clearEntitlementCacheForTests() { cache.clear(); }

export type ApplyEntitlementResult = { plan: "applied" | "stale" | "confirmed"; credited: number; reversed: number };

/** Idempotent. Older versions never overwrite newer ones (they still CONFIRM the mirror is current). */
export async function applyEntitlement(raw: unknown, now = new Date()): Promise<ApplyEntitlementResult> {
  const e = parseEntitlement(raw);
  if (!e) throw new Error("invalid entitlement");
  const out: ApplyEntitlementResult = { plan: "confirmed", credited: 0, reversed: 0 };
  const cur = await db.cyrusPlan.findUnique({ where: { userId: e.subject } });
  const mirrored = !cur || cur.stripeSubscriptionId.startsWith(MIRROR_PREFIX);
  const curVersion = cur?.lastSyncAt?.getTime() ?? -1;
  if (mirrored && e.version > curVersion) {
    const data = {
      stripeCustomerId: "nxeon", stripeSubscriptionId: `${MIRROR_PREFIX}${e.subject}`,
      tier: e.plan.tier ?? "katara", priceTier: e.plan.tier ?? "katara",
      // a plan-less entitlement is stored as status "none": effectiveTier gives it no paid tier
      status: e.plan.tier ? e.plan.status : "none",
      currentPeriodEnd: e.plan.periodEnd ? new Date(e.plan.periodEnd) : null, cancelAtPeriodEnd: e.plan.cancelAtPeriodEnd,
      endedAt: e.plan.status === "canceled" && e.plan.periodEnd ? new Date(e.plan.periodEnd) : null,
      livemode: true, lastSyncAt: new Date(e.version),
    };
    await db.cyrusPlan.upsert({ where: { userId: e.subject }, create: { userId: e.subject, ...data }, update: data });
    out.plan = "applied";
  } else if (mirrored && cur) {
    // same or older version: touch the row so updatedAt records that Nxeon confirmed it (the freshness rule)
    await db.cyrusPlan.update({ where: { userId: e.subject }, data: { lastSyncAt: cur.lastSyncAt } });
    out.plan = e.version < curVersion ? "stale" : "confirmed";
  } else out.plan = "stale"; // a real (own-Stripe) plan row is never overwritten by the mirror
  const cfg = e.purchases.length ? await loadTokenConfig() : null;
  for (const p of e.purchases) {
    const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: p.idemKey }, select: { id: true } });
    const refunded = p.chargeback ? p.cents : Math.min(p.cents, p.refundedCents);
    const tokens = p.tokens ?? topupTokens(p.cents, cfg!);
    const data = { idemKey: p.idemKey, kind: "topup" as const, method: p.method, tokens, cents: p.cents, expiresAt: new Date(Date.parse(p.at) + cfg!.topup.expiryDays * 86_400_000).toISOString(), note: `Top-up $${(p.cents / 100).toFixed(2)} (${p.method}, from Nxeon)` };
    if (!row) {
      // fully refunded before it was ever credited (e.g. the compensating refund) -> nothing to credit
      if (refunded >= p.cents) continue;
      const r = await applyPurchaseEvent(purchaseEnvelope("purchase.completed", e.subject, data, now));
      if (r.applied) out.credited += r.tokens;
    }
    if (refunded > 0 && (row || !(refunded >= p.cents))) {
      const r = await applyPurchaseEvent(purchaseEnvelope("purchase.refunded", e.subject, { ...data, refundedCents: refunded }, now));
      if (r.applied) out.reversed += r.tokens;
    }
  }
  cache.set(e.subject, now.getTime());
  return out;
}

/** Pull one user's snapshot from Nxeon and apply it. false when there is no Platform API or it failed. */
export async function pullEntitlement(userId: string, now = new Date()): Promise<boolean> {
  const p = getHost().platform;
  if (!p) return false;
  try { await applyEntitlement(await p.as(userId).entitlements(), now); return true; }
  catch (e) { console.error("[cyrus-entitlement] pull failed", userId, (e as Error).message); return false; }
}

/** The fail-closed read rule tierOf applies to the plan row while the mirror is on. */
export async function gateMirroredPlan<P extends { stripeSubscriptionId: string; updatedAt: Date } | null>(userId: string, plan: P, env: Env = process.env, now = new Date()): Promise<P | null> {
  if (!entitlementMirrorEnabled(env)) return plan;
  const t = now.getTime();
  const hit = cache.get(userId);
  if (hit !== undefined && t - hit < CACHE_TTL_MS) return plan && plan.stripeSubscriptionId.startsWith(MIRROR_PREFIX) ? plan : null;
  if (plan && plan.stripeSubscriptionId.startsWith(MIRROR_PREFIX) && t - plan.updatedAt.getTime() < maxAgeMs(env)) { cache.set(userId, t); return plan; }
  // unknown or stale: one pull; failure = no paid plan
  if (await pullEntitlement(userId, now)) {
    const fresh = await db.cyrusPlan.findUnique({ where: { userId } });
    return (fresh && fresh.stripeSubscriptionId.startsWith(MIRROR_PREFIX) ? fresh : null) as P | null;
  }
  return null;
}

/** Reconciliation (worker, flag on): re-pull every mirrored user not confirmed within 12 h. */
export async function reconcileEntitlements(o: { limit?: number; now?: Date } = {}, env: Env = process.env): Promise<{ checked: number; pulled: number; failed: number }> {
  if (!entitlementMirrorEnabled(env) || !getHost().platform) return { checked: 0, pulled: 0, failed: 0 };
  const now = o.now ?? new Date();
  const rows = await db.cyrusPlan.findMany({ where: { stripeSubscriptionId: { startsWith: MIRROR_PREFIX }, updatedAt: { lt: new Date(now.getTime() - 12 * 3600_000) } }, select: { userId: true }, take: o.limit ?? 200, orderBy: { updatedAt: "asc" } });
  let pulled = 0, failed = 0;
  for (const r of rows) if (await pullEntitlement(r.userId, now)) pulled++; else failed++;
  return { checked: rows.length, pulled, failed };
}

