// r38 (3): entitlement sync: Nxeon's snapshot (pure), the signed Nxeon -> Cyrus outbox, the Cyrus receiver rule.
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { composeEntitlement, cyrusPartnerCommission } from "../lib/nxeon-platform/entitlements";
import { createMemoryEventOutbox, dispatchPlatformEvents, entitlementChanged, grantChanged, platformEventTarget, signPlatformEvent } from "../lib/nxeon-platform/events";
import { parseEntitlement } from "../lib/cyrus/tokens/entitlement";
import { createDoneSet, receivePlatformEvent } from "../lib/cyrus/bridge/platform-events";

const U = "user_ent_0001";
const now = new Date("2026-10-11T12:00:00Z");
const plan = { tier: "saka", status: "active", currentPeriodEnd: new Date("2026-11-01T00:00:00Z"), cancelAtPeriodEnd: false, updatedAt: new Date("2026-10-01T00:00:00Z") };
const k = (s: string) => `cwt:${U}:${s.padEnd(20, "x")}`;

describe("Nxeon entitlement snapshot", () => {
  it("plan as a Nxeon product, wallet top-ups as purchases, refunds summed, version = newest change", () => {
    const e = composeEntitlement(U, plan, [
      { reference: k("a"), cents: -1000, at: new Date("2026-10-05T00:00:00Z") },
      { reference: k("b"), cents: -500, at: new Date("2026-10-06T00:00:00Z") },
      { reference: `${k("b")}:refund`, cents: 500, at: new Date("2026-10-06T00:01:00Z") },
      { reference: "cwt:someoneelse:short", cents: -100, at: new Date("2026-10-07T00:00:00Z") },
    ], null, now);
    assert.deepEqual(e.plan, { tier: "saka", status: "active", periodEnd: "2026-11-01T00:00:00.000Z", cancelAtPeriodEnd: false, product: "cyrus.plan.saka" });
    assert.deepEqual(e.purchases.map((p) => [p.cents, p.refundedCents, p.tokens]), [[1000, 0, null], [500, 500, null]]);
    assert.equal(e.version, new Date("2026-10-07T00:00:00Z").getTime());
    assert.ok(parseEntitlement(e), "the Cyrus parser accepts what Nxeon sends");
  });
  it("no plan = status none; Yakko is the 'all' tier", () => {
    assert.deepEqual(composeEntitlement(U, null, [], null, now).plan, { tier: null, status: "none", periodEnd: null, cancelAtPeriodEnd: false, product: null });
    assert.equal(composeEntitlement(U, { ...plan, tier: "all" }, [], null, now).plan.product, "cyrus.plan.yakko");
  });
  it("the Cyrus parser refuses foreign purchases and bad shapes", () => {
    const e = composeEntitlement(U, plan, [{ reference: k("a"), cents: -1000, at: now }], null, now);
    assert.equal(parseEntitlement({ ...e, purchases: [{ ...e.purchases[0], idemKey: "cwt:other_user:abcdefghijklmnopqrst" }] }), null);
    assert.equal(parseEntitlement({ ...e, plan: { ...e.plan, tier: "gold" } }), null);
    assert.equal(parseEntitlement({ ...e, version: -1 }), null);
  });
  it("partner attribution is off by default", async () => {
    delete process.env.CYRUS_PARTNER_ATTRIBUTION;
    assert.equal(await cyrusPartnerCommission({ userId: U, cents: 1000, first: true }, { plan: async () => null, walletMoves: async () => [], partner: async () => ({ code: "KOBBI", firstPaymentPct: 50, recurringPct: 10 }) }), null);
    process.env.CYRUS_PARTNER_ATTRIBUTION = "1";
    assert.deepEqual(await cyrusPartnerCommission({ userId: U, cents: 1000, first: true }, { plan: async () => null, walletMoves: async () => [], partner: async () => ({ code: "KOBBI", firstPaymentPct: 50, recurringPct: 10 }) }), { code: "KOBBI", pct: 50, cents: 500 });
    assert.equal((await cyrusPartnerCommission({ userId: U, cents: 1000, first: false }, { plan: async () => null, walletMoves: async () => [], partner: async () => ({ code: "KOBBI", firstPaymentPct: 50, recurringPct: 10 }) }))?.cents, 100);
    delete process.env.CYRUS_PARTNER_ATTRIBUTION;
  });
});

describe("Nxeon -> Cyrus signed outbox", () => {
  const SECRET = "p".repeat(40);
  it("off unless configured with a dedicated secret", () => {
    assert.equal(platformEventTarget({}), null);
    assert.equal(platformEventTarget({ CYRUS_PLATFORM_EVENTS: "1", CYRUS_PLATFORM_EVENTS_URL: "https://c.invalid/x", CYRUS_PLATFORM_EVENTS_SECRET: "short" }), null);
    assert.equal(platformEventTarget({ CYRUS_PLATFORM_EVENTS: "1", CYRUS_PLATFORM_EVENTS_URL: "https://c.invalid/x", CYRUS_PLATFORM_EVENTS_SECRET: SECRET, AUTH_SECRET: SECRET }), null);
    assert.ok(platformEventTarget({ CYRUS_PLATFORM_EVENTS: "1", CYRUS_PLATFORM_EVENTS_URL: "https://c.invalid/x", CYRUS_PLATFORM_EVENTS_SECRET: SECRET }));
  });
  it("deterministic ids (a double emit is one event), signed delivery, retry ladder then dead", async () => {
    const ob = createMemoryEventOutbox();
    const e = entitlementChanged(composeEntitlement(U, plan, [], null, now));
    await ob.add(e); await ob.add(entitlementChanged(composeEntitlement(U, plan, [], null, now)));
    assert.equal(ob.rows.size, 1);
    const seen: { sig: string | null; body: string }[] = [];
    let ok = false;
    const f = (async (_u: string, init: RequestInit) => { seen.push({ sig: new Headers(init.headers).get("nxeon-signature"), body: String(init.body) }); return new Response("", { status: ok ? 200 : 503 }); }) as unknown as typeof fetch;
    let t = now.getTime();
    const clock = () => new Date(t);
    assert.deepEqual(await dispatchPlatformEvents({ outbox: ob, target: { url: "https://c.invalid/x", secret: SECRET }, fetch: f, now: clock }), { sent: 0, retried: 1, dead: 0 });
    const ts = String(Math.floor(t / 1000));
    assert.equal(seen[0].sig, signPlatformEvent(SECRET, e.id, ts, seen[0].body));
    assert.deepEqual(await dispatchPlatformEvents({ outbox: ob, target: { url: "https://c.invalid/x", secret: SECRET }, fetch: f, now: clock }), { sent: 0, retried: 0, dead: 0 }, "not due yet");
    t += 61_000; ok = true;
    assert.deepEqual(await dispatchPlatformEvents({ outbox: ob, target: { url: "https://c.invalid/x", secret: SECRET }, fetch: f, now: clock }), { sent: 1, retried: 0, dead: 0 });
    const ob2 = createMemoryEventOutbox(); ok = false;
    await ob2.add(grantChanged("grant.revoked", { id: "cg_1", userId: U, serverId: "s1", scopes: [] }, now));
    let dead = 0;
    for (let i = 0; i < 6; i++) { dead += (await dispatchPlatformEvents({ outbox: ob2, target: { url: "https://c.invalid/x", secret: SECRET }, fetch: f, now: () => new Date(t) })).dead; t += 13 * 3600_000; }
    assert.equal(dead, 1);
  });
});

describe("Cyrus receiver", () => {
  const SECRET = "r".repeat(40);
  const mk = (id: string, body: string, tsS = Math.floor(Date.now() / 1000), secret = SECRET) =>
    new Request("http://x/api/cyrus/platform-events", { method: "POST", body, headers: { "nxeon-webhook-id": id, "nxeon-webhook-timestamp": String(tsS), "nxeon-signature": signPlatformEvent(secret, id, String(tsS), body) } });
  it("refuses unsigned, stale and wrongly signed; a failed handler is redelivered and then applied once", async () => {
    const done = createDoneSet();
    let calls = 0, fail = true;
    const handlers = { "grant.revoked": async () => { calls++; if (fail) throw new Error("db down"); return "ok"; } };
    const body = JSON.stringify({ id: "evt_1", type: "grant.revoked", createdAt: now.toISOString(), subject: U, data: {} });
    assert.equal((await receivePlatformEvent(new Request("http://x", { method: "POST", body }), { secret: SECRET, handlers, done })).status, 401);
    assert.equal((await receivePlatformEvent(mk("evt_1", body, Math.floor(Date.now() / 1000) - 3600), { secret: SECRET, handlers, done })).status, 401);
    assert.equal((await receivePlatformEvent(mk("evt_1", body, undefined, "w".repeat(40)), { secret: SECRET, handlers, done })).status, 401);
    assert.equal((await receivePlatformEvent(mk("evt_1", body), { secret: SECRET, handlers, done })).status, 500);
    fail = false;
    assert.equal((await receivePlatformEvent(mk("evt_1", body), { secret: SECRET, handlers, done })).status, 200);
    const dup = await receivePlatformEvent(mk("evt_1", body), { secret: SECRET, handlers, done });
    assert.equal((await dup.json()).duplicate, true);
    assert.equal(calls, 2);
  });
});
EOF
