let L: typeof import("../lib/cyrus/tokens/ledger.ts");
let H: typeof import("../lib/cyrus/host/index.ts");
let N: typeof import("../lib/nxeon-platform/entitlements.ts");
const users: string[] = [];
const rnd = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2)}xxxxxxxxxxxx`.slice(0, 24);
async function mkUser() {
  const u = await db.user.create({ data: { email: `ent-${rnd()}@example.test`, passwordHash: "x", name: "Ent", emailVerifiedAt: new Date() } });
