}
const ent = (sub: string, over: Record<string, unknown> = {}) => ({
  subject: sub, version: Date.parse("2026-10-10T00:00:00Z"), issuedAt: new Date().toISOString(),
  plan: { tier: "saka", status: "active", periodEnd: new Date(Date.now() + 20 * 86_400_000).toISOString(), cancelAtPeriodEnd: false, product: "cyrus.plan.saka" },
