    assert.equal(await A.tierOf(u.id), "saka");
    assert.equal((await E.applyEntitlement(ent(u.id, { version: Date.parse("2026-10-01T00:00:00Z"), plan: { tier: "all", status: "active", periodEnd: new Date(Date.now() + 86_400_000).toISOString(), cancelAtPeriodEnd: false, product: "cyrus.plan.yakko" } }))).plan, "stale");
    assert.equal(await A.tierOf(u.id), "saka");
    await E.applyEntitlement(ent(u.id, { version: Date.parse("2026-10-11T00:00:00Z"), plan: { tier: null, status: "none", periodEnd: null, cancelAtPeriodEnd: false, product: null } }));
