    E.clearEntitlementCacheForTests();
    assert.equal(await A.tierOf(u.id), "free", "stale + no platform");
    const pulls: string[] = [];
    const fakePlatform = { as: (id: string) => ({ entitlements: async () => { pulls.push(id); return ent(u.id, { version: Date.parse("2026-10-10T00:00:00Z") }); } }) };
    const restore = H.setHost({ ...H.getHost(), platform: fakePlatform as never });
    try {
      E.clearEntitlementCacheForTests();
      assert.equal(await A.tierOf(u.id), "saka", "pulled and confirmed");
      assert.equal(await A.tierOf(u.id), "saka");
      assert.equal(pulls.length, 1, "then the 60 s cache / fresh confirmation serve it");
      const broken = { as: () => ({ entitlements: async () => { throw new Error("nxeon down"); } }) };
      H.setHost({ ...H.getHost(), platform: broken as never });
      await db.$executeRawUnsafe(`UPDATE "CyrusPlan" SET "updatedAt" = now() - interval '3 days' WHERE "userId" = $1`, u.id);
