    await st.record({ grantId: g1.id, client: "cyrus", userId: u.id, serverId: "srv_sql_1", call: "restart", path: null, opId: "op_sql_00001", mutation: true, status: 200, code: null, bytes: 0, at: now });
    assert.equal(await st.touched(g1.id, "op_sql_00001", "/opt/mc/plugins/A.jar"), true);
    assert.equal(await st.touched(g1.id, "op_sql_00001", "/opt/mc/plugins/B.jar"), false);
    assert.equal(await st.opDid(g1.id, "op_sql_00001", "restart"), true);
    assert.equal(await st.opDid(g1.id, "op_sql_00001", "*"), true);
    assert.equal(await st.countCalls(g1.id, "restart", new Date(now.getTime() - 1000)), 1);
    assert.equal(await st.bytesWritten(g1.id, new Date(now.getTime() - 1000)), 10);
    await st.idemPut("s", "k1", { requestHash: "h", status: 200, body: "{}" }, now);
    assert.deepEqual(await st.idemGet("s", "k1"), { requestHash: "h", status: 200, body: "{}" });
    const r = await st.revoke(g1.id, "user", now);
    assert.equal(r?.status, "revoked");
    assert.equal(await st.active("cyrus", u.id, "srv_sql_1"), null);
    const g3 = await st.upsert({ client: "cyrus", userId: u.id, serverId: "srv_sql_1", scopes: [], consentVersion: "t", now });
    assert.notEqual(g3.id, g1.id, "a new consent after revoke is a new grant (partial unique index)");
    assert.equal((await st.listForUser("cyrus", u.id, { includeRevoked: true })).length, 2);
    const ob = Ev.createSqlEventOutbox(sql);
    const e = Ev.grantChanged("grant.revoked", { id: g1.id, userId: u.id, serverId: "srv_sql_1", scopes: [] }, now);
    await ob.add(e); await ob.add(e);
    const due = await ob.due(new Date(now.getTime() + 1000), 10);
    assert.equal(due.filter((x) => x.id === e.id).length, 1);
    await ob.markFailed(e.id, { attempts: 1, nextAttemptAt: new Date(now.getTime() + 60_000), error: "HTTP 503" });
    assert.equal((await ob.due(new Date(now.getTime() + 1000), 10)).filter((x) => x.id === e.id).length, 0);
