// NXEON SIDE: the change WATCHER behind server.version_changed / server.deleted. Rather than hooking every place a
// server's version or existence can change (config editor, auto-update, reinstall, cancellation, admin delete,
// expiry...), the worker compares each connected server with what it saw last (on the grant row) every 2 minutes:
//   gone / DELETING / no longer the user's  -> server.deleted, and every grant on it is revoked (grant.revoked)
//   pinned version or loader moved          -> server.version_changed (Cyrus marks the mods built for the old one outdated)
// The first look only records. Inert unless CYRUS_SERVER_GRANTS=1 and CYRUS_PLATFORM_EVENTS=1. SERVER ONLY.
import { emitPlatformEvent, grantChanged, serverDeleted, serverVersionChanged } from "./events";
import { revokeServerGrants, type GrantStore } from "./grants";

export type WatchedServer = { id: string; userId: string; status: string; version: string | null; loader: string | null };
export type WatchDeps = { store: GrantStore; load(ids: string[]): Promise<WatchedServer[]>; emit?: typeof emitPlatformEvent; now?: () => Date; pageSize?: number };

export async function platformWatchSweep(d: WatchDeps): Promise<{ checked: number; changed: number; deleted: number }> {
  const emit = d.emit ?? emitPlatformEvent;
  const now = d.now ?? (() => new Date());
  const out = { checked: 0, changed: 0, deleted: 0 };
  const gone = new Set<string>();
  let after: string | null = null;
  for (let page = 0; page < 200; page++) {
    const grants = await d.store.activePage(after, d.pageSize ?? 200);
    if (!grants.length) break;
    after = grants[grants.length - 1].id;
    const servers = new Map((await d.load([...new Set(grants.map((g) => g.serverId))])).map((s) => [s.id, s]));
    for (const g of grants) {
      out.checked++;
      const s = servers.get(g.serverId);
      if (!s || s.status === "DELETING" || s.userId !== g.userId) {
        if (gone.has(`${g.serverId}:${g.userId}`)) continue;
        gone.add(`${g.serverId}:${g.userId}`);
        await emit(serverDeleted({ userId: g.userId, serverId: g.serverId, at: now() }));
        // a transfer to another account ends the grant too (it was the old owner's consent)
        out.deleted += await revokeServerGrants(d.store, g.serverId, s && s.userId !== g.userId ? "server_transferred" : "server_deleted", async (e) => { await emit(grantChanged(e.type, e.grant, e.at)); }, now());
        continue;
      }
      if (!g.seenAt) { await d.store.markSeen(g.id, { version: s.version, loader: s.loader, at: now() }); continue; }
      if (g.seenVersion !== s.version || g.seenLoader !== s.loader) {
        await emit(serverVersionChanged({ userId: g.userId, serverId: s.id, from: g.seenVersion, to: s.version, loader: s.loader, at: now() }));
        await d.store.markSeen(g.id, { version: s.version, loader: s.loader, at: now() });
        out.changed++;
      }
    }
  }
  return out;
}

/** The worker's sweep with Nxeon's database. */
export async function nxeonPlatformWatchSweep(env: Record<string, string | undefined> = process.env) {
  if (env.CYRUS_SERVER_GRANTS !== "1" || env.CYRUS_PLATFORM_EVENTS !== "1") return { checked: 0, changed: 0, deleted: 0 };
  const [{ db }, { pinnedVersion }, { grantStore }] = await Promise.all([import("../db"), import("../mods/facts"), import("./grants")]);
  return platformWatchSweep({
    store: await grantStore(env),
    load: async (ids) => (await db.server.findMany({ where: { id: { in: ids } }, select: { id: true, userId: true, status: true, gameConfig: true, gameVariant: true } }))
      .map((s) => ({ id: s.id, userId: s.userId, status: String(s.status), version: pinnedVersion(s.gameConfig), loader: s.gameVariant ?? null })),
  });
}
