// r38 (4): Nxeon -> Cyrus events (change watcher, grant events) and the Cyrus product emitters (Cyrus -> Nxeon).
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { applyConsent, createMemoryGrantStore } from "../lib/nxeon-platform/grants";
import { platformWatchSweep, type WatchedServer } from "../lib/nxeon-platform/watch";
import type { PlatformEnvelope } from "../lib/nxeon-platform/events";
import { createMemoryOutbox } from "../lib/cyrus/api/v1/webhooks";
import { emitBuildFinished, emitDeliveryResult, emitModPublished, setCyrusWebhookOutboxForTests } from "../lib/cyrus/api/v1/emit";
import { platformEventHandlers } from "../lib/cyrus/bridge/platform-event-handlers";

describe("change watcher (Nxeon)", () => {
  it("records first, then emits version changes once, and a deletion revokes every grant on the server", async () => {
    const store = createMemoryGrantStore();
    await applyConsent(store, { client: "cyrus", userId: "u1", serverIds: ["s1", "s2"], scopes: ["files.write.mods"], eligible: new Set(["s1", "s2"]) });
    const servers = new Map<string, WatchedServer>([["s1", { id: "s1", userId: "u1", status: "RUNNING", version: "1.21.10", loader: "paper" }], ["s2", { id: "s2", userId: "u1", status: "RUNNING", version: "1.21.11", loader: "paper" }]]);
    const events: PlatformEnvelope[] = [];
    const d = { store, load: async (ids: string[]) => ids.flatMap((id) => (servers.has(id) ? [servers.get(id)!] : [])), emit: async (e: PlatformEnvelope) => { events.push(e); return true; }, pageSize: 1 };
    assert.deepEqual(await platformWatchSweep(d), { checked: 2, changed: 0, deleted: 0 });
    assert.equal(events.length, 0, "first look only records");
    servers.set("s1", { ...servers.get("s1")!, version: "1.21.11" });
    assert.equal((await platformWatchSweep(d)).changed, 1);
    assert.equal((await platformWatchSweep(d)).changed, 0, "once");
    assert.deepEqual(events.map((e) => [e.type, e.data.serverId, e.data.from, e.data.to]), [["server.version_changed", "s1", "1.21.10", "1.21.11"]]);
    servers.set("s2", { ...servers.get("s2")!, status: "DELETING" });
    assert.equal((await platformWatchSweep(d)).deleted, 1);
    assert.deepEqual(events.slice(1).map((e) => e.type), ["server.deleted", "grant.revoked"]);
    assert.equal((await store.listForUser("cyrus", "u1")).map((g) => g.serverId).join(), "s1");
    // a transfer to another account ends the old owner's grant
    servers.set("s1", { ...servers.get("s1")!, userId: "u9" });
    await platformWatchSweep(d);
    assert.equal((await store.listForUser("cyrus", "u1")).length, 0);
    assert.equal((await store.latest("cyrus", "u1", "s1"))?.revokedBy, "server_transferred");
  });
});

describe("Cyrus product emitters", () => {
  const env = { CYRUS_API_V1_WEBHOOKS: "1", CYRUS_API_V1_WEBHOOK_URL: "https://nxeon.invalid/hook", CYRUS_API_V1_WEBHOOK_SECRET: "w".repeat(40) };
  it("are no-ops while webhooks are off", async () => {
    const ob = createMemoryOutbox(); setCyrusWebhookOutboxForTests(ob);
    await emitBuildFinished({ id: "b1", userId: "u1", status: "succeeded", errorCode: null });
    assert.equal(ob.rows.size, 0);
  });
  it("emit build.finished, mod.published (public pages only), install.result and delivery.rolledback", async () => {
    Object.assign(process.env, env);
    try {
      const ob = createMemoryOutbox(); setCyrusWebhookOutboxForTests(ob);
      await emitBuildFinished({ id: "b1", userId: "u1", status: "succeeded", errorCode: null, cyrus: { projectId: "p1" } });
      await emitBuildFinished({ id: "b1", userId: "u1", status: "succeeded", errorCode: null });
      await emitBuildFinished({ id: "b2", userId: "u1", status: "running", errorCode: null });
      await emitModPublished({ userId: "u1", slug: "magic-wand", buildId: "b1", version: null, visibility: "PRIVATE", publishedAt: null });
      await emitModPublished({ userId: "u1", slug: "magic-wand", buildId: "b1", version: null, visibility: "PUBLIC", publishedAt: new Date() });
      await emitDeliveryResult({ userId: "u1", jobId: "job1", result: { ok: false, outcome: "rolled_back", serverId: "s1", error: "the server did not come up", failedStep: "health" } });
      await emitDeliveryResult({ userId: "u1", jobId: "job2", result: { ok: true, outcome: "pending_restart", serverId: "s1" } });
      const rows = [...ob.rows.values()].map((r) => JSON.parse(r.body));
      assert.deepEqual(rows.map((r) => r.type), ["build.finished", "mod.published", "install.result", "delivery.rolledback", "install.result"]);
      assert.equal(rows[0].data.projectId, "p1");
      assert.equal(rows[3].data.failedStep, "health");
      assert.equal(rows[4].data.restartRequired, true);
    } finally { for (const k of Object.keys(env)) delete process.env[k]; setCyrusWebhookOutboxForTests(null); }
  });
});

describe("Cyrus event handlers", () => {
  it("handle every Nxeon event type", () => {
    const h = platformEventHandlers();
    for (const t of ["entitlement.changed", "server.version_changed", "server.deleted", "server.restarted", "grant.created", "grant.updated", "grant.revoked"]) assert.equal(typeof h[t], "function", t);
  });
});
