// Server half of "Create a mod for this server": the user's OWN server (ownership by the host's list), its version,
// loader, RAM and installed plugins, through the host seam only. Inside Nxeon: the host's records (incl. the Mods tab);
// a standalone Cyrus: the Platform API (grant needed; no grant = only what the URL can't leak: nothing). SERVER ONLY.
import { getHost } from "../host";
import { SERVER_PARAM_RE, type ServerContext } from "./server-context";

export async function loadServerContext(userId: string, serverId: string | null | undefined): Promise<ServerContext | null> {
  if (!serverId || !SERVER_PARAM_RE.test(serverId)) return null;
  const host = getHost();
  if (host.platform) {
    try {
      const api = host.platform.as(userId);
      const [s, inv] = await Promise.all([api.server(serverId), api.inventory(serverId)]);
      if (s.game !== "minecraft") return null;
      return { serverId, name: s.name, game: "minecraft", version: s.version, loader: s.loader, ramMB: s.ramMB, plugins: inv.records.filter((r) => r.status !== "REMOVED").map((r) => ({ name: r.name, version: r.version, via: r.via })) };
    } catch { return null; }
  }
  const row = (await host.servers.listForUser(userId)).find((s) => s.id === serverId);
  if (!row || host.servers.familyOf(row) !== "minecraft") return null;
  const plan = (row as { gamePlan?: { ramMB?: number | null } | null }).gamePlan;
  const records = (await host.records.allOnServer?.(serverId).catch(() => [])) ?? [];
  return {
    serverId, name: row.label || row.hostname, game: "minecraft", version: host.servers.pinnedVersion(row.gameConfig), loader: row.gameVariant, ramMB: plan?.ramMB ?? null,
    plugins: records.map((r) => ({ name: r.name, version: r.version, via: r.via })),
  };
}
