export type PreinstallFinding = { id: string; class: string; severity: "blocking" | "warning" | "info"; message: string };
export type PreinstallReport = {
  ok: boolean;
  blocking: PreinstallFinding[];
  warnings: PreinstallFinding[];
  /** Mods-tab installs that collide with this mod (the user resolves these in the Mods tab) */
  modsTab: { name: string; version: string | null; fileName: string | null }[];
  /** true when this server already runs an older version of THIS Cyrus mod (an update, not a conflict) */
  update: boolean;
  notChecked: string[];
  plugins: number;
};

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");

export async function preinstallReport(a: {
  fs: ReadOnlyServerFs; base: string; records: HostRecord[]; mcVersion: string | null;
  candidate: { jarName: string; bytes: Buffer; pluginName: string | null; namespace: string; projectId: string };
  /** paths (relative to base) of this mod's previous files, from its delivery record (excluded: an update replaces them) */
  ownFiles?: string[];
