  const mine = rep.findings.filter((f) => f.items.some((i) => i.mod === cand.id));
  const blocking: PreinstallFinding[] = mine.filter((f) => f.severity === "blocking").map((f) => ({ id: f.id, class: f.class, severity: "blocking", message: f.message }));
  const warnings: PreinstallFinding[] = mine.filter((f) => f.severity !== "blocking").map((f) => ({ id: f.id, class: f.class, severity: "warning", message: f.message })).slice(0, 50);
  const name = a.candidate.pluginName ? norm(a.candidate.pluginName) : null;
  const modsTab = a.records.filter((r) => r.via === "mods-tab" && r.status !== "REMOVED" && ((name && norm(r.name) === name) || (r.fileName && norm(r.fileName.replace(/\.jar$/i, "")) === norm(a.candidate.jarName.replace(/\.jar$/i, "")))));
  for (const r of modsTab) blocking.push({ id: `mods-tab:${norm(r.name)}`, class: "mods_tab_duplicate", severity: "blocking", message: `${r.name}${r.version ? ` ${r.version}` : ""} is installed from your Mods tab. Remove it there first, or the server would load two copies.` });
  const update = !!a.ownFiles?.length || a.records.some((r) => r.via === "cyrus" && !!name && norm(r.name) === name);
  return { ok: blocking.length === 0, blocking, warnings, modsTab: modsTab.map((r) => ({ name: r.name, version: r.version, fileName: r.fileName })), update, notChecked: rep.notChecked.slice(0, 30), plugins: inv.plugins.length };
}
