"use client";
// Cyrus r31: ship a saved designer revision. Build it (no AI model, no tokens; a settings-only edit repacks the jar with
// the new config.yml) -> poll the build -> send it to one server through the delivery enqueue API
// (/api/cyrus/delivery/v1, which re-checks ownership, compatibility and every acknowledgement server side) -> poll the
// delivery's status read model. Shown only when the host wired shipping AND CYRUS_DESIGNER_BUILDS=1.
import { useEffect, useState } from "react";
import type { Designer } from "./shared";
import { designerApi } from "./api";
import { DI } from "./icons";

type Ack = { id: string; text?: string; label?: string };
type Status = { state: string; pending: boolean; ok: boolean | null; headline: string; needsAttention: boolean; error: string | null };

async function j(url: string, init?: RequestInit) {
  const r = await fetch(url, { cache: "no-store", ...init, headers: init?.body ? { "content-type": "application/json" } : undefined });
  return { status: r.status, body: (await r.json().catch(() => ({}))) as Record<string, unknown> };
}

export function ShipBar({ d }: { d: Designer }) {
  const ship = d.view?.ship;
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [build, setBuild] = useState<{ id: string; status: string; error: string | null } | null>(ship?.build ?? null);
  const [server, setServer] = useState("");
  const [acks, setAcks] = useState<Ack[]>([]);
  const [acked, setAcked] = useState<string[]>([]);
  const [job, setJob] = useState<{ id: string; status: Status | null } | null>(null);
  useEffect(() => { setBuild(ship?.build ?? null); }, [ship?.build?.id, ship?.build?.status]); // eslint-disable-line react-hooks/exhaustive-deps

  // poll a running build
  useEffect(() => {
    if (!build || build.status === "succeeded" || build.status === "failed") return;
    const t = window.setTimeout(async () => {
      const r = await j(`/api/mod-builder/builds/${build.id}`);
      const b = r.body.build as { id: string; status: string; error: string | null } | undefined;
      if (b) setBuild({ id: b.id, status: b.status, error: b.error ?? null });
    }, 2500);
    return () => window.clearTimeout(t);
  }, [build]);
  // poll a delivery
  useEffect(() => {
    if (!job || (job.status && !job.status.pending)) return;
    const t = window.setTimeout(async () => {
      const r = await j(`/api/cyrus/delivery/v1/${job.id}`);
      if (r.body.status) setJob({ id: job.id, status: r.body.status as Status });
    }, 3000);
    return () => window.clearTimeout(t);
  }, [job]);

  if (!ship || !d.pid) return null;
  const pending = ship.pending;
  const doBuild = async () => {
    if (!pending || !d.pid) return;
    setBusy(true); setMsg(null);
    try { const r = await designerApi.build(d.pid, pending.revisionId); setBuild({ id: r.buildId, status: "queued", error: null }); }
    catch (e) { setMsg((e as Error).message); }
    finally { setBusy(false); }
  };
  const send = async () => {
    if (!build || !server) return;
    setBusy(true); setMsg(null);
    const r = await j("/api/cyrus/delivery/v1", { method: "POST", body: JSON.stringify({ op: "deliver", buildId: build.id, serverId: server, acked }) });
    setBusy(false);
    if (r.status === 409 && r.body.code === "needs_ack") { setAcks((r.body.acks as Ack[]) ?? []); setMsg(String(r.body.error)); return; }
    if (r.status >= 400) { setMsg(String(r.body.error ?? "The delivery was refused.")); return; }
    setAcks([]);
    setJob({ id: String(r.body.jobId), status: (r.body.status as Status) ?? null });
  };
  const seq = pending?.seq ?? (ship.build?.seq ?? null);
  const label = build ? (build.status === "succeeded" ? "Built" : build.status === "failed" ? "Build failed" : "Building…") : "Not built yet";
  return (
    <div className="dz-ship" role="region" aria-label="Ship this revision">
      <div className="dz-ship-row">
        <DI n="wrench" />
        <b>{seq ? `Revision ${seq}` : "Designer revision"}</b>
        <span className={`dz-chip ${build?.status === "succeeded" ? "ok" : build?.status === "failed" ? "err" : ""}`}>{label}</span>
        {(pending?.configOnly ?? ship.build?.configOnly) ? <span className="cys-hint">settings only: the plugin is repacked with the new config.yml, nothing is recompiled</span> : <span className="cys-hint">rebuilds the changed Java files</span>}
        <span className="sp" />
        {pending && !build ? <button type="button" className="cys-btn sm primary" disabled={busy} onClick={() => void doBuild()}>{busy ? "Starting…" : "Build this revision"}</button> : null}
        {build?.status === "failed" && pending ? <button type="button" className="cys-btn sm" disabled={busy} onClick={() => void doBuild()}>Try again</button> : null}
      </div>
      <p className="cys-hint" style={{ margin: "4px 0 0" }}>No AI model and no tokens: Cyrus compiles your saved designs exactly as they are.</p>
      {build?.status === "failed" && build.error ? <p className="dz-ship-err" role="alert">{build.error}</p> : null}
      {build?.status === "succeeded" && ship.deliveryOn ? (
        <div className="dz-ship-row" style={{ marginTop: 8 }}>
          <label className="cys-hint" htmlFor="dz-ship-srv">Send to</label>
          <select id="dz-ship-srv" className="cys-input sm" value={server} onChange={(e) => setServer(e.target.value)}>
            <option value="">Pick a server…</option>
            {ship.servers.map((s) => <option key={s.id} value={s.id} disabled={!s.compatible}>{s.name}{s.compatible ? "" : ` (${s.reason ?? "not compatible"})`}</option>)}
          </select>
          <button type="button" className="cys-btn sm primary" disabled={!server || busy || !!(job?.status?.pending ?? (job && !job.status))} onClick={() => void send()}>{busy ? "Sending…" : "Send to server"}</button>
        </div>
      ) : build?.status === "succeeded" ? <p className="cys-hint" style={{ margin: "6px 0 0" }}>Built. Sending to a server from here is not switched on yet; install it from the mod page.</p> : null}
      {acks.length ? (
        <ul className="dz-ship-acks">
          {acks.map((a) => (
            <li key={a.id}><label><input type="checkbox" checked={acked.includes(a.id)} onChange={(e) => setAcked((x) => (e.target.checked ? [...x, a.id] : x.filter((y) => y !== a.id)))} /> {a.text ?? a.label ?? a.id}</label></li>
          ))}
        </ul>
      ) : null}
      {msg ? <p className="dz-ship-err" role="alert">{msg}</p> : null}
      {job ? (
        <p className={`dz-ship-job ${job.status?.needsAttention ? "err" : job.status?.ok ? "ok" : ""}`} role="status">
          {job.status ? job.status.headline : "Queued…"}{job.status?.needsAttention ? " Contact support: the server may not be exactly as it was." : ""}
        </p>
      ) : null}
    </div>
  );
}

