import { getHost } from "@/lib/cyrus/host";
import { installReport, installTargets } from "@/lib/cyrus/bridge/install-report";

export const dynamic = "force-dynamic";

/**
 * "Install to server" (CYRUS_INSTALL_REPORT=1; otherwise 404). Mod Builder access required.
 *   GET                         -> { servers }: where this user can install (connected servers on a standalone Cyrus)
 *   POST { buildId, serverId }  -> { report }: the pre-install conflict report (read-only; Mods-tab duplicates block)
 */
const off = () => process.env.CYRUS_INSTALL_REPORT !== "1";
export async function GET() {
  if (off()) return new Response("Not found.", { status: 404 });
  const user = await getHost().builds.accessUser();
  if (!user) return Response.json({ error: "Not available." }, { status: 404 });
  return Response.json({ servers: await installTargets(user.id) }, { headers: { "cache-control": "no-store" } });
}
export async function POST(req: Request) {
  if (off()) return new Response("Not found.", { status: 404 });
  const user = await getHost().builds.accessUser();
  if (!user) return Response.json({ error: "Not available." }, { status: 404 });
  const rl = getHost().rateLimit.check(`cyrus-install-report:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return Response.json({ error: "Too many checks, try again in a minute." }, { status: 429 });
  const b = (await req.json().catch(() => ({}))) as { buildId?: unknown; serverId?: unknown };
  if (typeof b.buildId !== "string" || typeof b.serverId !== "string" || !/^[A-Za-z0-9_-]{4,64}$/.test(b.serverId)) return Response.json({ error: "Bad request." }, { status: 400 });
  const r = await installReport(user.id, b.buildId, b.serverId);
  return r.ok ? Response.json({ report: r.report }) : Response.json({ error: r.error }, { status: r.status });
}
EOF
