"use client";
// "Install to server": the pre-install conflict report for the picked server (CYRUS_INSTALL_REPORT; a 404 = off, shows
// nothing). Blocking findings, including a duplicate from the user's own Mods tab, hold the Send button.
import { useEffect, useState } from "react";

type Finding = { id: string; class: string; severity: string; message: string };
type Report = { ok: boolean; blocking: Finding[]; warnings: Finding[]; modsTab: { name: string }[]; update: boolean; notChecked: string[]; plugins: number };

export function InstallReport({ buildId, serverId, onVerdict }: { buildId: string; serverId: string; onVerdict: (blocked: boolean) => void }) {
  const [state, setState] = useState<{ loading: boolean; report: Report | null; error: string | null }>({ loading: false, report: null, error: null });
  useEffect(() => {
    if (!serverId) { setState({ loading: false, report: null, error: null }); onVerdict(false); return; }
    let live = true;
    setState({ loading: true, report: null, error: null });
    void fetch("/api/cyrus/install-report", { method: "POST", cache: "no-store", headers: { "content-type": "application/json" }, body: JSON.stringify({ buildId, serverId }) })
      .then(async (r) => {
        if (!live) return;
        if (r.status === 404 && !(await r.clone().json().catch(() => null))) { setState({ loading: false, report: null, error: null }); onVerdict(false); return; }
        const j = await r.json().catch(() => ({}));
        if (!r.ok) { setState({ loading: false, report: null, error: j.error ?? `Could not check (${r.status}).` }); onVerdict(false); return; }
        setState({ loading: false, report: j.report, error: null });
        onVerdict(!j.report.ok);
      })
      .catch(() => { if (live) { setState({ loading: false, report: null, error: "Could not check this server." }); onVerdict(false); } });
    return () => { live = false; };
  }, [buildId, serverId]); // eslint-disable-line react-hooks/exhaustive-deps
  if (!serverId) return null;
  if (state.loading) return <p className="cys-hint" role="status">Checking what is already on that server…</p>;
