// Server half of "Install to server": the servers Cyrus may install to and the pre-install conflict report for one
// (build, server). Inside Nxeon: the user's own Minecraft servers and the host's file session; a standalone Cyrus: the
// servers the user CONNECTED (Platform API grants; unconnected ones carry a Connect link) and PlatformTxnFs.
// Read-only: nothing is written. SERVER ONLY. HOST SEAM: no platform imports.
import { readFile } from "node:fs/promises";
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import { projectForRootBuild } from "../engine-core/store";
import { readRecord, recordPath } from "../delivery/plan";
import { PlatformTxnFs } from "../host/platform-session";
import { preinstallReport, type HostRecord, type PreinstallReport } from "./preinstall";

export type InstallTarget = { id: string; name: string; version: string | null; connected: boolean; canInstall: boolean; reason: string | null };

export async function installTargets(userId: string): Promise<InstallTarget[]> {
  const host = getHost();
  if (host.platform) {
    const servers = await host.platform.as(userId).servers().catch(() => []);
    return servers.map((s) => {
      const can = s.grant.scopes.includes("files.write.mods");
      return { id: s.id, name: s.name, version: s.version, connected: true, canInstall: can && s.supported && s.status === "RUNNING", reason: !can ? "connected without permission to install files" : !s.supported ? s.reason : s.status !== "RUNNING" ? `server is ${s.status.toLowerCase()}` : null };
    });
  }
  return (await host.servers.listForUser(userId)).filter((s) => host.servers.familyOf(s) === "minecraft").map((s) => ({
    id: s.id, name: s.label || s.hostname, version: host.servers.pinnedVersion(s.gameConfig), connected: true, canInstall: s.status === "RUNNING", reason: s.status === "RUNNING" ? null : `server is ${s.status.toLowerCase()}`,
  }));
}

export async function installReport(userId: string, buildId: string, serverId: string): Promise<{ ok: true; report: PreinstallReport } | { ok: false; status: number; error: string }> {
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!b || b.userId !== userId) return { ok: false, status: 404, error: "No such build." };
  if (b.status !== "succeeded" || !b.jarPath || !b.jarName) return { ok: false, status: 409, error: "The build has no finished plugin yet." };
  const bytes = await readFile(b.jarPath).catch(() => null);
  if (!bytes) return { ok: false, status: 409, error: "The plugin file is not available." };
  const proj = await projectForRootBuild(b.rootBuildId ?? b.id).catch(() => null);
  const host = getHost();
  let fs: { stat: PlatformTxnFs["stat"]; readFile: PlatformTxnFs["readFile"]; list: PlatformTxnFs["list"] }, base: string, records: HostRecord[], close: (() => void) | undefined, mcVersion: string | null;
  if (host.platform) {
    const api = host.platform.as(userId);
    try {
      const [s, inv] = await Promise.all([api.server(serverId), api.inventory(serverId)]);
      fs = new PlatformTxnFs(api, serverId); base = inv.layout.base; records = inv.records; mcVersion = s.version;
    } catch (e) { return { ok: false, status: 403, error: `Connect this server to Cyrus first (${(e as Error).message.slice(0, 120)}).` }; }
  } else {
    const f = await host.servers.openFiles(userId, serverId);
    if (!f) return { ok: false, status: 404, error: "No such server." };
    fs = f.fs; base = f.base; close = f.close; mcVersion = null;
    records = (await host.records.allOnServer?.(serverId).catch(() => [])) ?? [];
  }
  try {
    const prev = proj ? readRecord(await fs.readFile(recordPath(proj.id), 1024 * 1024).catch(() => null)) : null;
    const ownFiles = [prev?.jar?.target, ...(prev?.datapacks.map((d) => d.target) ?? [])].filter((p): p is string => !!p).map((p) => p.slice(base.length + 1));
    const report = await preinstallReport({ fs, base, records, mcVersion: mcVersion ?? b.mcVersion, ownFiles, candidate: { jarName: b.jarName, bytes, pluginName: b.pluginName, namespace: proj?.namespace ?? "cyrus", projectId: proj?.id ?? b.id } });
    return { ok: true, report };
  } finally { close?.(); }
}
