// r38 (6): LOCAL TWO-SERVICE E2E. A fake Nxeon serves the REAL Platform API over HTTP (grants, path policy, hash
// preconditions, budgets, audit) on a fake guest dir; Cyrus runs its REAL delivery orchestrator (journal, health,
// rollback) through platformDeliveryHost, i.e. only through the primitives. Scenarios: fresh install, grant revoked
// MID-INSTALL (the rollback runs in rollback-only mode and restores the exact bytes), a broken pack rolled back after
// a real restart through the budgeted primitive, and no grant / read-only grant refusals.
//   scripts/devhost test test/cyrus-bridge-e2e.test.ts
import "./_cyrus-server-only-shim";
import { describe, it, afterEach } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { deliverMod } from "../lib/cyrus/delivery/orchestrator";
import type { ModRelease } from "../lib/cyrus/delivery/types";
import { platformDeliveryHost } from "../lib/cyrus/host/platform-session";
import { revokeGrant } from "../lib/nxeon-platform/grants";
import type { PlatformFs } from "../lib/nxeon-platform/api";
import { zip } from "../lib/cyrus/textures/zip";
import { dpZip, goodMod, jarOf, rpZip } from "./_cyrus-modfixture";
import { FakeServer, seedServer, BROKEN_MARKER, h } from "./_cyrus-delivery-fakehost";
import { fakePlatform, SERVER, USER, type FakePlatform } from "./_cyrus-platform-fake";

const NS = "nx_bridge01";
const sha1 = (b: Buffer) => createHash("sha1").update(b).digest("hex");
const mod = goodMod(NS, "alpha");
const JAR = jarOf(mod), RP = rpZip(mod), DP = dpZip(mod);
const BROKEN = zip([{ path: "pack.mcmeta", data: Buffer.from('{"pack":{"pack_format":94,"description":"broken"}}') }, { path: BROKEN_MARKER, data: Buffer.from("{}") }]);
const ALL = ["files.write.mods", "server.reload", "server.restart", "logs.read.tail", "pack.set"];
const release = (over: Partial<ModRelease> = {}): ModRelease => ({
  projectId: "cp_bridge01", revisionId: "rev_1", namespace: NS, mcVersion: "1.21.11", label: "NxAlpha",
  plugin: { pluginName: mod.name, jarName: `${mod.name}-1.0.0.jar`, sha256: h(JAR), bytes: JAR },
  pack: { sha1: sha1(RP), zip: RP, prompt: "NxAlpha uses custom textures.", required: false },
  datapacks: [{ name: "alpha", zip: DP, sha256: h(DP), apply: "reload" }], creatures: [], ...over,
});
const open: FakePlatform[] = [];
afterEach(() => { while (open.length) open.pop()!.close(); });

/** A fake Nxeon whose guest fs can run a hook before the Nth mutation (to revoke mid-install). */
async function world(o: { beforeWrite?: (n: number, fx: FakePlatform) => Promise<void> } = {}) {
  const srv = new FakeServer(); seedServer(srv);
  let n = 0;
  let fxRef: FakePlatform | null = null;
  const tick = async () => { n++; if (o.beforeWrite && fxRef) await o.beforeWrite(n, fxRef); };
  const raw = srv.raw;
  const fs: PlatformFs = {
    stat: (p) => raw.stat(p), readFile: (p, m) => raw.readFile(p, m), list: (d) => raw.list(d),
    writeFile: async (p, d) => { await tick(); return raw.writeFile(p, d); }, mkdirp: async (p) => { await tick(); return raw.mkdirp(p); },
    rename: async (a, b) => { await tick(); return raw.rename(a, b); }, remove: async (p) => { await tick(); return raw.remove(p); }, copy: async (a, b) => { await tick(); return raw.copy(a, b); },
  };
  const fx = await fakePlatform({ srv, deps: { open: async (id) => (id === SERVER ? { fs, layout: { base: "/opt/mc", levelName: "world", clientStateDir: "/root/.nxeon-cyrus" } } : null) } });
  fxRef = fx; open.push(fx);
  const fake = srv.host();
  const host = (opId?: string) => platformDeliveryHost({ api: fx.client.as(USER), serverId: SERVER, opId, managed: fake.managed, packs: fake.packs, env: fake.env });
  return { fx, srv, host, writes: () => n };
}

describe("two-service e2e: Cyrus delivers through the Nxeon Platform API", () => {
  it("fresh install: every file through the primitives, restart through the budget, healthy, audited", async () => {
    const { fx, srv, host } = await world();
    await fx.grant(ALL);
    const r = await deliverMod(SERVER, release(), host("op_e2e_fresh01"));
    assert.equal(r.outcome, "delivered", JSON.stringify(r.steps, null, 1) + r.error);
    assert.ok(r.health?.ok); assert.equal(srv.restarts, 1);
    assert.ok(srv.files("opt/mc/plugins").includes("NxAlpha-1.0.0.jar"));
    assert.ok(srv.files("opt/mc/world/datapacks").includes(`nxeon-${NS}-alpha.zip`));
    assert.ok(srv.read("root/.nxeon-cyrus/deliveries/cp_bridge01.json"));
    const calls = fx.store.calls.filter((c) => c.opId === "op_e2e_fresh01");
    assert.ok(calls.some((c) => c.call === "restart" && c.status === 200));
    assert.ok(calls.filter((c) => c.mutation).every((c) => c.grantId && c.userId === USER && c.serverId === SERVER));
    assert.ok(!calls.some((c) => c.code === "path_refused" || c.code === "precondition_failed"), "the orchestrator stays inside the allow-list");
    const again = await deliverMod(SERVER, release(), host());
    assert.equal(again.outcome, "unchanged");
  });

  it("grant revoked MID-INSTALL: forward calls stop, the rollback undoes exactly this operation's changes, then nothing more", async () => {
    let gid = "";
    const { fx, srv, host } = await world({ beforeWrite: async (n, f) => { if (n === 6 && gid) await revokeGrant(f.store, { userId: USER, grantId: gid }); } });
    gid = await fx.grant(ALL);
    const before = srv.tree({ excludeJournal: true });
    const refs = JSON.stringify([...srv.refs.entries()]);
    const r = await deliverMod(SERVER, release(), host("op_e2e_revoke1"));
    assert.equal(r.ok, false);
    assert.equal(r.outcome, "rolled_back", `${r.outcome} ${r.error} ${JSON.stringify(r.rollback)}`);
    assert.equal(r.rollback?.ok, true, JSON.stringify(r.rollback));
    assert.equal(srv.tree({ excludeJournal: true }), before, "exact previous bytes");
    assert.equal(JSON.stringify([...srv.refs.entries()]), refs);
    const calls = fx.store.calls.filter((c) => c.opId === "op_e2e_revoke1");
