    const before = srv.tree();
    assert.equal((await deliverMod(SERVER, release(), host())).ok, false);
    await fx.grant([]);
    const r = await deliverMod(SERVER, release(), host());
    assert.equal(r.ok, false); assert.match(String(r.error), /files\.write\.mods|install/i);
    assert.equal(writes(), 0); assert.equal(srv.tree(), before);
  });
});
