        return { online: r.checks.find((x) => x.id === "boot_done")?.status === "pass", answered, players: 0, maxPlayers: 10, datapacksLoaded: /: ok/.test(dl) ? lastDatapacks.map((n) => `file/${n}.zip`) : [] };
      },
    },
    open: async (id) => (id === SERVER ? { fs, layout: { base: BASE, levelName: "world", clientStateDir: "/root/.nxeon-cyrus" } } : null),
    records: async () => [],
    power: {
      async restart() {
        const plugins = readdirSync(local("opt/mc/plugins")).filter((n) => n.endsWith(".jar")).sort().map((n) => ({ localPath: local(`opt/mc/plugins/${n}`) }));
        const datapacks = readdirSync(local("opt/mc/world/datapacks")).filter((n) => n.endsWith(".zip")).sort().map((n) => ({ name: n.replace(/\.zip$/, "").toLowerCase().replace(/[^a-z0-9_.-]/g, "-").slice(0, 64), localPath: local(`opt/mc/world/datapacks/${n}`) }));
        const files: TestFlightSpec["files"] = [];
        try { files.push({ path: "plugins/NxeonPackLoader/packs.json", content: readFileSync(local("opt/mc/plugins/NxeonPackLoader/packs.json"), "utf8") }); } catch { /* none */ }
        const names = plugins.map((p) => inspectJar(path.basename(p.localPath), `plugins/${path.basename(p.localPath)}`, readFileSync(p.localPath), { bytecode: false }).descriptor?.name).filter((n): n is string => !!n);
        lastDatapacks = datapacks.map((d) => d.name);
        const t0 = Date.now();
        try {
          last = await fly({ version: VERSION, plugins, datapacks, ...(files.length ? { files } : {}), rcon: [{ id: "answers", command: "list", required: false }], timeouts: { bootSec: 200, totalSec: 480 } });
        } catch (e) { last = null; return { ok: false, error: (e as Error).message }; }
        const r = last.report;
        const enabled = (r.checks.find((c) => c.id === "plugins_enabled")?.evidence ?? []).map((l) => /^(\S+): enabled/.exec(l)?.[1]).filter((n): n is string => !!n);
        const logBad = r.checks.find((c) => c.id === "startup_log_clean");
        const cameUp = r.checks.find((c) => c.id === "boot_done")?.status === "pass";
        // the guest's latest.log as Nxeon would read it after this boot (from the real flight's evidence)
        writeFileSync(local("opt/mc/logs/latest.log"), [`[00:00:00 INFO]: This server is running Paper version ${r.engine?.paper ?? VERSION} (MC: ${VERSION})`, ...enabled.map((n) => `[00:00:01 INFO]: [${n}] Enabling ${n} v1`), ...(logBad?.status === "fail" ? logBad.evidence.filter((l) => /ERROR|Exception|Failed/.test(l)).slice(0, 10).map((l) => `[00:00:02 ERROR]: ${l}`) : []), ...(cameUp ? [`[00:00:03 INFO]: Done (${((r.bootMs ?? 0) / 1000).toFixed(1)}s)! For help, type "help"`] : [])].join("\n") + "\n");
        flights.push({ at: new Date().toISOString(), plugins: names, datapacks: lastDatapacks, overall: last.summary.overall, checks: r.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 6) })), bootMs: r.bootMs, peakRssKb: r.peakRssKb, wallMs: Date.now() - t0, runId: r.runId, paper: r.engine?.paper ?? null });
        console.log(`  flight: ${last.summary.overall} (${r.checks.map((c) => `${c.id}=${c.status}`).join(" ")})`);
        return { ok: true, cameUp };
      },
      async console(_id, command) { return { ok: false, error: `no live console in a Test Flight run (${command})` }; },
    },
    rateLimit: () => ({ ok: true, retryAfterSec: 0 }),
  });
  const http = createServer(async (req, res) => {
    const chunks: Buffer[] = [];
    for await (const c of req) chunks.push(c as Buffer);
    const r = await api.handle(new Request(`http://127.0.0.1${req.url}`, { method: req.method, headers: req.headers as Record<string, string>, body: req.method === "POST" ? Buffer.concat(chunks) : undefined }));
    res.writeHead(r.status, Object.fromEntries(r.headers)); res.end(Buffer.from(await r.arrayBuffer()));
  });
  await new Promise<void>((r) => http.listen(0, "127.0.0.1", () => r()));
  const baseUrl = `http://127.0.0.1:${(http.address() as AddressInfo).port}${PLATFORM_API_PREFIX}`;

  // ---------------- Cyrus
  const client = createPlatformClient({ baseUrl, keyId, secret, signingKey: privateKey, timeoutMs: 600_000 });
  const loader = readFileSync(`${FX}/NxeonPackLoader-0.1.0.jar`);
  const refs = new Map<string, string[]>();
  const writeJar = async (f: TxnFs, target: string, data: Buffer) => { await f.writeFile(`${target}.nxeon-part`, data); await f.rename(`${target}.nxeon-part`, target); };
  const managed: ManagedPort = {
    async ensure({ key, dependent, fs: f }) {
      if (key !== "nxeon-pack-loader") return { ok: false, error: `${key} is not available in this run` };
      const d = refs.get(key) ?? [];
      if (!d.length) await writeJar(f, `${BASE}/plugins/NxeonPackLoader-0.1.0.jar`, loader);
      refs.set(key, [...new Set([...d, dependent])].sort());
      return { ok: true, action: d.length ? (d.includes(dependent) ? "already" : "ref_added") : "installed", pluginName: "NxeonPackLoader" };
    },
    async release({ key, dependent, fs: f }) { const d = (refs.get(key) ?? []).filter((x) => x !== dependent); refs.set(key, d); if (!d.length) { await f.remove(`${BASE}/plugins/NxeonPackLoader-0.1.0.jar`); return { ok: true, action: "removed" }; } return { ok: true, action: "ref_dropped" }; },
    async snapshot() { return JSON.stringify([...refs.entries()]); },
    async restore(_s, snap) { refs.clear(); for (const [k, v] of JSON.parse(String(snap))) refs.set(k, v); return { ok: true }; },
  };
  const env = { CYRUS_DELIVERY: "1", CYRUS_MANAGED_PLUGINS_REAL: "1", CYRUS_DATAPACK_DELIVERY_REAL: "1", CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1" };
  const host = (opId: string) => platformDeliveryHost({ api: client.as(USER), serverId: SERVER, opId, managed, env, packs: { async publish(_z, sha1) { return { url: `https://packs.example.invalid/p/${sha1}.zip` }; } } });

  const jar = readFileSync(`${FX}/TfItemModel-1.0.0.jar`);
  const pluginName = inspectJar("TfItemModel-1.0.0.jar", "plugins/TfItemModel-1.0.0.jar", jar, { bytecode: false }).descriptor?.name ?? "TfItemModel";
  const dp = buildDataPack(JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-datapack/showcase.json"), "utf8")), { version: VERSION, namespace: NS });
  if (!dp.ok) throw new Error(`showcase data pack: ${dp.errors.join("; ")}`);
  const fakePack = zip([{ path: "pack.mcmeta", data: Buffer.from('{"pack":{"pack_format":75,"description":"r38"}}') }]);
  const rel = (over: Partial<ModRelease>): ModRelease => ({
    projectId: "cp_r38real01", revisionId: "rev_1", namespace: NS, mcVersion: VERSION, label: pluginName,
    plugin: { pluginName, jarName: "TfItemModel-1.0.0.jar", sha256: h(jar), bytes: jar },
    pack: { sha1: createHash("sha1").update(fakePack).digest("hex"), zip: fakePack, prompt: "r38 real run pack.", required: false },
    datapacks: [{ name: dp.pack.name, zip: dp.pack.zip, sha256: dp.pack.sha256, apply: dp.pack.apply }], creatures: [], ...over,
  });
  try {
    grantId = (await applyConsent(store, { client: "cyrus", userId: USER, serverIds: [SERVER], scopes: ["files.write.mods", "server.reload", "server.restart", "logs.read.tail", "pack.set"], eligible: new Set([SERVER]) }) as { ok: true; grants: { id: string }[] }).grants[0].id;
    console.log(`A: fresh delivery on ${VERSION} through the Platform API`);
    const a = await deliverMod(SERVER, rel({}), host("op_r38_real_A1"));
    const callsA = store.calls.filter((c) => c.opId === "op_r38_real_A1");
    S.A = { ...brief(a), files: readdirSync(local("opt/mc/plugins")).sort().concat(readdirSync(local("opt/mc/world/datapacks")).sort()), apiCalls: callsA.length, mutations: callsA.filter((c) => c.mutation).length, refused: callsA.filter((c) => c.status >= 400).map((c) => `${c.call}:${c.code}:${c.path}`), restarts: callsA.filter((c) => c.call === "restart").map((c) => c.status) };
    console.log(`A: ${a.outcome}`); save();
    if (!a.ok) throw new Error("A failed; stopping");

    console.log("R: the user revokes the grant in the middle of an update");
    const before = treeHash(root);
    writes = 0; revokeAt = 5;
    const r = await deliverMod(SERVER, rel({ revisionId: "rev_2", datapacks: [] }), host("op_r38_real_R1"));
    const after = treeHash(root);
    const callsR = store.calls.filter((c) => c.opId === "op_r38_real_R1");
    S.R = { ...brief(r), exactRestore: before === after, refusedForward: callsR.filter((c) => c.code === "grant_revoked").length, rollbackOnlyRefusals: callsR.filter((c) => c.code === "rollback_only").length, refs: [...refs.entries()] };
    console.log(`R: ${r.outcome}; exact restore: ${before === after}`); save();
  } finally {
    out.flights = flights;
    save();
    api.close(); http.close();
    rmSync(root, { recursive: true, force: true });
  }
  if (!process.argv.includes("--out")) console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

